package io.droptracker;

import io.droptracker.models.EventDisplayMode;
import io.droptracker.models.EventHudDetail;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

/**
 * Four sections: what we track, when we screenshot, events, and everything
 * advanced. Clan Chat keeps its own section because it relays other people's
 * messages and deserves to stay obvious.
 * <p>
 * <b>keyName is a data migration.</b> A player's stored value is looked up by
 * keyName, so renaming one silently resets that setting for everybody who had
 * configured it. Section, position, display name and description are all free
 * to change; keyName is not. Options retired from the UI keep their keyName and
 * become {@code hidden = true} so the value still applies and existing code
 * still reads it.
 */
@ConfigGroup(DropTrackerConfig.GROUP)
public interface DropTrackerConfig extends Config {

    String GROUP = "droptracker";

    // ==================== Tracking ====================

    @ConfigSection(
        name = "Tracking",
        description = "What the DropTracker records and sends for you",
        position = 1,
        closedByDefault = false
    )
    String trackingSection = "Tracking";

    @ConfigItem(
        keyName = "lootEmbeds",
        name = "Drops",
        description = "Should we send your drops to the DropTracker?",
        position = 1,
        section = trackingSection
    )
    default boolean lootEmbeds() {
        return true;
    }

    @ConfigItem(
        keyName = "pbEmbeds",
        name = "Personal Bests",
        description = "Do you want DropTracker to track your PBs?",
        position = 2,
        section = trackingSection
    )
    default boolean pbEmbeds() {
        return true;
    }

    @ConfigItem(
        keyName = "clogEmbeds",
        name = "Collection Logs",
        description = "<html>Should we send new collection log slot unlocks to the DropTracker?<br>"
            + "<b>Note</b>: Requires Collection Log Notification and popup Enabled in OSRS settings</html>",
        position = 3,
        section = trackingSection
    )
    default boolean clogEmbeds() {
        return true;
    }

    @ConfigItem(
        keyName = "caEmbeds",
        name = "Combat Achievements",
        description = "Should we send your Combat Achievements to the DropTracker?",
        position = 4,
        section = trackingSection
    )
    default boolean caEmbeds() {
        return true;
    }

    @ConfigItem(
        keyName = "petEmbeds",
        name = "Pets",
        description = "Do you want DropTracker to track your Pets?",
        position = 5,
        section = trackingSection
    )
    default boolean petEmbeds() {
        return true;
    }

    @ConfigItem(
        keyName = "levelEmbed",
        name = "Levels",
        description = "Do you want to send level gains to the DropTracker",
        position = 6,
        section = trackingSection
    )
    default boolean levelEmbed() {
        return true;
    }

    @ConfigItem(
        keyName = "xpMilestoneEmbeds",
        name = "XP Milestones",
        description = "<html>Send a notification when a level-99 skill crosses an XP milestone.<br />"
            + "Your group's settings determine which milestones are announced (default: every 25M XP).</html>",
        position = 7,
        section = trackingSection
    )
    default boolean xpMilestoneEmbeds() {
        return true;
    }

    @ConfigItem(
        keyName = "questsEmbed",
        name = "Quests",
        description = "Do you want to send quest completions to the DropTracker?",
        position = 8,
        section = trackingSection
    )
    default boolean questsEmbed() {
        return true;
    }

    @ConfigItem(
        keyName = "deathEmbeds",
        name = "Deaths",
        description = "Do you want to send player deaths to the DropTracker?",
        position = 9,
        section = trackingSection
    )
    default boolean deathEmbeds() {
        return true;
    }

    @ConfigItem(
        keyName = "diaryEmbeds",
        name = "Achievement Diaries",
        description = "Do you want to send achievement diary completions to the DropTracker?",
        position = 10,
        section = trackingSection
    )
    default boolean diaryEmbeds() {
        return true;
    }

    @ConfigItem(
        keyName = "trackActivities",
        name = "Activity Tracking",
        description = "<html>Track items from activities RuneLite's loot tracker misses:<br />"
            + "deep sea trawling catches.</html>",
        position = 11,
        section = trackingSection
    )
    default boolean trackActivities() {
        return true;
    }

    @ConfigItem(
            keyName = "relayClanBroadcasts",
            name = "Clan Broadcasts",
            description = "<html>Send your clan's broadcast messages (drops, pets, collection log slots) to the<br />"
                    + "DropTracker so clanmates WITHOUT the plugin can be tracked by your group.<br />"
                    + "One relaying member covers the whole clan; duplicates are handled server-side.</html>",
            position = 12,
            section = trackingSection
    )
    default boolean relayClanBroadcasts() {
        return false;
    }

    @ConfigItem(
            keyName = "relayClanChat",
            name = "Relay clan chat to Discord",
            description = "<html>Mirror your clan chat into your group's configured Discord bridge channel.<br />"
                    + "Only takes effect for groups that enabled the clan chat bridge on droptracker.io.</html>",
            position = 13,
            section = trackingSection
    )
    default boolean relayClanChat() {
        return false;
    }

    // ==================== Screenshots ====================

    @ConfigSection(
        name = "Screenshots",
        description = "When the plugin attaches a screenshot to a submission",
        position = 2,
        closedByDefault = false
    )
    String screenshotSection = "Screenshots";

    @ConfigItem(
        keyName = "screenshots",
        name = "Enable Screenshots",
        description = "<html>Attach screenshots to the things you track above.<br />"
            + "Turn this off to submit everything without images.</html>",
        position = 1,
        section = screenshotSection
    )
    default boolean screenshots() {
        return true;
    }

    @ConfigItem(
        keyName = "screenshotValue",
        name = "Loot screenshot value",
        description = "What minimum value would you like drops to be sent with an attached image for?",
        position = 2,
        section = screenshotSection
    )
    default int screenshotValue() {
        return 250000;
    }

    @ConfigItem(
        keyName = "screenshotUntradeables",
        name = "Screenshot untradeables",
        description = "<html>Take screenshots of notable untradeable drops (champion scrolls, boss heads,<br />"
            + "raid kits, etc.) even though they arrive with no GE value.<br />"
            + "Note: with the API enabled, an item required by one of your active events<br />"
            + "is always screenshotted for proof, regardless of this setting.</html>",
        position = 3,
        section = screenshotSection
    )
    default boolean screenshotUntradeables() {
        return true;
    }

    @ConfigItem(
        keyName = "minLevelToScreenshot",
        name = "Minimum level to screenshot",
        description = "<html>Only screenshot level-ups at or above this level.<br />"
            + "Levels below it are still tracked and sent - just without an image.</html>",
        position = 4,
        section = screenshotSection
    )
    default int minLevelToScreenshot() {
        return 75;
    }

    @ConfigItem(
        keyName = "hideWhispers",
        name = "Hide PMs",
        description = "Do you want your private chat to be hidden when screenshots are taken?",
        position = 5,
        section = screenshotSection
    )
    default boolean hideDMs() {
        return false;
    }

    @ConfigItem(
        keyName = "compressImages",
        name = "Compress screenshots",
        description = "<html>Convert large screenshots to JPEG before sending.<br />"
            + "Turn this off to always send lossless PNG, whatever the size.</html>",
        position = 6,
        section = screenshotSection
    )
    default boolean compressImages() {
        return true;
    }

    @ConfigItem(
        keyName = "imageCompressionThresholdKb",
        name = "Compression threshold (KB)",
        description = "<html>Maximum screenshot size (in KB) before JPEG compression is applied.<br>"
            + "Screenshots smaller than this threshold are sent as lossless PNG.<br>"
            + "Set to 0 to always compress to JPEG.</html>",
        position = 7,
        section = screenshotSection
    )
    default int imageCompressionThresholdKb() {
        return 1500;
    }

    // ==================== Events ====================

    @ConfigSection(
        name = "Events",
        description = "In-game notifications and HUD for DropTracker events (requires the API)",
        position = 3,
        closedByDefault = false
    )
    String eventSection = "Events";

    @ConfigItem(
        keyName = "eventNotifications",
        name = "Receive notifications",
        description = "<html>Show in-game notifications about your DropTracker events<br />"
            + "(task completions, lead changes, board turns...).<br />"
            + "Requires 'Use API Connections'. Fine-tune which types you receive on the website.</html>",
        position = 1,
        section = eventSection
    )
    default boolean eventNotifications() {
        return true;
    }

    @ConfigItem(
        keyName = "eventDisplayMode",
        name = "Display type",
        description = "<html>How event notifications appear:<br />"
            + "<b>Chat messages only</b> - lines in your chatbox.<br />"
            + "<b>Chat + text pop-ups</b> - also shows brief on-screen pop-ups.<br />"
            + "<b>Enhanced display (HUD)</b> - also shows a movable overlay with your<br />"
            + "current task, progress and team standing (hold Alt to drag it).</html>",
        position = 2,
        section = eventSection
    )
    default EventDisplayMode eventDisplayMode() {
        return EventDisplayMode.POPUP;
    }

    @ConfigItem(
        keyName = "eventTaskProgressNotifications",
        name = "Task progress notifications",
        description = "<html>Notify when teammates progress (not just complete) your team's tasks.<br />"
            + "The chattiest type - this is the mute switch for it.</html>",
        position = 3,
        section = eventSection
    )
    default boolean eventTaskProgressNotifications() {
        return true;
    }

    @ConfigItem(
        keyName = "eventHudDetail",
        name = "HUD details",
        description = "<html>Enhanced display only:<br />"
            + "<b>Compact</b> - task icon, name and progress.<br />"
            + "<b>Detailed</b> - adds your team name, rank and score.</html>",
        position = 4,
        section = eventSection
    )
    default EventHudDetail eventHudDetail() {
        return EventHudDetail.DETAILED;
    }


    // ==================== Advanced ====================

    @ConfigSection(
        name = "Advanced",
        description = "API connection, account sync and debugging",
        position = 5,
        closedByDefault = true
    )
    String advancedSection = "Advanced";

    @ConfigItem(
        keyName = "useApi",
        name = "Use API",
        description = "<html>Enables external connections to the DropTracker database, for panel data.<br />"
            + "<b>Note</b>: The API is currently <b>required</b> for participation in events!</html>",
        position = 1,
        section = advancedSection,
        warning = "<html><b>WARNING</b>: In order to connect to the DropTracker API,<br>"
            + "your client must make out-going connections to the developer's server.<br>"
            + "This server can not be verified by the RuneLite developers.<br>"
            + "<b>Are you sure?</b></html>"
    )
    default boolean useApi() {
        return false;
    }

    @ConfigItem(
        keyName = "receiveInGameMessages",
        name = "Receive in-game messages",
        description = "Do you want to see chat messages from the plugin to confirm your submissions/etc?",
        position = 2,
        section = advancedSection
    )
    default boolean receiveInGameMessages() {
        return true;
    }

    @ConfigItem(
            keyName = "receiveDiscordChat",
            name = "Show Discord messages in game",
            description = "<html>Display messages sent in your group's Discord bridge channel inside your<br />"
                    + "clan chat box (visible only to you; nothing is sent to the game server).</html>",
            position = 3,
            section = advancedSection
    )
    default boolean receiveDiscordChat() {
        return true;
    }

    @ConfigItem(
        keyName = "syncAccountState",
        name = "Sync account progress",
        description = "<html>Periodically send your skills, quests, achievement diaries,<br>"
            + "combat achievements and collection log to DropTracker, so your<br>"
            + "profile page can show your current progress.<br>"
            + "This sends <b>progress data only</b> - never your bank, inventory or location.</html>",
        position = 4,
        section = advancedSection
    )
    default boolean syncAccountState() {
        return true;
    }

    @ConfigItem(
        keyName = "uploadCharacterModel",
        name = "Send character model & gear",
        description = "<html>Send a 3D model of your character (and pet) so your profile page<br>"
            + "can show it, and so the gear and inventory you were carrying can be<br>"
            + "pictured alongside your personal bests.<br>"
            + "The model is sent once per outfit, while you are standing still - never during combat.</html>",
        position = 5,
        section = advancedSection
    )
    default boolean uploadCharacterModel() {
        return true;
    }

    @ConfigItem(
        keyName = "showSidePanel",
        name = "Show Side Panel",
        description = "<html>Do you want to render the <br>side-panel to lookup players, etc?<br>"
            + "<b>Note</b>: Requires the API to be enabled.</html>",
        position = 6,
        section = advancedSection
    )
    default boolean showSidePanel() {
        return true;
    }

    @ConfigItem(
        keyName = "debugLogging",
        name = "Debug Logging",
        description = "Do you want the DropTracker to log data locally to your machine for debugging purposes?",
        position = 7,
        section = advancedSection
    )
    default boolean debugLogging() {
        return false;
    }

    // ==================== Retired from the UI ====================
    /*
     * Kept (not deleted) so a player's existing value still applies and the
     * code reading it keeps working. Un-hide by removing `hidden = true`.
     */

    /** Master gate for the whole XP/level pipeline; "Levels" and "XP Milestones" sit under it. */
    @ConfigItem(
        keyName = "trackExperience",
        name = "Track Experience",
        description = "Do you want to send experience gains to the DropTracker?",
        hidden = true
    )
    default boolean trackExperience() {
        return true;
    }

    /** Folded into "Activity Tracking"; an existing opt-out still wins. */
    @ConfigItem(
        keyName = "trackTrawling",
        name = "Deep Sea Trawling",
        description = "Track fish you catch while deep sea trawling.",
        hidden = true
    )
    default boolean trackTrawling() {
        return true;
    }

    /** Folded into "Send character model & gear"; an existing opt-out still wins. */
    @ConfigItem(
        keyName = "sendLoadoutWithPbs",
        name = "Send gear with personal bests",
        description = "Include the gear and inventory you carried when you set a personal best.",
        hidden = true
    )
    default boolean sendLoadoutWithPbs() {
        return true;
    }

    /** Nuance of "Display type"; retired to keep the Events section to four options. */
    @ConfigItem(
        keyName = "eventImportantPopupsOnly",
        name = "Pop-ups: important only",
        description = "Only pop up the big moments; ordinary completions stay in chat.",
        hidden = true
    )
    default boolean eventImportantPopupsOnly() {
        return false;
    }

    @ConfigItem(
        keyName = "pollUpdates",
        name = "Polling Updates",
        description = "Auto-update the side panel content/stats periodically.",
        hidden = true
    )
    default boolean pollUpdates() {
        return true;
    }

    // ==================== Internal state ====================

    @ConfigItem(
        name = "pinnedEventId",
        keyName = "pinnedEventId",
        description = "pinnedEventId",
        hidden = true
    )
    default int pinnedEventId() {
        return 0;
    }

    // NOTE: config setters MUST carry their own @ConfigItem — RuneLite's
    // ConfigInvocationHandler reads the key name from the setter's annotation
    // and silently ignores the call (WARN "has no @ConfigItem!") without it.
    @ConfigItem(
        name = "pinnedEventId",
        keyName = "pinnedEventId",
        description = "pinnedEventId",
        hidden = true
    )
    void setPinnedEventId(int eventId);

    @ConfigItem(
        name = "lastVersionNotified",
        keyName = "lastVersionNotified",
        description = "lastVersionNotified",
        hidden = true
    )
    default String lastVersionNotified() {
        return "0";
    }

    @ConfigItem(
        name = "lastVersionNotified",
        keyName = "lastVersionNotified",
        description = "lastVersionNotified",
        hidden = true
    )
    public void setLastVersionNotified(String versionNotified);

    @ConfigItem(
        name = "lastAccountName",
        keyName = "lastAccountName",
        description = "lastAccountName",
        hidden = true
    )
    default String lastAccountName() {
        return null;
    }

    @ConfigItem(
        name = "lastAccountName",
        keyName = "lastAccountName",
        description = "lastAccountName",
        hidden = true
    )
    void setLastAccountName(String accountName);

    @ConfigItem(
        name = "customApiEndpoint",
        keyName = "customApiEndpoint",
        description = "customApiEndpoint",
        hidden = true
    )
    default String customApiEndpoint() {
        return "";
    }

    @ConfigItem(
        name = "customApiEndpoint",
        keyName = "customApiEndpoint",
        description = "customApiEndpoint",
        hidden = true
    )
    void setCustomApiEndpoint(String customApiEndpoint);

    @ConfigItem(
        name = "lastAccountHash",
        keyName = "lastAccountHash",
        description = "lastAccountHash",
        hidden = true
    )
    default String lastAccountHash() {
        return null;
    }

    @ConfigItem(
        name = "lastAccountHash",
        keyName = "lastAccountHash",
        description = "lastAccountHash",
        hidden = true
    )
    void setLastAccountHash(String accountHash);
}

package io.droptracker.ui.overlays;

import io.droptracker.DropTrackerConfig;
import io.droptracker.models.EventHudDetail;
import io.droptracker.models.api.EventNotification;
import io.droptracker.models.api.EventState;
import io.droptracker.service.EventNotificationService;
import io.droptracker.ui.DropTrackerTheme;
import io.droptracker.util.RemoteImageCache;
import io.droptracker.util.ValueFormat;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;

/**
 * The "Enhanced display" HUD, painted in the style of the game's collection
 * log popup: layered parchment card with a bronze frame, a title strip, the
 * team standing and the tracked task with a framed progress bar. Movable
 * (hold Alt to drag — standard RuneLite overlay behavior). Data comes from
 * the {@code /event_state} snapshot in {@link EventNotificationService};
 * which event shows is the "Show on HUD" pick in the Events tab, and which
 * task shows honors the user's tracked-task pick (Events tab) before the
 * server's focus choice.
 *
 * While this HUD paints, incoming event pop-ups render as compact nudges
 * anchored directly beneath the card (following wherever the user dragged
 * it), and the stand-alone {@link EventToastOverlay} stands down — the user
 * positions one object, never two.
 */
@Singleton
public class EventHudOverlay extends Overlay {
    private static final int WIDTH = 200;
    private static final int PAD = 8;
    private static final int ICON_SIZE = 26;
    private static final int BAR_HEIGHT = 13;

    /* Frame palette (collection-log-popup inspired). */
    private static final Color EDGE_DARK = new Color(0x0e, 0x0b, 0x07);
    private static final Color FRAME_BRONZE = DropTrackerTheme.BRONZE;
    private static final Color BG_TOP = new Color(0x2c, 0x23, 0x18, 242);
    private static final Color BG_BOTTOM = new Color(0x15, 0x11, 0x0c, 242);
    private static final Color TITLE_STRIP = new Color(0x0e, 0x0b, 0x07, 130);
    private static final Color BAR_FILL = new Color(0x2e, 0x5c, 0x33);
    private static final Color BAR_EDGE = DropTrackerTheme.GREEN;

    private final DropTrackerConfig config;
    private final EventNotificationService service;
    private final ItemManager itemManager;
    private final RemoteImageCache remoteImages;

    @Inject
    public EventHudOverlay(DropTrackerConfig config, EventNotificationService service,
                           ItemManager itemManager, RemoteImageCache remoteImages) {
        this.config = config;
        this.service = service;
        this.itemManager = itemManager;
        this.remoteImages = remoteImages;
        setPosition(OverlayPosition.TOP_LEFT);
        setResizable(false);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!config.eventNotifications() || !config.eventDisplayMode().hudEnabled()) {
            return null;
        }
        EventState.Entry entry = service.hudEntry();
        if (entry == null || entry.getEvent() == null) {
            return null;
        }
        boolean detailed = config.eventHudDetail() == EventHudDetail.DETAILED;
        EventNotificationService.DisplayTask task = service.displayTask(entry);
        boolean awaitingRoll = "awaiting_roll".equals(entry.getBoardStatus());

        graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
            RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

        Font titleFont = FontManager.getRunescapeBoldFont();
        Font smallFont = FontManager.getRunescapeSmallFont();
        FontMetrics titleFm = graphics.getFontMetrics(titleFont);
        FontMetrics smallFm = graphics.getFontMetrics(smallFont);

        int innerWidth = WIDTH - PAD * 2;
        String title = truncateToWidth(entry.getEvent().getName(), titleFm, innerWidth);

        // Task label lines (max 2), leaving room for the icon column.
        BufferedImage icon = task != null ? taskIcon(task) : null;
        int labelWidth = innerWidth - (icon != null ? ICON_SIZE + 6 : 0);
        List<String> taskLines = task != null
            ? wrap(taskLabel(task), smallFm, labelWidth, 2) : new ArrayList<>();
        boolean hasBar = task != null && (task.need > 1 || task.have > 0);

        /* ---- measure ---- */
        int titleStripH = titleFm.getHeight() + 6;
        int height = titleStripH;
        if (detailed && entry.getTeam() != null) {
            height += 4 + smallFm.getHeight();
            if (entry.getTeam().getRank() != null) {
                height += smallFm.getHeight();
            }
        }
        if (awaitingRoll) {
            height += 6 + titleFm.getHeight();
        } else if (task != null) {
            int textBlock = taskLines.size() * smallFm.getHeight();
            int rowH = Math.max(icon != null ? ICON_SIZE : 0, textBlock);
            height += 6 + rowH;
            if (hasBar) {
                height += 4 + BAR_HEIGHT;
            }
        } else if (entry.getTasksTotal() > 0) {
            height += 6 + smallFm.getHeight();
        }
        height += PAD;

        /* ---- frame ---- */
        graphics.setPaint(new GradientPaint(0, 0, BG_TOP, 0, height, BG_BOTTOM));
        graphics.fillRect(1, 1, WIDTH - 2, height - 2);
        graphics.setColor(EDGE_DARK);
        graphics.setStroke(new BasicStroke(1));
        graphics.drawRect(0, 0, WIDTH - 1, height - 1);
        graphics.setColor(FRAME_BRONZE);
        graphics.drawRect(1, 1, WIDTH - 3, height - 3);

        /* ---- title strip ---- */
        graphics.setColor(TITLE_STRIP);
        graphics.fillRect(2, 2, WIDTH - 4, titleStripH - 2);
        graphics.setColor(FRAME_BRONZE);
        graphics.drawLine(2, titleStripH, WIDTH - 3, titleStripH);
        graphics.setFont(titleFont);
        int titleX = (WIDTH - titleFm.stringWidth(title)) / 2;
        int titleY = 3 + titleFm.getAscent();
        graphics.setColor(Color.BLACK);
        graphics.drawString(title, titleX + 1, titleY + 1);
        graphics.setColor(DropTrackerTheme.GOLD);
        graphics.drawString(title, titleX, titleY);

        int y = titleStripH + 4;

        /* ---- team standing (Detailed) ---- */
        if (detailed && entry.getTeam() != null) {
            EventState.TeamInfo team = entry.getTeam();
            Color teamColor = parseColor(team.getColor(), DropTrackerTheme.TEXT);
            graphics.setFont(smallFont);

            int swatch = 8;
            int swatchY = y + (smallFm.getHeight() - swatch) / 2;
            graphics.setColor(teamColor);
            graphics.fillRect(PAD, swatchY, swatch, swatch);
            graphics.setColor(EDGE_DARK);
            graphics.drawRect(PAD, swatchY, swatch, swatch);

            String standing = team.getRank() != null
                ? ordinal(team.getRank()) + " of " + team.getTeamCount()
                : ValueFormat.commas(team.getScore()) + " pts";
            String teamName = truncateToWidth(team.getName(), smallFm,
                innerWidth - swatch - 6 - smallFm.stringWidth(standing) - 4);
            int textY = y + smallFm.getAscent();
            shadowed(graphics, teamName, PAD + swatch + 6, textY, teamColor);
            shadowed(graphics, standing, WIDTH - PAD - smallFm.stringWidth(standing),
                textY, DropTrackerTheme.TEXT_MUTED);
            y += smallFm.getHeight();

            if (team.getRank() != null) {
                String score = ValueFormat.commas(team.getScore());
                textY = y + smallFm.getAscent();
                shadowed(graphics, "Score", PAD, textY, DropTrackerTheme.TEXT_MUTED);
                shadowed(graphics, score, WIDTH - PAD - smallFm.stringWidth(score),
                    textY, DropTrackerTheme.GOLD_BRIGHT);
                y += smallFm.getHeight();
            }
        }

        /* ---- task / roll prompt ---- */
        if (awaitingRoll) {
            y += 6;
            graphics.setFont(titleFont);
            String roll = "Roll the dice!";
            int rollX = (WIDTH - titleFm.stringWidth(roll)) / 2;
            shadowed(graphics, roll, rollX, y + titleFm.getAscent(), DropTrackerTheme.GOLD_BRIGHT);
        } else if (task != null) {
            y += 6;
            int textBlock = taskLines.size() * smallFm.getHeight();
            int rowH = Math.max(icon != null ? ICON_SIZE : 0, textBlock);
            int textX = PAD;
            if (icon != null) {
                graphics.drawImage(scaled(icon), PAD, y + (rowH - ICON_SIZE) / 2, null);
                textX += ICON_SIZE + 6;
            }
            graphics.setFont(smallFont);
            int lineY = y + (rowH - textBlock) / 2 + smallFm.getAscent();
            for (String line : taskLines) {
                shadowed(graphics, line, textX, lineY,
                    task.tracked ? DropTrackerTheme.GOLD_BRIGHT : DropTrackerTheme.TEXT);
                lineY += smallFm.getHeight();
            }
            y += rowH;

            if (hasBar) {
                y += 4;
                drawProgressBar(graphics, smallFm, PAD, y, innerWidth, task.have, task.need);
                y += BAR_HEIGHT;
            }
        } else if (entry.getTasksTotal() > 0) {
            y += 6;
            graphics.setFont(smallFont);
            String done = entry.getTasksCompleted() + " / " + entry.getTasksTotal();
            shadowed(graphics, "Tasks", PAD, y + smallFm.getAscent(), DropTrackerTheme.TEXT_MUTED);
            shadowed(graphics, done, WIDTH - PAD - smallFm.stringWidth(done),
                y + smallFm.getAscent(), DropTrackerTheme.TEXT);
        }

        // This frame painted: own the pop-up queue (EventToastOverlay stands
        // down) and render it as nudges hanging off the card's bottom edge.
        service.markHudRendered();
        int totalHeight = height;
        if (config.eventDisplayMode().popupsEnabled()) {
            totalHeight = renderNudges(graphics, height);
        }
        return new Dimension(WIDTH, totalHeight);
    }

    /* ===================== pop-up nudges ===================== */

    private static final int MAX_NUDGES = 3;
    private static final int NUDGE_GAP = 4;
    private static final int NUDGE_ICON = 20;
    /** Ceiling on nudge height — three cards of unbounded body used to be
     *  able to run off the bottom of the screen. */
    private static final int MAX_NUDGE_BODY_LINES = 3;
    private static final long NUDGE_FADE_MS = 1000;

    /** Draws the pending toasts as compact HUD-styled cards below the HUD
     *  (starting at {@code hudHeight}); returns the new total height. */
    private int renderNudges(Graphics2D g, int hudHeight) {
        long now = System.currentTimeMillis();
        List<EventNotificationService.Toast> visible = new ArrayList<>(MAX_NUDGES);
        Iterator<EventNotificationService.Toast> iterator = service.getToasts().iterator();
        while (iterator.hasNext()) {
            EventNotificationService.Toast toast = iterator.next();
            if (toast.expired(now)) {
                iterator.remove();
            } else if (visible.size() < MAX_NUDGES) {
                visible.add(toast);
            }
        }
        int y = hudHeight;
        for (EventNotificationService.Toast toast : visible) {
            y += NUDGE_GAP;
            y += drawNudge(g, toast, y, now);
        }
        return y;
    }

    private int drawNudge(Graphics2D g, EventNotificationService.Toast toast, int top, long now) {
        long remaining = toast.remainingMs(now);
        float alpha = remaining < NUDGE_FADE_MS
            ? Math.max(remaining / (float) NUDGE_FADE_MS, 0f) : 1f;
        Color accent = nudgeAccent(toast.getPriority());

        Font titleFont = FontManager.getRunescapeBoldFont();
        Font smallFont = FontManager.getRunescapeSmallFont();
        FontMetrics titleFm = g.getFontMetrics(titleFont);
        FontMetrics smallFm = g.getFontMetrics(smallFont);

        int textLeft = PAD;
        BufferedImage icon = null;
        if (toast.getIconItemId() != null && toast.getIconItemId() > 0) {
            icon = itemManager.getImage(toast.getIconItemId());
            if (icon != null) {
                textLeft += NUDGE_ICON + 6;
            }
        }
        int textWidth = WIDTH - textLeft - PAD;
        List<String> bodyLines = wrap(toast.getBody(), smallFm, textWidth, MAX_NUDGE_BODY_LINES);
        int height = 6 + titleFm.getHeight() + bodyLines.size() * smallFm.getHeight() + 6;
        if (icon != null) {
            height = Math.max(height, NUDGE_ICON + 12);
        }

        java.awt.Composite previous = g.getComposite();
        g.setComposite(java.awt.AlphaComposite.getInstance(
            java.awt.AlphaComposite.SRC_OVER, alpha));

        g.setColor(BG_BOTTOM);
        g.fillRect(1, top + 1, WIDTH - 2, height - 2);
        g.setColor(EDGE_DARK);
        g.drawRect(0, top, WIDTH - 1, height - 1);
        g.setColor(accent);
        g.drawRect(1, top + 1, WIDTH - 3, height - 3);

        if (icon != null) {
            g.drawImage(icon, PAD, top + (height - NUDGE_ICON) / 2,
                NUDGE_ICON, NUDGE_ICON, null);
        }
        g.setFont(titleFont);
        int titleY = top + 6 + titleFm.getAscent();
        shadowed(g, truncateToWidth(toast.getTitle(), titleFm, textWidth),
            textLeft, titleY, accent);
        g.setFont(smallFont);
        int lineY = titleY + smallFm.getHeight();
        for (String line : bodyLines) {
            shadowed(g, line, textLeft, lineY, DropTrackerTheme.TEXT);
            lineY += smallFm.getHeight();
        }

        g.setComposite(previous);
        return height;
    }

    /** Frame + title colour for a nudge, by importance tier: the tile-finishing
     *  drop and the 50-KC tick must not look alike at a glance. */
    private static Color nudgeAccent(EventNotification.Priority priority) {
        switch (priority) {
            case HIGH:
                return DropTrackerTheme.GOLD_BRIGHT;
            case LOW:
                return DropTrackerTheme.STONE;
            default:
                return FRAME_BRONZE;
        }
    }

    /* ===================== painting helpers ===================== */

    private void drawProgressBar(Graphics2D g, FontMetrics fm, int x, int y,
                                 int width, long have, long need) {
        long max = Math.max(need, 1);
        long value = Math.min(Math.max(have, 0), max);
        g.setColor(new Color(0x0a, 0x08, 0x05));
        g.fillRect(x, y, width, BAR_HEIGHT);
        int fill = (int) Math.round((double) value / max * (width - 2));
        g.setColor(BAR_FILL);
        g.fillRect(x + 1, y + 1, fill, BAR_HEIGHT - 2);
        g.setColor(BAR_EDGE);
        g.fillRect(x + 1, y + 1, fill, 2);
        g.setColor(FRAME_BRONZE);
        g.drawRect(x, y, width - 1, BAR_HEIGHT - 1);

        String text = ValueFormat.progress(have, need);
        int tx = x + (width - fm.stringWidth(text)) / 2;
        int ty = y + (BAR_HEIGHT + fm.getAscent() - fm.getDescent()) / 2;
        g.setColor(Color.BLACK);
        g.drawString(text, tx + 1, ty + 1);
        g.setColor(DropTrackerTheme.TEXT);
        g.drawString(text, tx, ty);
    }

    private void shadowed(Graphics2D g, String text, int x, int y, Color color) {
        g.setColor(Color.BLACK);
        g.drawString(text, x + 1, y + 1);
        g.setColor(color);
        g.drawString(text, x, y);
    }

    private String taskLabel(EventNotificationService.DisplayTask task) {
        // "*" not "★": this string is drawn with a RuneScape font, which has
        // no star glyph (see PanelIcons).
        return (task.tracked ? "* " : "") + (task.label != null ? task.label : "");
    }

    @Nullable
    private BufferedImage taskIcon(EventNotificationService.DisplayTask task) {
        if (task.iconItemId != null && task.iconItemId > 0) {
            return itemManager.getImage(task.iconItemId);
        }
        return remoteImages.get(task.iconPath, null);
    }

    private static BufferedImage scaled(BufferedImage source) {
        if (source.getWidth() <= ICON_SIZE && source.getHeight() <= ICON_SIZE) {
            return source;
        }
        // Fit within the slot, centered, aspect ratio preserved (item sprites
        // are 36x32 — a straight square scale visibly squishes them).
        int w = Math.max(source.getWidth(), 1);
        int h = Math.max(source.getHeight(), 1);
        float scale = Math.min((float) ICON_SIZE / w, (float) ICON_SIZE / h);
        int nw = Math.max(Math.round(w * scale), 1);
        int nh = Math.max(Math.round(h * scale), 1);
        BufferedImage out = new BufferedImage(ICON_SIZE, ICON_SIZE, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = out.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
            RenderingHints.VALUE_INTERPOLATION_BILINEAR);
        g.drawImage(source, (ICON_SIZE - nw) / 2, (ICON_SIZE - nh) / 2, nw, nh, null);
        g.dispose();
        return out;
    }

    /* ===================== text helpers ===================== */

    private static String truncateToWidth(String text, FontMetrics fm, int width) {
        if (text == null) {
            return "";
        }
        if (fm.stringWidth(text) <= width) {
            return text;
        }
        String out = text;
        while (out.length() > 1 && fm.stringWidth(out + "…") > width) {
            out = out.substring(0, out.length() - 1);
        }
        return out + "…";
    }

    /** Word-wrap into at most maxLines lines; the last line is ellipsized. */
    private static List<String> wrap(String text, FontMetrics fm, int width, int maxLines) {
        List<String> lines = new ArrayList<>();
        if (text == null || text.isEmpty()) {
            return lines;
        }
        String[] words = text.split(" ");
        StringBuilder line = new StringBuilder();
        for (String word : words) {
            String candidate = line.length() == 0 ? word : line + " " + word;
            if (fm.stringWidth(candidate) <= width || line.length() == 0) {
                line = new StringBuilder(candidate);
            } else {
                lines.add(line.toString());
                line = new StringBuilder(word);
                if (lines.size() == maxLines - 1) {
                    break;
                }
            }
        }
        if (line.length() > 0 && lines.size() < maxLines) {
            lines.add(line.toString());
        }
        // If the text didn't fully fit, ellipsize the final line.
        String joined = String.join(" ", lines);
        if (!joined.equals(text) && !lines.isEmpty()) {
            int last = lines.size() - 1;
            lines.set(last, truncateToWidth(lines.get(last) + "…", fm, width));
        }
        return lines;
    }

    private static Color parseColor(String hex, Color fallback) {
        if (hex == null || hex.isEmpty()) {
            return fallback;
        }
        try {
            return Color.decode(hex);
        } catch (NumberFormatException e) {
            return fallback;
        }
    }

    private static String ordinal(int n) {
        if (n % 100 >= 11 && n % 100 <= 13) {
            return n + "th";
        }
        switch (n % 10) {
            case 1: return n + "st";
            case 2: return n + "nd";
            case 3: return n + "rd";
            default: return n + "th";
        }
    }
}

package io.droptracker.ui.overlays;

import io.droptracker.DropTrackerConfig;
import io.droptracker.models.api.EventNotification;
import io.droptracker.service.EventNotificationService;
import io.droptracker.service.EventNotificationService.Toast;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;

/**
 * Transient event pop-ups ("Chat + text pop-ups" / "Enhanced display"):
 * up to {@value #MAX_VISIBLE} small cards stacked top-center, each at most
 * {@value #MAX_BODY_LINES} body lines tall, fading out over the last second
 * of their (priority-dependent) lifetime.
 *
 * Cards are styled by the envelope's importance tier: a completion that
 * finished a bingo tile gets a bright frame, an accent rail and a longer
 * life; a routine progress tick gets a dim frame and flicks past.
 *
 * Stands down while the Enhanced Display HUD is painting: the HUD then draws
 * the same queue as nudges anchored beneath itself (one movable object for
 * the user, not two), and this overlay resumes the moment the HUD stops.
 */
@Singleton
public class EventToastOverlay extends Overlay {
    private static final int MAX_VISIBLE = 3;
    /**
     * Hard ceiling on card height. Bodies used to wrap unbounded "so the
     * detail never gets cut", which let three cards eat the whole top of the
     * screen; the detail that matters leads the line anyway.
     */
    private static final int MAX_BODY_LINES = 3;
    private static final int WIDTH = 280;
    private static final int PADDING = 8;
    private static final int ICON_SIZE = 24;
    private static final int GAP = 6;
    private static final int RAIL_WIDTH = 3;
    private static final long FADE_MS = 1000;

    private static final Color BACKGROUND = new Color(0x15, 0x11, 0x0c, 230);
    private static final Color BORDER = new Color(0x7a, 0x5a, 0x32, 255);
    private static final Color BORDER_HIGH = new Color(0xff, 0xd9, 0x66, 255);
    private static final Color BORDER_LOW = new Color(0x5a, 0x5a, 0x52, 255);
    private static final Color TITLE = new Color(0xff, 0xb8, 0x3f);
    private static final Color TITLE_HIGH = new Color(0xff, 0xd9, 0x66);
    private static final Color TITLE_LOW = new Color(0xd8, 0xc9, 0xa3);
    private static final Color BODY = new Color(0xef, 0xe6, 0xd2);

    private final DropTrackerConfig config;
    private final EventNotificationService service;
    private final ItemManager itemManager;

    @Inject
    public EventToastOverlay(DropTrackerConfig config, EventNotificationService service,
                             ItemManager itemManager) {
        this.config = config;
        this.service = service;
        this.itemManager = itemManager;
        setPosition(OverlayPosition.TOP_CENTER);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!config.eventNotifications() || !config.eventDisplayMode().popupsEnabled()) {
            service.getToasts().clear();
            return null;
        }
        if (service.hudOwnsToasts()) {
            return null; // the HUD is rendering the queue as nudges beneath itself
        }
        long now = System.currentTimeMillis();
        List<Toast> visible = new ArrayList<>(MAX_VISIBLE);
        Iterator<Toast> iterator = service.getToasts().iterator();
        while (iterator.hasNext()) {
            Toast toast = iterator.next();
            if (toast.expired(now)) {
                iterator.remove();
            } else if (visible.size() < MAX_VISIBLE) {
                visible.add(toast);
            }
        }
        if (visible.isEmpty()) {
            return null;
        }

        graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
            RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
        int y = 0;
        for (Toast toast : visible) {
            y += drawToast(graphics, toast, y, now) + GAP;
        }
        return new Dimension(WIDTH, Math.max(y - GAP, 0));
    }

    private int drawToast(Graphics2D g, Toast toast, int top, long now) {
        long remaining = toast.remainingMs(now);
        float alpha = remaining < FADE_MS ? Math.max(remaining / (float) FADE_MS, 0f) : 1f;
        boolean important = toast.getPriority() == EventNotification.Priority.HIGH;

        FontMetrics titleFm = g.getFontMetrics(FontManager.getRunescapeBoldFont());
        FontMetrics bodyFm = g.getFontMetrics(FontManager.getRunescapeSmallFont());

        int textLeft = PADDING + (important ? RAIL_WIDTH : 0);
        BufferedImage icon = null;
        if (toast.getIconItemId() != null && toast.getIconItemId() > 0) {
            icon = itemManager.getImage(toast.getIconItemId());
            if (icon != null) {
                textLeft += ICON_SIZE + PADDING;
            }
        }
        int textWidth = WIDTH - textLeft - PADDING;
        List<String> bodyLines = wrap(toast.getBody(), bodyFm, textWidth, MAX_BODY_LINES);
        int height = PADDING + titleFm.getHeight()
            + bodyLines.size() * bodyFm.getHeight() + PADDING;
        height = Math.max(height, icon != null ? ICON_SIZE + 2 * PADDING : 0);

        java.awt.Composite previous = g.getComposite();
        g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));

        g.setColor(BACKGROUND);
        g.fillRoundRect(0, top, WIDTH, height, 8, 8);
        g.setColor(borderFor(toast));
        g.drawRoundRect(0, top, WIDTH - 1, height - 1, 8, 8);
        if (important) {
            // Accent rail: the one card you should look at reads as such even
            // out of the corner of your eye.
            g.fillRect(1, top + 2, RAIL_WIDTH, height - 4);
        }

        if (icon != null) {
            g.drawImage(icon, PADDING + (important ? RAIL_WIDTH : 0),
                top + (height - ICON_SIZE) / 2, ICON_SIZE, ICON_SIZE, null);
        }

        int textY = top + PADDING + titleFm.getAscent();
        g.setFont(FontManager.getRunescapeBoldFont());
        g.setColor(titleFor(toast));
        g.drawString(ellipsize(toast.getTitle(), titleFm, textWidth), textLeft, textY);

        g.setFont(FontManager.getRunescapeSmallFont());
        g.setColor(BODY);
        int lineY = textY + bodyFm.getHeight();
        for (String line : bodyLines) {
            g.drawString(line, textLeft, lineY);
            lineY += bodyFm.getHeight();
        }

        g.setComposite(previous);
        return height;
    }

    private static Color borderFor(Toast toast) {
        switch (toast.getPriority()) {
            case HIGH:
                return BORDER_HIGH;
            case LOW:
                return BORDER_LOW;
            default:
                return BORDER;
        }
    }

    private static Color titleFor(Toast toast) {
        switch (toast.getPriority()) {
            case HIGH:
                return TITLE_HIGH;
            case LOW:
                return TITLE_LOW;
            default:
                return TITLE;
        }
    }

    /** Word-wrap into at most {@code maxLines} lines, marking the last one
     *  with "…" whenever anything had to be dropped. */
    private static List<String> wrap(String text, FontMetrics fm, int width, int maxLines) {
        List<String> lines = new ArrayList<>();
        if (text == null || text.isEmpty()) {
            return lines;
        }
        StringBuilder current = new StringBuilder();
        boolean clipped = false;
        for (String word : text.split(" ")) {
            String candidate = current.length() == 0 ? word : current + " " + word;
            if (fm.stringWidth(candidate) <= width || current.length() == 0) {
                current = new StringBuilder(candidate);
            } else if (lines.size() == maxLines - 1) {
                clipped = true; // no room for another line: drop the tail
                break;
            } else {
                lines.add(current.toString());
                current = new StringBuilder(word);
            }
        }
        if (current.length() > 0 && lines.size() < maxLines) {
            lines.add(current.toString());
        }
        if (!lines.isEmpty()) {
            int last = lines.size() - 1;
            String tail = lines.get(last);
            if (clipped || !String.join(" ", lines).equals(text)) {
                tail += "…";
            }
            // Always through ellipsize: a single word wider than the card
            // (a long team name) has no wrap point to break on.
            lines.set(last, ellipsize(tail, fm, width));
        }
        return lines;
    }

    private static String ellipsize(String text, FontMetrics fm, int width) {
        if (text == null) {
            return "";
        }
        if (fm.stringWidth(text) <= width) {
            return text;
        }
        String result = text;
        while (result.length() > 1 && fm.stringWidth(result + "…") > width) {
            result = result.substring(0, result.length() - 1);
        }
        return result + "…";
    }
}

package io.droptracker.ui;

import io.droptracker.ui.components.PanelIcons;
import net.runelite.client.ui.FontManager;

import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.Border;
import javax.swing.border.EmptyBorder;
import java.awt.Color;
import java.awt.LayoutManager;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;

/**
 * Design tokens for the DropTracker side panel, mapped from the droptracker.io web
 * design system (dark parchment surfaces, gold accents) to Swing colors.
 *
 * Surfaces get lighter as they nest: SURFACE_0 is the page background, SURFACE_1 is a
 * card, SURFACE_2 is nested/hover content inside a card, SURFACE_3 is borders/accents.
 */
public final class DropTrackerTheme {

    /* Surfaces */
    public static final Color SURFACE_0 = new Color(0x15110c);
    public static final Color SURFACE_1 = new Color(0x211a12);
    public static final Color SURFACE_2 = new Color(0x2c2318);
    public static final Color SURFACE_3 = new Color(0x3a2f20);

    /* Text */
    public static final Color TEXT = new Color(0xefe6d2);
    public static final Color TEXT_MUTED = new Color(0xd8c9a3);

    /* Accents */
    public static final Color GOLD = new Color(0xffb83f);
    public static final Color GOLD_BRIGHT = new Color(0xffd966);
    public static final Color GREEN = new Color(0x6fbf73);
    public static final Color RED = new Color(0xe05c4d);
    public static final Color EMBER = new Color(0xff8c42);

    /* Subtle borders */
    public static final Color BRONZE = new Color(0x7a5a32);
    public static final Color STONE = new Color(0x5a5a52);

    private DropTrackerTheme() {
    }

    /** Standard matte card border: 1px SURFACE_3 line with 8px inner padding. */
    public static Border cardBorder() {
        return cardBorder(8, 8, 8, 8);
    }

    /** Matte card border with custom inner padding. */
    public static Border cardBorder(int top, int left, int bottom, int right) {
        return BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(SURFACE_3, 1),
            new EmptyBorder(top, left, bottom, right));
    }

    /** Accented card border (bronze), for panels that should stand out. */
    public static Border accentCardBorder(int top, int left, int bottom, int right) {
        return BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(BRONZE, 1),
            new EmptyBorder(top, left, bottom, right));
    }

    /** Creates a SURFACE_1 card panel with the standard matte border. */
    public static JPanel card(LayoutManager layout) {
        JPanel panel = new JPanel(layout);
        panel.setBackground(SURFACE_1);
        panel.setBorder(cardBorder());
        return panel;
    }

    /** Applies the standard themed button look (SURFACE_2 body, gold-bright hover). */
    public static void styleButton(JButton button) {
        button.setFocusPainted(false);
        button.setContentAreaFilled(true);
        button.setOpaque(true);
        button.setBackground(SURFACE_2);
        button.setForeground(TEXT);
        button.setFont(FontManager.getRunescapeSmallFont());
        button.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(SURFACE_3, 1),
            new EmptyBorder(4, 8, 4, 8)));
        button.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseEntered(MouseEvent e) {
                if (button.isEnabled()) {
                    button.setBackground(SURFACE_3);
                    button.setForeground(GOLD_BRIGHT);
                }
            }

            @Override
            public void mouseExited(MouseEvent e) {
                button.setBackground(SURFACE_2);
                button.setForeground(TEXT);
            }
        });
    }

    /** Small round status dot in the given color. Painted rather than drawn as
     *  a "●" glyph, which no bundled font carries (see PanelIcons). */
    public static JLabel statusDot(Color color) {
        JLabel dot = new JLabel(PanelIcons.dot(color, 10));
        dot.setForeground(color);
        return dot;
    }

    /**
     * Compact status "chip": small bordered label used for submission states.
     * The chip text is rendered in the accent color on a SURFACE_2 body.
     */
    public static JLabel chip(String text, Color accent) {
        JLabel label = new JLabel(text);
        label.setFont(FontManager.getRunescapeSmallFont());
        label.setForeground(accent);
        label.setOpaque(true);
        label.setBackground(SURFACE_2);
        label.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(SURFACE_3, 1),
            new EmptyBorder(1, 4, 1, 4)));
        return label;
    }
}

package io.droptracker.ui;

import io.droptracker.api.DropTrackerUrls;
import io.droptracker.DropTrackerConfig;
import io.droptracker.DropTrackerPlugin;
import io.droptracker.service.SubmissionManager;

import javax.inject.Inject;
import javax.swing.*;

import io.droptracker.api.DropTrackerApi;
import io.droptracker.service.EventNotificationService;
import io.droptracker.ui.components.PanelElements;
import io.droptracker.ui.components.PanelIcons;
import io.droptracker.ui.pages.ActivityPanel;
import io.droptracker.ui.pages.EventsPanel;
import io.droptracker.ui.pages.GroupPanel;
import io.droptracker.ui.pages.HomePanel;
import io.droptracker.ui.pages.PlayerStatsPanel;
import io.droptracker.util.ItemIDSearch;
import io.droptracker.util.RemoteImageCache;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.LinkBrowser;
import okhttp3.OkHttpClient;

import javax.swing.border.EmptyBorder;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Image;
import java.util.Map;

@Slf4j
public class DropTrackerPanel extends PluginPanel implements DropTrackerApi.PanelDataLoadedCallback {

	private static final ImageIcon LOGO_GIF;

	static {
		Image logoGif = ImageUtil.loadImageResource(DropTrackerPlugin.class, "brand/droptracker-small.gif");
		Image logoResized = logoGif.getScaledInstance(44, 44, Image.SCALE_DEFAULT);
		LOGO_GIF = new ImageIcon(logoResized);
	}

	/** Connection state shown as a dot + label in the persistent header. */
	public enum ConnectionState {
		CONNECTED("Connected", DropTrackerTheme.GREEN),
		CONNECTING("Connecting…", DropTrackerTheme.EMBER),
		OFFLINE("Offline", DropTrackerTheme.RED),
		DISABLED("API off", DropTrackerTheme.STONE);

		private final String label;
		private final Color color;

		ConnectionState(String label, Color color) {
			this.label = label;
			this.color = color;
		}
	}

	private final DropTrackerPlugin plugin;
	private final DropTrackerApi api;
	private final OkHttpClient httpClient;
	private JPanel headerPanel;

	@Inject
	private Client client;
	@Inject
	private ItemManager itemManager;
	@Inject
	private DropTrackerConfig config;
	@Inject
	private SubmissionManager submissionManager;
	@Inject
	private EventNotificationService eventNotificationService;
	@Inject
	private RemoteImageCache remoteImageCache;
	@Inject
	private ItemIDSearch itemIDSearch;
	@Inject
	private ConfigManager configManager;

	private PlayerStatsPanel statsPanel;
	private GroupPanel groupPanel;
	private ActivityPanel activityPanel;
	private HomePanel homePanel;
	private EventsPanel eventsPanel;
	private JTabbedPane tabbedPane;

	// The actual component instances added as tabs
	private JPanel homeComponent;
	private JPanel activityComponent;
	private JPanel playerComponent;
	private JPanel groupComponent;
	private JPanel eventsComponent;

	private JLabel statusDotLabel;
	private JLabel statusTextLabel;

	@Inject
	public DropTrackerPanel(DropTrackerConfig config, DropTrackerApi api, DropTrackerPlugin plugin, Client client, OkHttpClient httpClient) {
		this.config = config;
		this.api = api;
		this.plugin = plugin;
		this.client = client;
		this.httpClient = httpClient;
		// Static UI helpers fetch images through the shared client; hand it over once here.
		// They also need to know whether the API is on: lootboards come from our own
		// host, so they must not be fetched unless the user has enabled connections.
		PanelElements.setHttpClient(httpClient, config.useApi());

		setLayout(new BorderLayout());
		setBorder(new EmptyBorder(6, 6, 6, 6));
		setBackground(DropTrackerTheme.SURFACE_0);

		// init() will be called by the plugin - don't call it here to avoid double initialization
	}

	public void init() {
		// Stop any timer owned by a previous incarnation of the Activity tab
		if (activityPanel != null) {
			activityPanel.cleanup();
			activityPanel = null;
		}
		removeAll();

		setLayout(new BorderLayout());
		headerPanel = buildHeader();

		tabbedPane = new JTabbedPane();
		tabbedPane.setBackground(DropTrackerTheme.SURFACE_0);
		tabbedPane.setForeground(DropTrackerTheme.TEXT);
		tabbedPane.setFont(FontManager.getRunescapeSmallFont());

		homePanel = new HomePanel(config, api, client, this);
		homeComponent = homePanel.create();

		if (config.useApi()) {
			activityPanel = new ActivityPanel(config, api, submissionManager, this);
			activityComponent = activityPanel.create();
			statsPanel = new PlayerStatsPanel(client, plugin, config, api, itemManager);
			playerComponent = statsPanel.create();
			groupPanel = new GroupPanel(client, config, api, itemManager, this, httpClient);
			groupComponent = groupPanel.create();
			eventsPanel = new EventsPanel(config, api, eventNotificationService,
				client, itemManager, remoteImageCache, itemIDSearch, configManager);
			eventsComponent = eventsPanel.create();
			eventNotificationService.setOnStateUpdated(() -> {
				if (eventsPanel != null) {
					eventsPanel.onUpdated();
				}
			});

			tabbedPane.addTab("Home", homeComponent);
			tabbedPane.addTab("Activity", activityComponent);
			tabbedPane.addTab("Events", eventsComponent);
			tabbedPane.addTab("Player", playerComponent);
			tabbedPane.addTab("Group", groupComponent);
		} else {
			activityComponent = null;
			playerComponent = null;
			groupComponent = null;
			eventsComponent = null;
			eventsPanel = null;
			eventNotificationService.setOnStateUpdated(null);
			tabbedPane.addTab("Home", homeComponent);
		}

		add(headerPanel, BorderLayout.NORTH);
		add(tabbedPane, BorderLayout.CENTER);
		tabbedPane.setSelectedComponent(homeComponent);

		// Populate the connection indicator once everything is wired up
		if (config.useApi() && activityPanel != null) {
			activityPanel.updateStatusLabel();
		} else {
			updateConnectionState(ConnectionState.DISABLED);
		}

		revalidate();
		repaint();
	}

	/**
	 * Compact persistent header: logo, name + version, tracked account, and a single
	 * connection dot + label, plus the refresh affordance.
	 */
	private JPanel buildHeader() {
		JPanel header = new JPanel();
		header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
		header.setBackground(DropTrackerTheme.SURFACE_1);
		header.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 1, 0, DropTrackerTheme.SURFACE_3),
			new EmptyBorder(6, 8, 6, 8)));

		// Row 1: logo | title + version | refresh
		JPanel topRow = new JPanel(new BorderLayout(8, 0));
		topRow.setBackground(DropTrackerTheme.SURFACE_1);
		topRow.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, 48));

		JLabel logoLabel = new JLabel(LOGO_GIF);
		topRow.add(logoLabel, BorderLayout.WEST);

		JPanel titleCol = new JPanel();
		titleCol.setLayout(new BoxLayout(titleCol, BoxLayout.Y_AXIS));
		titleCol.setBackground(DropTrackerTheme.SURFACE_1);

		JLabel titleLabel = new JLabel("DropTracker");
		titleLabel.setFont(FontManager.getRunescapeBoldFont());
		titleLabel.setForeground(DropTrackerTheme.TEXT);
		titleLabel.setAlignmentX(Component.LEFT_ALIGNMENT);

		JLabel versionLabel = new JLabel("v" + plugin.pluginVersion);
		versionLabel.setFont(FontManager.getRunescapeSmallFont());
		versionLabel.setForeground(DropTrackerTheme.TEXT_MUTED);
		versionLabel.setAlignmentX(Component.LEFT_ALIGNMENT);

		titleCol.add(Box.createVerticalGlue());
		titleCol.add(titleLabel);
		titleCol.add(versionLabel);
		titleCol.add(Box.createVerticalGlue());
		topRow.add(titleCol, BorderLayout.CENTER);

		JButton docsButton = new JButton("?");
		DropTrackerTheme.styleButton(docsButton);
		docsButton.setToolTipText("Open the DropTracker documentation");
		docsButton.setPreferredSize(new Dimension(26, 26));
		docsButton.setMargin(new java.awt.Insets(0, 0, 0, 0));
		docsButton.addActionListener(e -> LinkBrowser.browse(DropTrackerUrls.web("docs").toString()));

		JButton refreshButton = new JButton(
			PanelIcons.refresh(DropTrackerTheme.TEXT, 12));
		DropTrackerTheme.styleButton(refreshButton);
		refreshButton.setToolTipText("Refresh panel");
		refreshButton.setPreferredSize(new Dimension(26, 26));
		refreshButton.setMargin(new java.awt.Insets(0, 0, 0, 0));
		refreshButton.addActionListener(e -> init());

		JPanel refreshWrap = new JPanel(new FlowLayout(FlowLayout.RIGHT, 4, 0));
		refreshWrap.setBackground(DropTrackerTheme.SURFACE_1);
		refreshWrap.add(docsButton);
		refreshWrap.add(refreshButton);
		topRow.add(refreshWrap, BorderLayout.EAST);

		header.add(topRow);
		header.add(Box.createRigidArea(new Dimension(0, 4)));

		// Row 2: tracked account + connection status on one compact line
		JPanel statusRow = new JPanel(new BorderLayout(4, 0));
		statusRow.setBackground(DropTrackerTheme.SURFACE_1);
		statusRow.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, 18));

		JLabel accountLabel = new JLabel();
		accountLabel.setFont(FontManager.getRunescapeSmallFont());
		String lastAccount = config.lastAccountName();
		if (lastAccount != null && !lastAccount.isEmpty()) {
			accountLabel.setText(lastAccount);
			accountLabel.setForeground(DropTrackerTheme.TEXT_MUTED);
			accountLabel.setToolTipText("Currently tracked account");
		} else {
			accountLabel.setText("You are not registered!");
			accountLabel.setForeground(DropTrackerTheme.EMBER);
			accountLabel.setToolTipText("<html>Claim your in-game name in our Discord to register.<br/>"
				+ "Join via the <b>Join Discord</b> button on the Home tab.</html>");
		}
		statusRow.add(accountLabel, BorderLayout.WEST);

		JPanel connectionPanel = new JPanel(new FlowLayout(FlowLayout.RIGHT, 3, 0));
		connectionPanel.setBackground(DropTrackerTheme.SURFACE_1);
		statusDotLabel = DropTrackerTheme.statusDot(DropTrackerTheme.STONE);
		statusTextLabel = new JLabel("…");
		statusTextLabel.setFont(FontManager.getRunescapeSmallFont());
		statusTextLabel.setForeground(DropTrackerTheme.TEXT_MUTED);
		connectionPanel.add(statusDotLabel);
		connectionPanel.add(statusTextLabel);
		statusRow.add(connectionPanel, BorderLayout.EAST);

		header.add(statusRow);

		return header;
	}

	public void deinit() {
		removeAll();
		if (activityPanel != null) {
			activityPanel.cleanup();
		}
		eventNotificationService.setOnStateUpdated(null);
		eventsPanel = null;
	}

	public void selectPanel(String panelToSelect) {
		if (tabbedPane == null) {
			return;
		}

		switch (panelToSelect.toLowerCase()) {
			case "home":
			case "welcome":
				if (homeComponent != null) {
					tabbedPane.setSelectedComponent(homeComponent);
				}
				break;
			case "player":
			case "players":
			case "stats":
				if (playerComponent != null && config.useApi()) {
					tabbedPane.setSelectedComponent(playerComponent);
				}
				break;
			case "group":
			case "groups":
				if (groupComponent != null && config.useApi()) {
					tabbedPane.setSelectedComponent(groupComponent);
				}
				break;
			// "api" kept for backwards compatibility: that tab is now "Activity"
			case "api":
			case "activity":
				if (activityComponent != null && config.useApi()) {
					tabbedPane.setSelectedComponent(activityComponent);
				}
				break;
			default:
				break;
		}
	}

	// Allow searched for player by name (Perhaps for right-click lookups later, etc)
	public void updatePlayerPanel(String playerToLoad) {
		if (statsPanel != null) {
			statsPanel.performPlayerSearch(playerToLoad);
		}
	}

	// Update the player panel with the current player's name
	public void updatePlayerPanel() {
		if (statsPanel != null) {
			statsPanel.performPlayerSearch("");
		}
	}

	// Update the group panel from sources other than direct searches
	public void updateGroupPanel(String groupToLoad) {
		if (groupPanel != null && groupToLoad != null && !groupToLoad.trim().isEmpty()) {
			groupPanel.performGroupSearch(groupToLoad);
		}
	}

	// Update the Activity tab with the current session's valid submissions
	public void updateSentSubmissions() {
		if (activityPanel != null) {
			activityPanel.refresh();
		}
	}

	/**
	 * Updates the player button on the home panel if a local name becomes available after initial render
	 */
	public void updateHomePlayerButton() {
		if (homePanel != null) {
			homePanel.updatePlayerButton();
		}
	}

	/**
	 * Updates the connection dot + label in the persistent header.
	 */
	public void updateConnectionState(ConnectionState state) {
		if (statusDotLabel == null || statusTextLabel == null || state == null) {
			return;
		}
		statusDotLabel.setForeground(state.color);
		statusTextLabel.setText(state.label);
		statusTextLabel.setForeground(state.color);
		if (headerPanel != null) {
			headerPanel.revalidate();
			headerPanel.repaint();
		}
	}

	@Override
	public void onDataLoaded(Map<String, Object> data) {
		updatePlayerPanel();
		updateGroupPanel("");
	}
}

package io.droptracker.ui.pages;

import io.droptracker.api.DropTrackerUrls;
import io.droptracker.DropTrackerConfig;
import io.droptracker.api.DropTrackerApi;
import io.droptracker.ui.DropTrackerPanel;
import io.droptracker.ui.DropTrackerTheme;
import io.droptracker.ui.components.PanelElements;
import net.runelite.api.Client;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.LinkBrowser;

import javax.annotation.Nullable;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;

public class HomePanel {
    private final DropTrackerConfig config;
    private final DropTrackerApi api;
    private final Client client;
    private final DropTrackerPanel panel;

    // Store references for dynamic updates
    private JPanel homePanel;
    private @Nullable JPanel playerButtonRow;
    private int playerButtonIndex = -1; // Tracks where to insert the button

    public HomePanel(DropTrackerConfig config, DropTrackerApi api, Client client, DropTrackerPanel panel) {
        this.config = config;
        this.api = api;
        this.client = client;
        this.panel = panel;
    }

    public JPanel create() {
        homePanel = new JPanel();
        homePanel.setLayout(new BoxLayout(homePanel, BoxLayout.Y_AXIS));
        homePanel.setBackground(DropTrackerTheme.SURFACE_0);
        homePanel.setBorder(new EmptyBorder(5, 0, 5, 0));

        // Set maximum width to prevent expansion
        homePanel.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, Integer.MAX_VALUE));

        // When the API is disabled, lead with a call-to-action explaining what it unlocks.
        if (!config.useApi()) {
            homePanel.add(createApiCtaCard());
            homePanel.add(Box.createRigidArea(new Dimension(0, 8)));
        }

        final JPanel welcomeMessagePanel = PanelElements.createCollapsiblePanel("Welcome to the DropTracker", PanelElements.getLatestWelcomeContent(api), true);

        final JPanel patchNotesPanel = PanelElements.createCollapsiblePanel("News / Updates", PanelElements.getLatestUpdateContent(config, api), false);

        homePanel.add(welcomeMessagePanel);
        homePanel.add(Box.createRigidArea(new Dimension(0, 8)));

        // Global lootboard button row — a 1-cell grid so the button fills the
        // panel's full width instead of hugging its text.
        JButton viewGlobalButton = PanelElements.createLootboardButton("Global Lootboard", "Click to view the global lootboard", () -> PanelElements.showLootboardForGroup(client, 2));
        viewGlobalButton.setMargin(new Insets(3, 3, 3, 3));
        viewGlobalButton.setHorizontalAlignment(SwingConstants.CENTER);

        JPanel buttonPanel = new JPanel(new GridLayout(1, 1, 5, 0));
        buttonPanel.setBackground(DropTrackerTheme.SURFACE_0);
        buttonPanel.setAlignmentX(Component.LEFT_ALIGNMENT);
        buttonPanel.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, 30));
        buttonPanel.add(viewGlobalButton);
        homePanel.add(buttonPanel);

        // Note: playerButtonIndex will be set to the next component index
        playerButtonIndex = homePanel.getComponentCount();

        // Initialize player button (will add if config is available)
        updatePlayerButton();

        homePanel.add(Box.createRigidArea(new Dimension(0, 8)));
        homePanel.add(patchNotesPanel);
        homePanel.add(Box.createRigidArea(new Dimension(0, 8)));
        homePanel.add(createQuickLinks());
        // Collect leftover vertical space here instead of stretching the cards.
        homePanel.add(Box.createVerticalGlue());

        return homePanel;
    }

    /**
     * Prominent card shown when the API integration is disabled, explaining what
     * enabling it adds. The rest of the plugin (Discord webhook notifications) still
     * works without it.
     */
    private JPanel createApiCtaCard() {
        JPanel card = new JPanel();
        card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
        card.setBackground(DropTrackerTheme.SURFACE_1);
        card.setBorder(DropTrackerTheme.accentCardBorder(10, 10, 10, 10));
        card.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, 170));
        card.setAlignmentX(Component.LEFT_ALIGNMENT);

        JLabel title = new JLabel("Unlock the full DropTracker");
        title.setFont(FontManager.getRunescapeBoldFont());
        title.setForeground(DropTrackerTheme.GOLD);
        title.setAlignmentX(Component.LEFT_ALIGNMENT);

        JTextArea body = new JTextArea(
            "Enable \"Use API Connections\" in the plugin settings to unlock:\n"
            + "- Live top player & group leaderboards\n"
            + "- Player and group lookups\n"
            + "- Submission tracking with retries\n"
            + "- Participation in clan events");
        body.setWrapStyleWord(true);
        body.setLineWrap(true);
        body.setOpaque(false);
        body.setEditable(false);
        body.setFocusable(false);
        body.setForeground(DropTrackerTheme.TEXT_MUTED);
        body.setFont(FontManager.getRunescapeSmallFont());
        body.setBorder(new EmptyBorder(5, 0, 5, 0));
        body.setAlignmentX(Component.LEFT_ALIGNMENT);

        JButton learnMore = new JButton("Learn more");
        DropTrackerTheme.styleButton(learnMore);
        learnMore.setToolTipText("Read about the DropTracker API on the wiki");
        learnMore.setAlignmentX(Component.LEFT_ALIGNMENT);
        learnMore.addActionListener(e -> LinkBrowser.browse(DropTrackerUrls.web("wiki").toString()));

        card.add(title);
        card.add(body);
        card.add(learnMore);

        return card;
    }

    /** 2x2 grid of quick links: wiki, discord, suggestions, bug reports. */
    private JPanel createQuickLinks() {
        JPanel quickAccessPanel = new JPanel();
        quickAccessPanel.setLayout(new BoxLayout(quickAccessPanel, BoxLayout.Y_AXIS));
        quickAccessPanel.setBackground(DropTrackerTheme.SURFACE_0);
        quickAccessPanel.setAlignmentX(Component.LEFT_ALIGNMENT);

        JPanel topButtonRow = new JPanel(new GridLayout(1, 2, 5, 0));
        topButtonRow.setBackground(DropTrackerTheme.SURFACE_0);

        JPanel bottomButtonRow = new JPanel(new GridLayout(1, 2, 5, 0));
        bottomButtonRow.setBackground(DropTrackerTheme.SURFACE_0);

        topButtonRow.add(linkButton("Read the Wiki", DropTrackerUrls.web("wiki").toString()));
        topButtonRow.add(linkButton("Join Discord", DropTrackerUrls.web("discord").toString()));
        bottomButtonRow.add(linkButton("Suggest Features", DropTrackerUrls.web("forums", "suggestions").toString()));
        bottomButtonRow.add(linkButton("Report a Bug", DropTrackerUrls.web("forums", "bug-reports").toString()));

        quickAccessPanel.add(topButtonRow);
        quickAccessPanel.add(Box.createRigidArea(new Dimension(0, 8)));
        quickAccessPanel.add(bottomButtonRow);

        quickAccessPanel.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, 68));
        return quickAccessPanel;
    }

    private JButton linkButton(String text, String url) {
        JButton button = new JButton(text);
        DropTrackerTheme.styleButton(button);
        button.addActionListener(e -> LinkBrowser.browse(url));
        button.setMargin(new Insets(0, 0, 0, 0));
        return button;
    }

    /**
     * Updates the player button based on current config state.
     * Can be called dynamically when the config changes.
     */
    public void updatePlayerButton() {
        if (homePanel == null) {
            return; // Panel not initialized yet
        }

        // Remove existing player button if it exists
        if (playerButtonRow != null) {
            homePanel.remove(playerButtonRow);
            playerButtonRow = null;
        }

        // Add player button if the API is on and an account has been seen
        if (config.useApi() && config.lastAccountName() != null && !config.lastAccountName().isEmpty()) {
            playerButtonRow = new JPanel(new GridLayout(1, 1, 5, 0));
            playerButtonRow.setBackground(DropTrackerTheme.SURFACE_0);
            playerButtonRow.setAlignmentX(Component.LEFT_ALIGNMENT);
            playerButtonRow.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, 30));

            JButton playerStatsButton = new JButton("View your Stats");
            DropTrackerTheme.styleButton(playerStatsButton);
            playerStatsButton.addActionListener(e -> {
                panel.selectPanel("player");
                panel.updatePlayerPanel(config.lastAccountName());
            });
            playerStatsButton.setMargin(new Insets(0, 0, 0, 0));

            playerButtonRow.add(playerStatsButton);

            // Insert at the correct position (after the global lootboard button)
            homePanel.add(playerButtonRow, playerButtonIndex);
        }

        // Refresh the panel
        homePanel.revalidate();
        homePanel.repaint();
    }
}

package io.droptracker.ui.pages;

import io.droptracker.DropTrackerConfig;
import io.droptracker.api.DropTrackerApi;
import io.droptracker.api.DropTrackerUrls;
import io.droptracker.models.api.GroupSearchResult;
import io.droptracker.models.api.TopGroupResult;
import io.droptracker.models.submissions.RecentSubmission;
import io.droptracker.ui.DropTrackerPanel;
import io.droptracker.ui.components.LeaderboardComponents;
import io.droptracker.ui.components.StateViews;
import io.droptracker.ui.components.PanelElements;
import io.droptracker.ui.DropTrackerTheme;
import net.runelite.api.Client;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.LinkBrowser;
import javax.annotation.Nullable;

import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

import javax.imageio.ImageIO;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.util.List;
import java.util.concurrent.CompletableFuture;

public class GroupPanel {
    private final Client client;
    private final DropTrackerConfig config;
    private final DropTrackerPanel panel;
    private final DropTrackerApi api;
    private final ItemManager itemManager;
    private final OkHttpClient httpClient;

    private int currentGroupId = 2; // Track group ID instead of URL

    // UI components that we need to update
    private JPanel contentPanel;
    private JTextField searchField;

    // Add field for tracking leaderboard placeholder
    private JPanel leaderboardPlaceholder;

    /**
     * Name of the group currently shown in the detail view. Used to make sure a
     * late-arriving async enrichment doesn't clobber a newer view.
     */
    private String activeDetailGroupName;

    public GroupPanel(Client client, DropTrackerConfig config, DropTrackerApi api, ItemManager itemManager, DropTrackerPanel panel, OkHttpClient httpClient) {
        this.client = client;
        this.config = config;
        this.api = api;
        this.itemManager = itemManager;
        this.panel = panel;
        // Redirects off: group icons load from a hardcoded base, and following a
        // redirect would let the response choose the host instead.
        this.httpClient = httpClient.newBuilder()
            .followRedirects(false)
            .followSslRedirects(false)
            .build();
    }

    public JPanel create() {
        var mainPanel = new JPanel();
        mainPanel.setLayout(new BoxLayout(mainPanel, BoxLayout.Y_AXIS));
        mainPanel.setBackground(DropTrackerTheme.SURFACE_0);

        // Header section with title and search using LeaderboardComponents
        LeaderboardComponents.HeaderResult headerResult = LeaderboardComponents.createHeaderPanel(
                "DropTracker - Groups",
                "Search for a group",
                () -> performGroupSearch("")
        );
        searchField = headerResult.searchField;

        // Content panel that will change based on state - fix alignment
        contentPanel = new JPanel();
        contentPanel.setLayout(new BoxLayout(contentPanel, BoxLayout.Y_AXIS));
        contentPanel.setBackground(DropTrackerTheme.SURFACE_0);
        contentPanel.setAlignmentX(Component.LEFT_ALIGNMENT);

        // Show default state
        showDefaultState();

        // Add components to main panel - match PlayerStatsPanel structure
        mainPanel.add(headerResult.panel);
        mainPanel.add(Box.createRigidArea(new Dimension(0, 10)));
        mainPanel.add(contentPanel);
        mainPanel.add(Box.createVerticalGlue());

        return mainPanel;
    }


    private void showDefaultState() {
        activeDetailGroupName = null;
        contentPanel.removeAll();

        // Create center panel for the button
        JPanel defaultPanel = new JPanel();
        defaultPanel.setLayout(new BoxLayout(defaultPanel, BoxLayout.Y_AXIS));
        defaultPanel.setBackground(DropTrackerTheme.SURFACE_0);
        defaultPanel.setAlignmentX(Component.CENTER_ALIGNMENT);

        // Instructions text
