    private JPanel showLeaderboard(TopGroupResult leaderboardData) {
        return LeaderboardComponents.createLeaderboardTable(
                "Top Groups",
                "Name",
                leaderboardData != null ? leaderboardData.getGroups() : null,
                new LeaderboardComponents.LeaderboardItemRenderer<TopGroupResult.TopGroup>() {
                    @Override
                    public String getName(TopGroupResult.TopGroup group) {
                        return group.getGroupName() != null && !group.getGroupName().trim().isEmpty()
                                ? group.getGroupName()
                                : "Unknown Group";
                    }

                    @Override
                    public String getLootValue(TopGroupResult.TopGroup group) {
                        String loot = group.getTotalLoot();
                        return (loot != null && !loot.trim().isEmpty()) ? loot : "0 GP";
                    }

                    @Override
                    public Integer getRank(TopGroupResult.TopGroup group) {
                        return group.getRank();
                    }

                    @Override
                    public void onItemClick(TopGroupResult.TopGroup group) {
                        // Render instantly from the row data; enrich asynchronously.
                        showGroupDetailsFromRow(group);
                    }
                }
        );
    }

    private void obtainLeaderboardData() {
        LeaderboardComponents.loadLeaderboardAsync(
                leaderboardPlaceholder,
                () -> {
                    try {
                        return api.getTopGroups();
                    } catch (Exception e) {
                        return null;
                    }
                },
                this::showLeaderboard
        );
    }

    public void performGroupSearch(String directQuery) {
        String searchQuery;
        if (directQuery.equalsIgnoreCase("")) {
            searchQuery = searchField.getText().trim();
        } else {
            searchQuery = directQuery;
        }

        if (searchQuery.isEmpty()) {
            JOptionPane.showMessageDialog(contentPanel, "Please enter a group name to search for.");
            return;
        }


        // Show loading message
        showLoadingState();

        // Perform search in background. Keep the failure cause so the user can
        // tell "group doesn't exist" apart from "the API call failed".
        CompletableFuture.supplyAsync(() -> {
            try {
                return new SearchOutcome(api.searchGroup(searchQuery), null);
            } catch (Exception e) {
                return new SearchOutcome(null, e);
            }
        }).thenAccept(outcome -> {
            SwingUtilities.invokeLater(() -> {
                if (outcome.result != null) {
                    showGroupDetails(outcome.result);
                    // Load the lootboard image when group is found
                    if (outcome.result.getGroupDropTrackerId() != null) {
                        currentGroupId = outcome.result.getGroupDropTrackerId();
                        PanelElements.loadLootboardForGroup(currentGroupId);
                    }
                    PanelElements.cachedGroupName = outcome.result.getGroupName();
                } else if (outcome.error == null || isNotFound(outcome.error)) {
                    showSearchError("Group '" + searchQuery + "' was not found.");
                } else {
                    showSearchError("Search failed — the DropTracker API could not be reached. Please try again.");
                }
            });
        });
    }

    private static boolean isNotFound(Exception e) {
        String message = e.getMessage();
        return message != null && message.contains("status: 404");
    }

    private static class SearchOutcome {
        final GroupSearchResult result;
        final Exception error;

        SearchOutcome(GroupSearchResult result, Exception error) {
            this.result = result;
            this.error = error;
        }
    }

    private void showLoadingState() {
        contentPanel.removeAll();
        contentPanel.add(StateViews.loading("Searching for group…"));
        contentPanel.revalidate();
        contentPanel.repaint();
    }

    private void showSearchError(String message) {
        activeDetailGroupName = null;
        contentPanel.removeAll();

        JPanel errorPanel = StateViews.error(message, "Back to Search", () -> {
            searchField.setText("");
            showDefaultState();
        });

        contentPanel.add(errorPanel);
        contentPanel.revalidate();
        contentPanel.repaint();
    }

    /**
     * Instantly renders the group detail view from data already present in a top-groups
     * leaderboard row (name, rank, total loot, member count, top member), then
     * asynchronously enriches it with the full /group_search payload (description, icon,
     * discord link, recent submissions) once that arrives. Never blocks on the network.
     */
    private void showGroupDetailsFromRow(TopGroupResult.TopGroup row) {
        if (row == null || row.getGroupName() == null || row.getGroupName().trim().isEmpty()) {
            return;
        }
        final String groupName = row.getGroupName();

        // Build a partial result from the row's data and render it immediately.
        GroupSearchResult partial = new GroupSearchResult();
        partial.setGroupName(groupName);
        partial.setGroupDropTrackerId(row.getGroupId());
        GroupSearchResult.GroupStats stats = new GroupSearchResult.GroupStats();
        stats.setTotalMembers(row.getMemberCount() != null ? row.getMemberCount() : 0);
        stats.setGlobalRank(row.getRank() != null ? String.valueOf(row.getRank()) : null);
        stats.setMonthlyLoot(row.getTotalLoot());
        partial.setGroupStats(stats);
        partial.setGroupTopPlayer(row.getTopMemberString());
        showGroupDetails(partial, true);

        if (row.getGroupId() != null) {
            currentGroupId = row.getGroupId();
            PanelElements.loadLootboardForGroup(currentGroupId);
            PanelElements.cachedGroupName = groupName;
        }

        // Enrich in the background; drop the result if the user has navigated away.
        CompletableFuture.supplyAsync(() -> {
            try {
                return api.searchGroup(groupName);
            } catch (Exception e) {
                return null;
            }
        }).thenAccept(full -> SwingUtilities.invokeLater(() -> {
            if (full == null || !groupName.equals(activeDetailGroupName)) {
                return;
            }
            if (full.getGroupDropTrackerId() != null) {
                currentGroupId = full.getGroupDropTrackerId();
                PanelElements.loadLootboardForGroup(currentGroupId);
            }
            PanelElements.cachedGroupName = full.getGroupName();
            showGroupDetails(full);
        }));
    }

    private void showGroupDetails(GroupSearchResult groupResult) {
        showGroupDetails(groupResult, false);
    }

    /**
     * Renders the group detail card. When {@code partial} is true the view was built
     * from leaderboard-row data only, so the fields the row can't provide (description,
     * recent submissions) show loading placeholders instead of empty states.
     */
    private void showGroupDetails(GroupSearchResult groupResult, boolean partial) {
        activeDetailGroupName = groupResult.getGroupName();
        contentPanel.removeAll();

        // Match PlayerStatsPanel structure exactly - no custom borders
        JPanel groupInfoPanel = new JPanel();
        groupInfoPanel.setLayout(new BoxLayout(groupInfoPanel, BoxLayout.Y_AXIS));
        groupInfoPanel.setBackground(DropTrackerTheme.SURFACE_1);
        groupInfoPanel.setBorder(DropTrackerTheme.cardBorder(10, 10, 10, 10));

        // Group header panel - exactly like playerHeaderPanel with clear button
        JPanel groupHeaderPanel = new JPanel(new BorderLayout(10, 0));
        groupHeaderPanel.setBackground(DropTrackerTheme.SURFACE_1);
        groupHeaderPanel.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH - 40, 60));
        groupHeaderPanel.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 40, 60));
        groupHeaderPanel.setAlignmentX(Component.LEFT_ALIGNMENT);

        // Group icon
        BufferedImage placeholderImg = new BufferedImage(50, 50, BufferedImage.TYPE_INT_ARGB);
        JLabel groupIcon = new JLabel(new ImageIcon(placeholderImg));
        groupIcon.setBackground(DropTrackerTheme.SURFACE_2);
        groupIcon.setPreferredSize(new Dimension(50, 50));
        groupIcon.setMaximumSize(new Dimension(50, 50));
        groupIcon.setMinimumSize(new Dimension(50, 50));
        loadGroupIcon(groupIcon, groupResult.getGroupImagePath());

        // Group name and description
        JPanel groupNamePanel = new JPanel();
        groupNamePanel.setLayout(new BoxLayout(groupNamePanel, BoxLayout.Y_AXIS));
        groupNamePanel.setBackground(DropTrackerTheme.SURFACE_1);

        JLabel groupNameLabel = new JLabel(groupResult.getGroupName());
        groupNameLabel.setFont(FontManager.getRunescapeBoldFont());
        groupNameLabel.setForeground(DropTrackerTheme.TEXT);
        groupNameLabel.setAlignmentX(Component.LEFT_ALIGNMENT);

        String description = groupResult.getGroupDescription() != null
            ? groupResult.getGroupDescription()
            : (partial ? "Loading details…" : "");
        // Escaped: Swing resolves <img src> in HTML labels, so an unescaped server
        // description is an outbound request to a host of the server's choosing.
        JLabel groupDescLabel = new JLabel("<html>" + PanelElements.escapeHtml(description) + "</html>");
        groupDescLabel.setFont(FontManager.getRunescapeSmallFont());
        groupDescLabel.setForeground(DropTrackerTheme.TEXT_MUTED);
        groupDescLabel.setAlignmentX(Component.LEFT_ALIGNMENT);

        groupNamePanel.add(groupNameLabel);
        groupNamePanel.add(groupDescLabel);

        // Clear button for closing the search result
        JButton clearButton = LeaderboardComponents.createClearButton(() -> {
            searchField.setText("");
            showDefaultState();
        });

        groupHeaderPanel.add(groupIcon, BorderLayout.WEST);
        groupHeaderPanel.add(groupNamePanel, BorderLayout.CENTER);
        groupHeaderPanel.add(clearButton, BorderLayout.EAST);

        // Stats panel - exactly like playerStatsPanel
        JPanel statsPanel = new JPanel(new GridLayout(2, 2, 5, 5));
        statsPanel.setBackground(DropTrackerTheme.SURFACE_1);
        statsPanel.setBorder(new EmptyBorder(10, 0, 10, 0)); // Same as playerStatsPanel
        statsPanel.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, 100));
        statsPanel.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 40, 100));
        statsPanel.setAlignmentX(Component.LEFT_ALIGNMENT);

        GroupSearchResult.GroupStats groupStats = groupResult.getGroupStats();
        String memberText = groupStats != null ? String.valueOf(groupStats.getTotalMembers()) : "—";
        String rankText = (groupStats != null && groupStats.getGlobalRank() != null) ? "#" + groupStats.getGlobalRank() : "—";
        String lootText = (groupStats != null && groupStats.getMonthlyLoot() != null) ? groupStats.getMonthlyLoot() + " GP" : "—";
        String topPlayer = groupResult.getGroupTopPlayer();

        JPanel membersBox = PanelElements.createStatBox("Members", memberText);
        JPanel rankBox = PanelElements.createStatBox("Global Rank", rankText);
        JPanel lootBox = PanelElements.createStatBox("Monthly Loot", lootText);
        JPanel topPlayerBox = PanelElements.createStatBox("Top Player", topPlayer != null ? topPlayer : "—");
        if (topPlayer != null && !topPlayer.trim().isEmpty()) {
            topPlayerBox.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            topPlayerBox.addMouseListener(new MouseAdapter() {
                @Override
                public void mouseClicked(MouseEvent e) {
                    panel.selectPanel("players");
                    panel.updatePlayerPanel(topPlayer.split("\\(")[0].trim());
                }
            });
        }

        statsPanel.add(membersBox);
        statsPanel.add(rankBox);
        statsPanel.add(lootBox);
        statsPanel.add(topPlayerBox);

        // Action buttons - exactly like actionPanel
        JPanel actionPanel = new JPanel();
        actionPanel.setLayout(new FlowLayout(FlowLayout.CENTER, 10, 0));
        actionPanel.setBackground(DropTrackerTheme.SURFACE_1);
        actionPanel.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH - 40, 40));
        actionPanel.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 40, 40));
        actionPanel.setAlignmentX(Component.LEFT_ALIGNMENT);

        // The API sends an invite code, not a link: the discord.gg host is ours to decide.
        final HttpUrl inviteUrl = DropTrackerUrls.discordInvite(groupResult.getDiscordInviteCode());
        if (inviteUrl != null) {
            JButton joinButton = new JButton("Discord");
            DropTrackerTheme.styleButton(joinButton);
            joinButton.setMargin(new Insets(0, 5, 0, 5));
            joinButton.addActionListener(e -> LinkBrowser.browse(inviteUrl.toString()));
            actionPanel.add(joinButton);
        }

        JButton viewLootboardButton = PanelElements.createLootboardButton("View Lootboard", "Click to view the lootboard", () -> PanelElements.showLootboardForGroup(client, currentGroupId));
        actionPanel.add(viewLootboardButton);

        // Add components exactly like PlayerStatsPanel
        groupInfoPanel.add(groupHeaderPanel);
        groupInfoPanel.add(Box.createRigidArea(new Dimension(0, 10)));
        groupInfoPanel.add(statsPanel);
        groupInfoPanel.add(Box.createRigidArea(new Dimension(0, 10)));
        // Get recent submission data to draw
        List<RecentSubmission> recentSubmissions = groupResult.getGroupRecentSubmissions();
        if (recentSubmissions != null && !recentSubmissions.isEmpty()) {
            groupInfoPanel.add(PanelElements.createRecentSubmissionPanel(recentSubmissions, itemManager, client, true));
        } else if (partial) {
            groupInfoPanel.add(PanelElements.createRecentSubmissionsPlaceholder("Loading recent activity…"));
        } else {
            groupInfoPanel.add(PanelElements.createRecentSubmissionsPlaceholder("No recent submissions available"));
        }
        groupInfoPanel.add(Box.createRigidArea(new Dimension(0, 10)));
        groupInfoPanel.add(actionPanel);

        contentPanel.add(groupInfoPanel);
        contentPanel.revalidate();
        contentPanel.repaint();
    }

    private void openGroupPage() {
        try {
            LinkBrowser.browse(DropTrackerUrls.web("groups").toString());
        } catch (Exception e) {
            // Fallback: copy URL to clipboard or show message
            JOptionPane.showMessageDialog(contentPanel,
                    "Could not open browser. Please visit:\nhttps://www.droptracker.io/groups",
                    "Group Page",
                    JOptionPane.INFORMATION_MESSAGE);
        }
    }

    private void openCreateGroupPage() {
        try {
            LinkBrowser.browse(DropTrackerUrls.web("wiki", "create-group").toString());
        } catch (Exception e) {
            // Fallback: copy URL to clipboard or show message
            JOptionPane.showMessageDialog(contentPanel,
                    "Could not open browser. Please visit:\nhttps://droptracker.io/wiki/create-group",
                    "Create Group Guide",
                    JOptionPane.INFORMATION_MESSAGE);
        }
    }

    /**
     * Downloads the group icon, scales it to 50×50, then swaps it into the given label.
     * This runs off the EDT to avoid blocking the UI.
     *
     * @param imagePath path under {@code /img/} supplied by the API, e.g.
     *                  {@code "clans/2/icon.png"}. Not a URL — the host is decided
     *                  by {@link DropTrackerUrls#image}.
     */
    private void loadGroupIcon(JLabel iconLabel, String imagePath) {
        if (imagePath == null || imagePath.trim().isEmpty()) {
            return; // nothing to load
        }

        // we can't load gifs in swing panels natively, so we swap for a png alternative hoping it exists
        String pngPath = imagePath.replace(".gif", ".png");
        HttpUrl pngUrl = DropTrackerUrls.image(pngPath);
        HttpUrl originalUrl = DropTrackerUrls.image(imagePath);

        CompletableFuture.supplyAsync(() -> {
            ImageIcon icon = fetchScaledIcon(pngUrl);
            if (icon == null && !pngPath.equals(imagePath)) {
                // Fall back to the original path if the .png swap didn't exist.
                icon = fetchScaledIcon(originalUrl);
            }
            return icon;
        }).thenAccept(icon -> {
            if (icon != null) {
                SwingUtilities.invokeLater(() -> iconLabel.setIcon(icon));
            }
        });
    }

    private ImageIcon fetchScaledIcon(@Nullable HttpUrl url) {
        if (url == null) {
            return null;
        }
        Request request = new Request.Builder().url(url).build();
        try (Response response = httpClient.newCall(request).execute()) {
            ResponseBody body = response.body();
            if (!response.isSuccessful() || body == null) {
                return null;
            }
            BufferedImage img = ImageIO.read(body.byteStream());
            if (img == null) {
                return null;
            }
            Image scaled = img.getScaledInstance(50, 50, Image.SCALE_SMOOTH);
            return new ImageIcon(scaled);
        } catch (Exception e) {
            return null;
        }
    }

}

package io.droptracker.ui.pages;

import io.droptracker.api.DropTrackerUrls;
import io.droptracker.DropTrackerConfig;
import io.droptracker.DropTrackerPlugin;
import io.droptracker.api.DropTrackerApi;
import io.droptracker.models.api.PlayerSearchResult;
import io.droptracker.models.api.TopPlayersResult;
import io.droptracker.models.submissions.RecentSubmission;
import io.droptracker.ui.components.LeaderboardComponents;
import io.droptracker.ui.components.StateViews;
import io.droptracker.ui.components.PanelElements;
import io.droptracker.ui.DropTrackerTheme;
import net.runelite.api.Client;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.LinkBrowser;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.List;
import java.util.concurrent.CompletableFuture;

public class PlayerStatsPanel {
    private final Client client;
    private final DropTrackerConfig config;
    private final DropTrackerApi api;
    private final DropTrackerPlugin plugin;
    private final ItemManager itemManager;

    // UI components that we need to update
    private JPanel contentPanel;
    private JTextField searchField;
    private JPanel leaderboardPlaceholder;

    public PlayerStatsPanel(Client client, DropTrackerPlugin plugin, DropTrackerConfig config, DropTrackerApi api, ItemManager itemManager) {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        this.api = api;
        this.itemManager = itemManager;
    }

    public JPanel create() {
        var mainPanel = new JPanel();
        mainPanel.setLayout(new BoxLayout(mainPanel, BoxLayout.Y_AXIS));
        mainPanel.setBackground(DropTrackerTheme.SURFACE_0);

        // Header section with title and search using LeaderboardComponents
        LeaderboardComponents.HeaderResult headerResult = LeaderboardComponents.createHeaderPanel(
                "DropTracker - Players",
                "Search for a player",
                () -> performPlayerSearch("")
        );
        searchField = headerResult.searchField;

        // Content panel that will change based on state
        contentPanel = new JPanel();
        contentPanel.setLayout(new BoxLayout(contentPanel, BoxLayout.Y_AXIS));
        contentPanel.setBackground(DropTrackerTheme.SURFACE_0);
        contentPanel.setAlignmentX(Component.LEFT_ALIGNMENT);

        // Show default state
        showDefaultState();

        // Add components to main panel - match GroupPanel structure
        mainPanel.add(headerResult.panel);
        mainPanel.add(Box.createRigidArea(new Dimension(0, 10)));
        mainPanel.add(contentPanel);
        mainPanel.add(Box.createVerticalGlue());

        return mainPanel;
    }

    private void showDefaultState() {
        contentPanel.removeAll();

        // Create center panel for instructions and leaderboard
        JPanel defaultPanel = new JPanel();
        defaultPanel.setLayout(new BoxLayout(defaultPanel, BoxLayout.Y_AXIS));
        defaultPanel.setBackground(DropTrackerTheme.SURFACE_0);
        defaultPanel.setAlignmentX(Component.CENTER_ALIGNMENT);

        // Add some spacing
        defaultPanel.add(Box.createRigidArea(new Dimension(0, 5)));

        // Instructions text
        JLabel instructionLabel = new JLabel("Search for a player by name above");
        instructionLabel.setFont(FontManager.getRunescapeFont());
        instructionLabel.setForeground(DropTrackerTheme.TEXT_MUTED);
        instructionLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
        instructionLabel.setHorizontalAlignment(JLabel.CENTER);

        defaultPanel.add(instructionLabel);
        defaultPanel.add(Box.createRigidArea(new Dimension(0, 5)));

        // Get current player and add button if logged in
        String playerName = (config.lastAccountName() != null) ? config.lastAccountName() : null;

        if (playerName != null && !"Not logged in".equals(playerName)) {
            // Button to view current player stats
            JPanel buttonPanel = new JPanel(new FlowLayout(FlowLayout.CENTER));
            buttonPanel.setBackground(DropTrackerTheme.SURFACE_0);
            buttonPanel.setAlignmentX(Component.CENTER_ALIGNMENT);
            buttonPanel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));
            buttonPanel.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH, 30));

            JButton viewStatsButton = new JButton("View My Stats (" + playerName + ")");
            DropTrackerTheme.styleButton(viewStatsButton);
            viewStatsButton.setPreferredSize(new Dimension(200, 30));
            viewStatsButton.setToolTipText("View your DropTracker statistics");
            viewStatsButton.addActionListener(e -> performPlayerSearch(playerName));

            buttonPanel.add(viewStatsButton);
            defaultPanel.add(buttonPanel);
            defaultPanel.add(Box.createRigidArea(new Dimension(0, 10)));
        }

        if (config.useApi()) {
            // Create placeholder for leaderboard (same pattern as GroupPanel)
            leaderboardPlaceholder = StateViews.loading("Loading top players…");
            defaultPanel.add(leaderboardPlaceholder);

            // Start loading data
            obtainPlayerLeaderboardData();
        }

        defaultPanel.add(Box.createVerticalGlue());

        contentPanel.add(defaultPanel);
        contentPanel.revalidate();
        contentPanel.repaint();
    }

    // New method to obtain player leaderboard data (similar to GroupPanel)
    private void obtainPlayerLeaderboardData() {
        LeaderboardComponents.loadLeaderboardAsync(
                leaderboardPlaceholder,
                () -> {
                    try {
                        return api.getTopPlayers();
                    } catch (Exception e) {
                        return null;
                    }
                },
                this::showPlayerLeaderboard
        );
    }

    // New method to show player leaderboard using LeaderboardComponents
    private JPanel showPlayerLeaderboard(TopPlayersResult leaderboardData) {
        return LeaderboardComponents.createLeaderboardTable(
                "Top Players",
                "Player",
                leaderboardData != null ? leaderboardData.getPlayers() : null,
                new LeaderboardComponents.LeaderboardItemRenderer<TopPlayersResult.TopPlayer>() {
                    @Override
                    public String getName(TopPlayersResult.TopPlayer player) {
                        return player.getPlayerName() != null ? player.getPlayerName() : "Unknown Player";
                    }

                    @Override
                    public String getLootValue(TopPlayersResult.TopPlayer player) {
                        String loot = player.getTotalLoot();
                        return (loot != null && !loot.trim().isEmpty()) ? loot : "0 GP";
                    }

                    @Override
                    public Integer getRank(TopPlayersResult.TopPlayer player) {
                        return player.getRank();
                    }

                    @Override
                    public void onItemClick(TopPlayersResult.TopPlayer player) {
                        // Search for this player when clicked
                        performPlayerSearch(player.getPlayerName());
                    }
                }
        );
    }

    public void performPlayerSearch(String searchQuery) {
        String toSearch;
        if (searchQuery.isEmpty()) {
            if (searchField != null && searchField.getText() != null && !searchField.getText().isEmpty()) {
                toSearch = searchField.getText().trim();
            } else {
                if (plugin.getLocalPlayerName() != null && !plugin.getLocalPlayerName().isEmpty()) {
                    toSearch = plugin.getLocalPlayerName();
                } else {
                    return;
                }
            }
        } else {
            toSearch = searchQuery;
        }


        // Show loading message
        contentPanel.removeAll();
        contentPanel.add(StateViews.loading("Searching for player…"));
        contentPanel.revalidate();
        contentPanel.repaint();

        // Perform search in background. Keep the failure cause so the user can
        // tell "player doesn't exist" apart from "the API call failed".
        CompletableFuture.supplyAsync(() -> {
            try {
                return new SearchOutcome(api.lookupPlayer(toSearch), null);
            } catch (Exception e) {
                return new SearchOutcome(null, e);
            }
        }).thenAccept(outcome -> {
            SwingUtilities.invokeLater(() -> {
                if (outcome.result != null) {
                    showPlayerDetails(outcome.result);
                } else if (outcome.error == null || isNotFound(outcome.error)) {
                    showSearchError("Player '" + toSearch + "' was not found.");
                } else {
                    showSearchError("Search failed — the DropTracker API could not be reached. Please try again.");
                }
            });
        });
    }

    private static boolean isNotFound(Exception e) {
        String message = e.getMessage();
        return message != null && message.contains("status: 404");
    }

    private static class SearchOutcome {
        final PlayerSearchResult result;
        final Exception error;

        SearchOutcome(PlayerSearchResult result, Exception error) {
            this.result = result;
            this.error = error;
        }
    }

    private void showSearchError(String message) {
        contentPanel.removeAll();

        JPanel errorPanel = StateViews.error(message, "Back to Search", () -> {
            searchField.setText("");
            showDefaultState();
        });

        contentPanel.add(errorPanel);
        contentPanel.revalidate();
        contentPanel.repaint();
    }

    private void showPlayerDetails(PlayerSearchResult playerResult) {
        contentPanel.removeAll();

        // Match GroupPanel structure exactly
        JPanel playerInfoPanel = new JPanel();
        playerInfoPanel.setLayout(new BoxLayout(playerInfoPanel, BoxLayout.Y_AXIS));
        playerInfoPanel.setBackground(DropTrackerTheme.SURFACE_1);
        playerInfoPanel.setBorder(DropTrackerTheme.cardBorder(10, 10, 10, 10));

        // Player header panel - like groupHeaderPanel
        JPanel playerHeaderPanel = new JPanel(new BorderLayout(10, 0));
        playerHeaderPanel.setBackground(DropTrackerTheme.SURFACE_1);
        playerHeaderPanel.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH - 40, 60));
        playerHeaderPanel.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 40, 60));
        playerHeaderPanel.setAlignmentX(Component.LEFT_ALIGNMENT);

        // Player name and description
        JPanel playerNamePanel = new JPanel();
        playerNamePanel.setLayout(new BoxLayout(playerNamePanel, BoxLayout.Y_AXIS));
        playerNamePanel.setBackground(DropTrackerTheme.SURFACE_1);

        JLabel playerNameLabel = new JLabel(playerResult.getPlayerName());
        playerNameLabel.setFont(FontManager.getRunescapeBoldFont());
        playerNameLabel.setForeground(DropTrackerTheme.TEXT);
        playerNameLabel.setAlignmentX(Component.LEFT_ALIGNMENT);

        String statusText = playerResult.isRegistered() ? "Registered Player" : "Not registered!";
        JLabel playerDescLabel = new JLabel(statusText);
        playerDescLabel.setFont(FontManager.getRunescapeSmallFont());
        playerDescLabel.setForeground(playerResult.isRegistered() ? DropTrackerTheme.GREEN : DropTrackerTheme.EMBER);
        playerDescLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
        if (!playerResult.isRegistered()) {
            playerDescLabel.setToolTipText("<html>This account has not been claimed on DropTracker.<br/>"
                + "Claim your in-game name in our Discord to register.</html>");
        }

        playerNamePanel.add(playerNameLabel);
        playerNamePanel.add(Box.createRigidArea(new Dimension(0, 5)));
        playerNamePanel.add(playerDescLabel);

        // Add groups information if available
        if (playerResult.getGroups() != null && !playerResult.getGroups().isEmpty()) {
            JPanel groupsPanel = createGroupsPanel(playerResult.getGroups());
            playerNamePanel.add(groupsPanel);
        }

        // Clear button for closing the search result
        JButton clearButton = LeaderboardComponents.createClearButton(() -> {
            searchField.setText("");
            showDefaultState();
        });

        playerHeaderPanel.add(playerNamePanel, BorderLayout.CENTER);
        playerHeaderPanel.add(clearButton, BorderLayout.EAST);

        // Stats panel - exactly like GroupPanel statsPanel
        JPanel statsPanel = new JPanel(new GridLayout(2, 2, 5, 5));
        statsPanel.setBackground(DropTrackerTheme.SURFACE_1);
        statsPanel.setBorder(new EmptyBorder(10, 0, 10, 0));
        statsPanel.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, 100));
        statsPanel.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 40, 100));
        statsPanel.setAlignmentX(Component.LEFT_ALIGNMENT);

        // Format numbers nicely
        String globalRankFormatted = "#" + playerResult.getGlobalRank();

        // Format top NPC information

        JPanel totalLootBox = PanelElements.createStatBox("Total Loot", playerResult.getTotalLoot() + " GP");
        JPanel globalRankBox = PanelElements.createStatBox("Global Rank", globalRankFormatted);
        JPanel playerPointsBox = PanelElements.createStatBox("Lifetime Points", playerResult.getPoints() + " pts");

        statsPanel.add(totalLootBox);
        statsPanel.add(globalRankBox);
        statsPanel.add(playerPointsBox);

        playerPointsBox.addMouseListener(new java.awt.event.MouseAdapter() {
            @Override
            public void mouseClicked(java.awt.event.MouseEvent e) {
                LinkBrowser.browse(DropTrackerUrls.web("wiki", "points").toString());
            }

            @Override
            public void mouseEntered(java.awt.event.MouseEvent e) {
                playerPointsBox.setBackground(DropTrackerTheme.SURFACE_3);
                playerPointsBox.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            }

            @Override
            public void mouseExited(java.awt.event.MouseEvent e) {
                playerPointsBox.setBackground(DropTrackerTheme.SURFACE_2);
                playerPointsBox.setCursor(Cursor.getDefaultCursor());
            }
        });
        playerPointsBox.setToolTipText("View more info about points (click to open wiki)");

        // Action buttons - exactly like GroupPanel actionPanel
        JPanel actionPanel = new JPanel();
        actionPanel.setLayout(new FlowLayout(FlowLayout.CENTER, 10, 0));
        actionPanel.setBackground(DropTrackerTheme.SURFACE_1);
        actionPanel.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH - 40, 40));
        actionPanel.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 40, 40));
        actionPanel.setAlignmentX(Component.LEFT_ALIGNMENT);

        JButton refreshButton = new JButton("Refresh Stats");
        DropTrackerTheme.styleButton(refreshButton);
        refreshButton.setMargin(new Insets(0, 5, 0, 5));
        refreshButton.addActionListener(e -> {
            performPlayerSearch(playerResult.getPlayerName());
        });

        JButton viewProfileButton = new JButton("View Profile");
        viewProfileButton.setIcon(PanelElements.getExternalLinkIcon());
        DropTrackerTheme.styleButton(viewProfileButton);
        viewProfileButton.setMargin(new Insets(0, 5, 0, 5));
        viewProfileButton.addActionListener(e -> {
            if (playerResult.getDropTrackerPlayerId() != null) {
                LinkBrowser.browse(DropTrackerUrls.web("players", String.valueOf(playerResult.getDropTrackerPlayerId()), "view").toString());
            } else {
                LinkBrowser.browse(DropTrackerUrls.web("players", playerResult.getPlayerName(), "view").toString());
            }
        });

        actionPanel.add(refreshButton);
        actionPanel.add(viewProfileButton);

        // Add components exactly like GroupPanel
        playerInfoPanel.add(playerHeaderPanel);
        playerInfoPanel.add(Box.createRigidArea(new Dimension(0, 10)));
        playerInfoPanel.add(statsPanel);
        playerInfoPanel.add(Box.createRigidArea(new Dimension(0, 10)));

        // Add recent submissions panel if available
        if (playerResult.getRecentSubmissions() != null && !playerResult.getRecentSubmissions().isEmpty()) {
            List<RecentSubmission> recentSubmissions = playerResult.getRecentSubmissions();
            playerInfoPanel.add(PanelElements.createRecentSubmissionPanel(recentSubmissions, itemManager, client, false));
        } else {
            playerInfoPanel.add(PanelElements.createRecentSubmissionsPlaceholder("No recent submissions available"));
        }
        playerInfoPanel.add(Box.createRigidArea(new Dimension(0, 10)));

        playerInfoPanel.add(actionPanel);

        contentPanel.add(playerInfoPanel);
        contentPanel.revalidate();
        contentPanel.repaint();
    }

    private JPanel createGroupsPanel(List<PlayerSearchResult.PlayerGroup> groups) {
        if (groups == null || groups.isEmpty()) {
            return new JPanel(); // Return empty panel if no groups
        }

        JPanel groupsContainer = new JPanel();
        groupsContainer.setLayout(new BoxLayout(groupsContainer, BoxLayout.Y_AXIS));
        groupsContainer.setBackground(DropTrackerTheme.SURFACE_1);
        groupsContainer.setAlignmentX(Component.LEFT_ALIGNMENT);

        // Groups header
        JLabel groupsHeaderLabel = new JLabel("Groups:");
        groupsHeaderLabel.setFont(FontManager.getRunescapeSmallFont());
        groupsHeaderLabel.setForeground(DropTrackerTheme.TEXT_MUTED);
        groupsHeaderLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
        groupsContainer.add(groupsHeaderLabel);

        // Add each group as a separate label for proper scaling
        for (PlayerSearchResult.PlayerGroup group : groups) {
            StringBuilder groupText = new StringBuilder("- ");
            groupText.append(group.getName());
            if (group.getMembers() != null) {
                groupText.append(" (").append(group.getMembers()).append(" members)");
            }

            JLabel groupLabel = new JLabel(groupText.toString());
            groupLabel.setFont(FontManager.getRunescapeSmallFont());
            groupLabel.setForeground(DropTrackerTheme.TEXT_MUTED);
            groupLabel.setAlignmentX(Component.LEFT_ALIGNMENT);

            groupsContainer.add(groupLabel);
        }

        return groupsContainer;
    }

}

package io.droptracker.ui.pages;

import io.droptracker.DropTrackerConfig;
import io.droptracker.api.DropTrackerApi;
import io.droptracker.models.api.GroupConfig;
import io.droptracker.models.submissions.SubmissionStatus;
import io.droptracker.models.submissions.ValidSubmission;
import io.droptracker.service.SubmissionManager;
import io.droptracker.ui.DropTrackerPanel;
import io.droptracker.ui.DropTrackerTheme;
import io.droptracker.ui.components.PanelIcons;
import io.droptracker.ui.components.PanelElements;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * The "Activity" tab: this session's submission feed (promoted from the old buried
 * "API" tab), a compact session stats row, and the per-group configuration summary.
 */
public class ActivityPanel {
    private final DropTrackerConfig config;
    private final DropTrackerApi api;
    private final SubmissionManager submissionManager;
    private final DropTrackerPanel mainPanel;

    private JPanel activityRoot;
    private JPanel statsCard;
    private JPanel feedCard;
    private JPanel feedListPanel;
    private Timer statusUpdateTimer;

    private JPanel groupConfigPanel;
    private JPanel groupsContainerPanel;
    private JScrollPane groupsScrollPane;
    private final Map<String, Boolean> groupExpandStates = new HashMap<>();

    public ActivityPanel(
        DropTrackerConfig config,
        DropTrackerApi api,
        SubmissionManager submissionManager,
        DropTrackerPanel mainPanel
    ) {
        this.config = config;
        this.api = api;
        this.submissionManager = submissionManager;
        this.mainPanel = mainPanel;
    }

    public JPanel create() {
        activityRoot = new JPanel();
        activityRoot.setLayout(new BoxLayout(activityRoot, BoxLayout.Y_AXIS));
        activityRoot.setBackground(DropTrackerTheme.SURFACE_0);
        activityRoot.setBorder(new EmptyBorder(5, 0, 5, 0));

        statsCard = buildStatsCard();
        feedCard = buildFeedCard();
        JPanel configCard = buildGroupConfigCard();

        activityRoot.add(statsCard);
        activityRoot.add(Box.createRigidArea(new Dimension(0, 6)));
        activityRoot.add(feedCard);
        activityRoot.add(Box.createRigidArea(new Dimension(0, 6)));
        activityRoot.add(configCard);
        activityRoot.add(Box.createVerticalGlue());

        refresh();

        if (config.pollUpdates()) {
            statusUpdateTimer = new Timer(10000, e -> {
                updateStatusLabel();
                refreshStatistics();
                refreshGroupConfigs();
                if (config.useApi() && submissionManager.hasActiveSubmissions()) {
                    submissionManager.checkPendingStatuses();
                    refreshSubmissions();
                }
            });
            statusUpdateTimer.start();
        }

        JPanel wrapperPanel = new JPanel(new BorderLayout());
        wrapperPanel.setBackground(DropTrackerTheme.SURFACE_0);
        wrapperPanel.add(activityRoot, BorderLayout.CENTER);
        return wrapperPanel;
    }

    /* ===================== Session stats ===================== */

    private JPanel buildStatsCard() {
        JPanel card = new JPanel();
        card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
        card.setBackground(DropTrackerTheme.SURFACE_1);
        card.setBorder(DropTrackerTheme.cardBorder(8, 8, 8, 8));
        card.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, 70));
        card.setAlignmentX(Component.LEFT_ALIGNMENT);

        rebuildStatsCard(card);
        return card;
    }

    private void rebuildStatsCard(JPanel card) {
        card.removeAll();

        JLabel title = new JLabel("This Session");
        title.setFont(FontManager.getRunescapeBoldFont());
        title.setForeground(DropTrackerTheme.TEXT);
        title.setAlignmentX(Component.CENTER_ALIGNMENT);
        card.add(title);
        card.add(Box.createRigidArea(new Dimension(0, 4)));

        int sent = submissionManager.getTotalSubmissions();
        int processed = submissionManager.getNotificationsSent();
        int failed = submissionManager.getFailedSubmissions();

        JPanel row = new JPanel(new FlowLayout(FlowLayout.CENTER, 8, 0));
        row.setBackground(DropTrackerTheme.SURFACE_1);
        row.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH - 30, 16));
        row.add(compactStat("Sent", String.valueOf(sent), DropTrackerTheme.GOLD));
        row.add(compactStat("Processed", String.valueOf(processed), DropTrackerTheme.GREEN));
        row.add(compactStat("Failed", String.valueOf(failed), DropTrackerTheme.RED));
        row.setToolTipText("Submissions that qualified for notifications in your groups this session");
        card.add(row);

        JLabel gpLabel = new JLabel("Session loot: " + formatValue(submissionManager.getTotalValue()) + " GP");
        gpLabel.setFont(FontManager.getRunescapeSmallFont());
        gpLabel.setForeground(DropTrackerTheme.TEXT_MUTED);
        gpLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
        card.add(Box.createRigidArea(new Dimension(0, 3)));
        card.add(gpLabel);

        card.revalidate();
        card.repaint();
    }

    private JPanel compactStat(String label, String value, Color valueColor) {
        JPanel stat = new JPanel(new FlowLayout(FlowLayout.LEFT, 3, 0));
        stat.setBackground(DropTrackerTheme.SURFACE_1);

        JLabel labelComponent = new JLabel(label);
        labelComponent.setFont(FontManager.getRunescapeSmallFont());
        labelComponent.setForeground(DropTrackerTheme.TEXT_MUTED);

        JLabel valueComponent = new JLabel(value);
        valueComponent.setFont(FontManager.getRunescapeSmallFont());
        valueComponent.setForeground(valueColor);

        stat.add(labelComponent);
        stat.add(valueComponent);
        return stat;
    }

    private String formatValue(long value) {
        if (value >= 1_000_000) {
            return String.format("%.1fM", value / 1_000_000.0);
        } else if (value >= 1_000) {
            return String.format("%.1fK", value / 1_000.0);
        }
        return String.valueOf(value);
    }

    /* ===================== Submission feed ===================== */

    private JPanel buildFeedCard() {
        JPanel card = new JPanel();
        card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
        card.setBackground(DropTrackerTheme.SURFACE_1);
        card.setBorder(DropTrackerTheme.cardBorder(8, 8, 8, 8));
        card.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, 320));
        card.setAlignmentX(Component.LEFT_ALIGNMENT);

        JLabel title = new JLabel("Submission Feed");
        title.setFont(FontManager.getRunescapeBoldFont());
        title.setForeground(DropTrackerTheme.TEXT);
        title.setAlignmentX(Component.CENTER_ALIGNMENT);
        card.add(title);
        card.add(Box.createRigidArea(new Dimension(0, 4)));

        feedListPanel = new JPanel();
        feedListPanel.setLayout(new BoxLayout(feedListPanel, BoxLayout.Y_AXIS));
        feedListPanel.setBackground(DropTrackerTheme.SURFACE_1);

        JScrollPane scrollPane = new JScrollPane(feedListPanel);
        scrollPane.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
        scrollPane.setVerticalScrollBarPolicy(ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED);
        scrollPane.setBorder(null);
        scrollPane.setBackground(DropTrackerTheme.SURFACE_1);
        scrollPane.getViewport().setBackground(DropTrackerTheme.SURFACE_1);
        scrollPane.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 30, 260));
        scrollPane.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH - 30, 280));
        card.add(scrollPane);

        return card;
    }

    public void refreshSubmissions() {
        if (feedListPanel == null) {
            return;
        }

        feedListPanel.removeAll();

        List<ValidSubmission> submissions = submissionManager.getValidSubmissions();
        if (submissions != null && !submissions.isEmpty()) {
            // Newest first: submissions are appended chronologically.
            List<ValidSubmission> newestFirst = new ArrayList<>(submissions);
            Collections.reverse(newestFirst);
            for (ValidSubmission submission : newestFirst) {
                feedListPanel.add(createFeedRow(submission));
                feedListPanel.add(Box.createRigidArea(new Dimension(0, 3)));
            }
        } else {
            JLabel emptyLabel = new JLabel("<html>Qualifying drops and achievements will appear here as you receive them. Failed sends can be retried.</html>");
            emptyLabel.setFont(FontManager.getRunescapeSmallFont());
            emptyLabel.setForeground(DropTrackerTheme.TEXT_MUTED);
            emptyLabel.setBorder(new EmptyBorder(5, 5, 5, 5));
            feedListPanel.add(emptyLabel);
        }

        feedListPanel.revalidate();
        feedListPanel.repaint();
    }

    private JPanel createFeedRow(ValidSubmission submission) {
        JPanel row = new JPanel(new BorderLayout(5, 0));
        row.setBackground(DropTrackerTheme.SURFACE_2);
        row.setBorder(DropTrackerTheme.cardBorder(4, 5, 4, 5));
        row.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 40, 42));
        row.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH - 40, 42));

        // Type indicator
        JLabel typeLabel = new JLabel(submission.getTypeShortLabel());
        typeLabel.setFont(FontManager.getRunescapeSmallFont());
        typeLabel.setForeground(typeColor(submission.getTypeShortLabel()));
        typeLabel.setHorizontalAlignment(SwingConstants.CENTER);
        typeLabel.setPreferredSize(new Dimension(32, 32));
        row.add(typeLabel, BorderLayout.WEST);

        // Name + timestamp
        JPanel textPanel = new JPanel();
        textPanel.setLayout(new BoxLayout(textPanel, BoxLayout.Y_AXIS));
        textPanel.setBackground(DropTrackerTheme.SURFACE_2);

        String displayText = submission.getDisplayText();
        JLabel nameLabel = new JLabel(displayText.length() > 24 ? displayText.substring(0, 21) + "..." : displayText);
        nameLabel.setFont(FontManager.getRunescapeSmallFont());
        nameLabel.setForeground(DropTrackerTheme.TEXT);
        nameLabel.setAlignmentX(Component.LEFT_ALIGNMENT);

        JPanel metaRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
        metaRow.setBackground(DropTrackerTheme.SURFACE_2);
        metaRow.setAlignmentX(Component.LEFT_ALIGNMENT);

        String timestamp = formatReceivedTime(submission.getTimeReceived());
        if (timestamp != null) {
            JLabel timeLabel = new JLabel(timestamp);
            timeLabel.setFont(FontManager.getRunescapeSmallFont());
            timeLabel.setForeground(DropTrackerTheme.TEXT_MUTED);
            metaRow.add(timeLabel);
        }
        metaRow.add(statusChip(submission.getStatus()));

        textPanel.add(nameLabel);
        textPanel.add(metaRow);
        row.add(textPanel, BorderLayout.CENTER);

        // Actions: retry for failed submissions, dismiss for everything
        JPanel actions = new JPanel(new FlowLayout(FlowLayout.RIGHT, 2, 0));
        actions.setBackground(DropTrackerTheme.SURFACE_2);

        if (submission.getStatus() == SubmissionStatus.FAILED) {
            // Painted icon: the RuneScape fonts have no "↻" glyph, so its
            // colour rides on the icon rather than the foreground.
            JButton retryButton = smallActionButton("", "Retry sending this submission");
            retryButton.setIcon(PanelIcons.refresh(DropTrackerTheme.EMBER, 11));
            retryButton.setForeground(DropTrackerTheme.EMBER);
            retryButton.addActionListener(e -> {
                submissionManager.retrySubmission(submission);
                refreshSubmissions();
            });
            actions.add(retryButton);
        }

        JButton dismissButton = smallActionButton("×", "Remove from list");
        dismissButton.setForeground(DropTrackerTheme.RED);
        dismissButton.addActionListener(e -> {
            submissionManager.removeSubmission(submission);
            refresh();
        });
        actions.add(dismissButton);

        row.add(actions, BorderLayout.EAST);

        row.setToolTipText(buildSubmissionTooltip(submission));
        return row;
    }

    private JButton smallActionButton(String glyph, String tooltip) {
        JButton button = new JButton(glyph);
        button.setFont(FontManager.getRunescapeSmallFont());
        button.setPreferredSize(new Dimension(20, 20));
        button.setMargin(new Insets(0, 0, 0, 0));
        button.setFocusPainted(false);
        button.setContentAreaFilled(true);
        button.setOpaque(true);
        button.setBackground(DropTrackerTheme.SURFACE_3);
        button.setBorder(BorderFactory.createLineBorder(DropTrackerTheme.SURFACE_3, 1));
        button.setToolTipText(tooltip);
        return button;
    }

    private JLabel statusChip(SubmissionStatus status) {
        if (status == null) {
            return DropTrackerTheme.chip("Unknown", DropTrackerTheme.STONE);
        }
        switch (status) {
            case PROCESSED:
                return DropTrackerTheme.chip("Processed", DropTrackerTheme.GREEN);
            case SENT:
                return DropTrackerTheme.chip("Sent", DropTrackerTheme.GREEN);
            case FAILED:
                return DropTrackerTheme.chip("Failed", DropTrackerTheme.RED);
            case PENDING:
            case SENDING:
            case RETRYING:
            default:
                return DropTrackerTheme.chip("Pending", DropTrackerTheme.EMBER);
        }
    }

    private Color typeColor(String shortLabel) {
        switch (shortLabel) {
            case "DROP":
                return DropTrackerTheme.GOLD;
            case "CLOG":
                return DropTrackerTheme.EMBER;
            case "PB":
                return DropTrackerTheme.GOLD_BRIGHT;
            case "CA":
                return new Color(0xc98bd8);
            case "PET":
                return DropTrackerTheme.GREEN;
            case "LVL":
                return new Color(0x8fb8d8);
            case "QST":
                return DropTrackerTheme.TEXT_MUTED;
            default:
                return DropTrackerTheme.TEXT;
        }
    }

    private String buildSubmissionTooltip(ValidSubmission submission) {
        StringBuilder tooltip = new StringBuilder();
        tooltip.append("<html><div style='font-size: 10px; line-height: 1.2; padding: 3px;'>");

        tooltip.append("<div style='color: #ffb83f; font-weight: bold; margin-bottom: 3px;'>")
               .append(submission.getTypeShortLabel()).append(" SUBMISSION</div>");

        tooltip.append("<div style='color: #efe6d2; margin-bottom: 3px;'>")
               .append(submission.getDisplayText()).append("</div>");

        SubmissionStatus status = submission.getStatus();
        String statusColor = status != null ? status.getHexColor() : "#808080";
        tooltip.append("<div style='color: ").append(statusColor).append("; margin-bottom: 3px;'>")
               .append("Status: ").append(submission.getStatusDescription()).append("</div>");

        if (submission.getGroupIds() != null && submission.getGroupIds().length > 0) {
            tooltip.append("<div style='color: #d8c9a3; margin-bottom: 3px;'>")
                   .append("Configured for ").append(submission.getGroupIds().length).append(" group(s)</div>");
        }

        String receivedAt = formatReceivedTime(submission.getTimeReceived());
        if (receivedAt != null) {
            tooltip.append("<div style='color: #d8c9a3; margin-bottom: 3px;'>")
                   .append("Received: ").append(receivedAt).append("</div>");
        }

        if (submission.getRetryAttempts() > 0) {
            tooltip.append("<div style='color: #ff8c42; margin-bottom: 3px;'>")
                   .append("Retry attempts: ").append(submission.getRetryAttempts()).append("</div>");
        }

        if (submission.getLastFailureReason() != null && !submission.getLastFailureReason().isEmpty()) {
            tooltip.append("<div style='color: #e05c4d; margin-bottom: 3px;'>")
                   .append("Last failure: ").append(submission.getLastFailureReason()).append("</div>");
        }

        tooltip.append("</div></html>");
        return tooltip.toString();
    }

    /** Formats the ISO timeReceived value into a short human-readable time, or null. */
    private String formatReceivedTime(String isoTime) {
        if (isoTime == null || isoTime.isEmpty()) {
            return null;
        }
        try {
            java.time.LocalDateTime received = java.time.LocalDateTime.parse(isoTime, java.time.format.DateTimeFormatter.ISO_DATE_TIME);
            return received.format(java.time.format.DateTimeFormatter.ofPattern("HH:mm:ss"));
        } catch (Exception e) {
            return isoTime;
        }
    }

    /* ===================== Group config summary ===================== */

    private JPanel buildGroupConfigCard() {
        JPanel wrapperPanel = new JPanel();
        wrapperPanel.setLayout(new BoxLayout(wrapperPanel, BoxLayout.Y_AXIS));
        wrapperPanel.setBackground(DropTrackerTheme.SURFACE_1);
        wrapperPanel.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH - 20, 400));

        JPanel groupsContainer = new JPanel();
        groupsContainer.setLayout(new BoxLayout(groupsContainer, BoxLayout.Y_AXIS));
        groupsContainer.setBackground(DropTrackerTheme.SURFACE_1);

        // Built empty here; refreshGroupConfigs() populates it from the in-memory list.
        buildGroupConfigPanels(groupsContainer, null);

        groupsScrollPane = new JScrollPane(groupsContainer);
        groupsScrollPane.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
        groupsScrollPane.setVerticalScrollBarPolicy(ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED);
        groupsScrollPane.setBorder(null);
        groupsScrollPane.setBackground(DropTrackerTheme.SURFACE_1);
        groupsScrollPane.getViewport().setBackground(DropTrackerTheme.SURFACE_1);
        groupsScrollPane.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH - 20, 150));
        groupsScrollPane.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 20, 150));

        wrapperPanel.add(groupsScrollPane);
        this.groupsContainerPanel = groupsContainer;
        groupConfigPanel = createMainCollapsiblePanel("Group Configurations", wrapperPanel);

        return groupConfigPanel;
    }

    private JPanel createMainCollapsiblePanel(String title, JPanel content) {
        JPanel panel = new JPanel();
        panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
        panel.setBackground(DropTrackerTheme.SURFACE_1);
        panel.setBorder(DropTrackerTheme.cardBorder(8, 8, 8, 8));

        panel.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, 200));
        panel.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH, 200));
        panel.setAlignmentX(Component.LEFT_ALIGNMENT);

        JPanel headerPanel = new JPanel(new BorderLayout());
        headerPanel.setBackground(DropTrackerTheme.SURFACE_1);

        JLabel titleLabel = new JLabel(title);
        titleLabel.setFont(FontManager.getRunescapeBoldFont());
        titleLabel.setForeground(DropTrackerTheme.TEXT);

        final ImageIcon expandedIcon = PanelElements.getExpandedIcon();
        final ImageIcon collapsedIcon = PanelElements.getCollapsedIcon();
        final JLabel toggleIcon = new JLabel(expandedIcon);

        headerPanel.add(titleLabel, BorderLayout.WEST);
        headerPanel.add(toggleIcon, BorderLayout.EAST);

        final boolean[] isCollapsed = {false};

        headerPanel.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                isCollapsed[0] = !isCollapsed[0];
                toggleIcon.setIcon(isCollapsed[0] ? collapsedIcon : expandedIcon);
                content.setVisible(!isCollapsed[0]);

                if (isCollapsed[0]) {
                    panel.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH, headerPanel.getPreferredSize().height + 20));
                    panel.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, headerPanel.getPreferredSize().height + 20));
                } else {
                    panel.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH, 200));
                    panel.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, 200));
                }

                panel.revalidate();
                panel.repaint();
            }

            @Override
            public void mouseEntered(MouseEvent e) {
                headerPanel.setCursor(new Cursor(Cursor.HAND_CURSOR));
            }

            @Override
            public void mouseExited(MouseEvent e) {
                headerPanel.setCursor(new Cursor(Cursor.DEFAULT_CURSOR));
            }
        });

        JSeparator separator = new JSeparator();
        separator.setBackground(DropTrackerTheme.SURFACE_3);
        separator.setForeground(DropTrackerTheme.SURFACE_3);

        panel.add(headerPanel);
        panel.add(separator);
        panel.add(content);

        return panel;
    }

    private void buildGroupConfigPanels(JPanel parentPanel, List<GroupConfig> groupConfigs) {
        parentPanel.removeAll();

        if (groupConfigs != null && !groupConfigs.isEmpty()) {
            for (GroupConfig groupConfig : groupConfigs) {
                JPanel groupContentPanel = createGroupConfigPanel(groupConfig);
                String groupTitle = groupConfig.getGroupName() + " (ID: " + groupConfig.getGroupId() + ")";
                String groupKey = String.valueOf(groupConfig.getGroupId());
                boolean isCollapsed = groupExpandStates.getOrDefault(groupKey, true);
                JPanel collapsibleGroup = createCompactCollapsiblePanel(groupTitle, groupContentPanel, groupKey, isCollapsed);
                parentPanel.add(collapsibleGroup);
                parentPanel.add(Box.createRigidArea(new Dimension(0, 2)));
            }
        } else {
            JPanel emptyPanel = new JPanel();
            emptyPanel.setLayout(new BoxLayout(emptyPanel, BoxLayout.Y_AXIS));
            emptyPanel.setBackground(DropTrackerTheme.SURFACE_1);
            emptyPanel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));
            emptyPanel.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 40, 30));

            JLabel noConfigsLabel = new JLabel("No group configurations loaded.");
            noConfigsLabel.setFont(FontManager.getRunescapeSmallFont());
            noConfigsLabel.setForeground(DropTrackerTheme.TEXT_MUTED);
            noConfigsLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
            emptyPanel.add(Box.createVerticalGlue());
            emptyPanel.add(noConfigsLabel);
            emptyPanel.add(Box.createVerticalGlue());

            parentPanel.add(emptyPanel);
        }
    }

    private JPanel createCompactCollapsiblePanel(String title, JPanel content, String groupKey, boolean isCollapsed) {
        JPanel panel = new JPanel();
        panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
        panel.setBackground(DropTrackerTheme.SURFACE_1);
        panel.setBorder(new EmptyBorder(2, 5, 2, 5));
        panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 130));

        JPanel headerPanel = new JPanel(new BorderLayout());
        headerPanel.setBackground(DropTrackerTheme.SURFACE_1);
        headerPanel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 18));
        headerPanel.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 40, 18));

        JLabel titleLabel = new JLabel(title);
        titleLabel.setFont(FontManager.getRunescapeSmallFont());
        titleLabel.setForeground(DropTrackerTheme.TEXT);

        final ImageIcon expandedIcon = PanelElements.getExpandedIcon();
        final ImageIcon collapsedIcon = PanelElements.getCollapsedIcon();
        final JLabel toggleIcon = new JLabel(isCollapsed ? collapsedIcon : expandedIcon);

        headerPanel.add(titleLabel, BorderLayout.WEST);
        headerPanel.add(toggleIcon, BorderLayout.EAST);

        content.setVisible(!isCollapsed);

        if (isCollapsed) {
            panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
            panel.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 40, 24));
        }

        final boolean[] isCollapsedRef = {isCollapsed};

        MouseAdapter clickListener = new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                isCollapsedRef[0] = !isCollapsedRef[0];
                toggleIcon.setIcon(isCollapsedRef[0] ? collapsedIcon : expandedIcon);
                content.setVisible(!isCollapsedRef[0]);
                groupExpandStates.put(groupKey, isCollapsedRef[0]);

                if (isCollapsedRef[0]) {
                    panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
                    panel.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 40, 24));
                } else {
                    panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 130));
                    panel.setPreferredSize(null);
                }

                panel.revalidate();
                panel.repaint();
                if (panel.getParent() != null) {
                    panel.getParent().revalidate();
                    panel.getParent().repaint();
                }
            }

            @Override
            public void mouseEntered(MouseEvent e) {
                headerPanel.setCursor(new Cursor(Cursor.HAND_CURSOR));
            }

            @Override
            public void mouseExited(MouseEvent e) {
                headerPanel.setCursor(new Cursor(Cursor.DEFAULT_CURSOR));
            }
        };

        headerPanel.addMouseListener(clickListener);

        JSeparator separator = new JSeparator();
        separator.setBackground(DropTrackerTheme.SURFACE_3);
        separator.setForeground(DropTrackerTheme.SURFACE_3);
        separator.setMaximumSize(new Dimension(Integer.MAX_VALUE, 1));

        panel.add(headerPanel);
        panel.add(separator);
        panel.add(content);

        return panel;
    }

    private JPanel createGroupConfigPanel(GroupConfig groupConfig) {
        JPanel panel = new JPanel();
        panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
        panel.setBackground(DropTrackerTheme.SURFACE_1);
        panel.setBorder(new EmptyBorder(2, 5, 2, 5));

        JPanel headerPanel = new JPanel(new FlowLayout(FlowLayout.LEFT, 2, 0));
        headerPanel.setBackground(DropTrackerTheme.SURFACE_1);
        headerPanel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 18));
        headerPanel.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 70, 18));

        JLabel notificationsLabel = new JLabel("Notifications:");
        notificationsLabel.setFont(FontManager.getRunescapeSmallFont());
        notificationsLabel.setForeground(DropTrackerTheme.TEXT);
        headerPanel.add(notificationsLabel);

        panel.add(headerPanel);
        panel.add(Box.createRigidArea(new Dimension(0, 2)));

        panel.add(createConfigRow("Drops", groupConfig.isSendDrops(), "Min: " + groupConfig.getMinimumDropValue()));
        panel.add(createConfigRow("CAs", groupConfig.isSendCAs(), "Min Tier: " + groupConfig.getMinimumCATier()));
        panel.add(createConfigRow("PBs", groupConfig.isSendPbs(), null));
        panel.add(createConfigRow("CLogs", groupConfig.isSendClogs(), null));
        panel.add(createConfigRow("Pets", groupConfig.isSendPets(), null));
        panel.add(createConfigRow("Quests", groupConfig.isSendQuests(), null));

        String levelText = groupConfig.isSendXP()
            ? "Levels (" + groupConfig.getMinimumLevel() + " min)"
            : "Levels";
        panel.add(createConfigRow(levelText, groupConfig.isSendXP(), null));
        return panel;
    }

    private JPanel createConfigRow(String label, boolean enabled, String details) {
        JPanel row = new JPanel(new FlowLayout(FlowLayout.LEFT, 2, 0));
        row.setBackground(DropTrackerTheme.SURFACE_1);
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 18));
        row.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 70, 18));

        JLabel nameLabel = new JLabel(label + ":");
        nameLabel.setFont(FontManager.getRunescapeSmallFont());
        nameLabel.setForeground(DropTrackerTheme.TEXT_MUTED);
        row.add(nameLabel);

        JLabel statusLabel = new JLabel(enabled ? "On" : "Off");
        statusLabel.setFont(FontManager.getRunescapeSmallFont());
        statusLabel.setForeground(enabled ? DropTrackerTheme.GREEN : DropTrackerTheme.RED);
        row.add(statusLabel);

        if (details != null && !details.isEmpty()) {
            JLabel detailsLabel = new JLabel("(" + details + ")");
            detailsLabel.setFont(FontManager.getRunescapeSmallFont());
            detailsLabel.setForeground(DropTrackerTheme.STONE);
            row.add(detailsLabel);
        }

        return row;
    }

    public void refreshGroupConfigs() {
        if (groupsContainerPanel == null || groupsScrollPane == null) {
            return;
        }

        // Kick a rate-limited async refresh, then render whatever is in memory right now.
        // getGroupConfigs() is a pure in-memory read, so this never blocks the EDT.
        api.refreshGroupConfigsAsync();
        List<GroupConfig> groupConfigs = api.getGroupConfigs();
        SwingUtilities.invokeLater(() -> {
            if (groupsContainerPanel == null || groupsScrollPane == null) {
                return;
            }
            int scrollPosition = groupsScrollPane.getVerticalScrollBar().getValue();

            buildGroupConfigPanels(groupsContainerPanel, groupConfigs);
            groupsContainerPanel.revalidate();
            groupsContainerPanel.repaint();

            SwingUtilities.invokeLater(() -> groupsScrollPane.getVerticalScrollBar().setValue(scrollPosition));

            if (groupConfigPanel != null) {
                groupConfigPanel.revalidate();
                groupConfigPanel.repaint();
            }
        });
    }

    /* ===================== Status + lifecycle ===================== */

    /** Recomputes the header connection state from the last successful API communication. */
    public void updateStatusLabel() {
        if (!config.useApi() || mainPanel == null) {
            return;
        }

        long deltaSeconds = Math.max(0L, Instant.now().getEpochSecond() - api.lastCommunicationTime);
        Duration sinceLastContact = Duration.ofSeconds(deltaSeconds);

        DropTrackerPanel.ConnectionState state;
        if (sinceLastContact.getSeconds() < 60) {
            state = DropTrackerPanel.ConnectionState.CONNECTED;
        } else if (sinceLastContact.getSeconds() < 300) {
            state = DropTrackerPanel.ConnectionState.CONNECTING;
        } else {
            state = DropTrackerPanel.ConnectionState.OFFLINE;
        }
        mainPanel.updateConnectionState(state);
    }

    public void refreshStatistics() {
        if (statsCard != null) {
            rebuildStatsCard(statsCard);
        }
    }

    public void refresh() {
        updateStatusLabel();
        refreshStatistics();
        refreshSubmissions();
        refreshGroupConfigs();
    }

    public void cleanup() {
        if (statusUpdateTimer != null && statusUpdateTimer.isRunning()) {
            statusUpdateTimer.stop();
        }
    }
}

