    private static final String TEAM_SIZES = "(?<teamsize>[^)]+)";

    private static final Pattern ADVENTURE_LOG_TITLE_PATTERN = Pattern.compile("The Exploits of (.+)");
    private static final Pattern ADVENTURE_LOG_PB_PATTERN = Pattern.compile(
        "Fastest (?:kill|run|Room time|Overall time)(?: - \\(Team size: " + TEAM_SIZES + "\\))?:\\s*(?<time>[0-9:]+(?:\\.[0-9]+)?)?"
    );
    private static final Pattern ADVENTURE_LOG_PB_TIME_ONLY_PATTERN = Pattern.compile("^(?<time>[0-9:]+(?:\\.[0-9]+)?)$");

    static final int ADV_LOG_EXPLOITS_TEXT_INDEX = 1;

    private static class BossPB {
        private final String bossName;
        private final String teamSize;
        private final double time;

        public BossPB(String bossName, String teamSize, double time) {
            this.bossName = bossName;
            this.teamSize = teamSize;
            this.time = time;
        }

        public String getBossName() {
            return bossName;
        }

        public String getTeamSize() {
            return teamSize;
        }

        public double getTime() {
            return time;
        }
    }


    @SuppressWarnings("deprecation")
    public void onWidgetLoaded(WidgetLoaded widget)
    {
        switch (widget.getGroupId())
        {
            case InterfaceID.ADVENTURE_LOG:
                advLogLoaded = true;
                break;
            case InterfaceID.KILL_LOG:
                bossLogLoaded = true;
                break;
            case InterfaceID.ACHIEVEMENT_DIARY_SCROLL:
                scrollInterfaceLoaded = true;
                break;
        }
    }

    @SuppressWarnings({ "deprecation", "null" })
    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (client.getLocalPlayer() == null)
        {
            return;
        }

        if (advLogLoaded)
        {
            advLogLoaded = false;

            Widget adventureLog = client.getWidget(ComponentID.ADVENTURE_LOG_CONTAINER);

            if (adventureLog != null && adventureLog.getChild(ADV_LOG_EXPLOITS_TEXT_INDEX) != null)
            {
                Matcher advLogExploitsText = ADVENTURE_LOG_TITLE_PATTERN.matcher(adventureLog.getChild(ADV_LOG_EXPLOITS_TEXT_INDEX).getText());
                if (advLogExploitsText.find())
                {
                    pohOwner = advLogExploitsText.group(1);
                }
            }
        }

        if (bossLogLoaded && (pohOwner == null || pohOwner.equals(client.getLocalPlayer().getName())))
        {
            bossLogLoaded = false;

            Widget title = client.getWidget(ComponentID.KILL_LOG_TITLE);
            Widget bossMonster = client.getWidget(ComponentID.KILL_LOG_MONSTER);
            Widget bossKills = client.getWidget(ComponentID.KILL_LOG_KILLS);

            if (title == null || bossMonster == null || bossKills == null
                || !"Boss Kill Log".equals(title.getText()))
            {
                return;
            }

        }

        // Adventure log - Counters
        if (scrollInterfaceLoaded)
        {
            scrollInterfaceLoaded = false;

            collectAndSendAdventureLogPBs();
        }
    }



    @VisibleForTesting
    static String secondsToTimeString(double seconds)
    {
        int hours = (int) (Math.floor(seconds) / 3600);
        int minutes = (int) (Math.floor(seconds / 60) % 60);
        seconds = seconds % 60;

        String timeString = hours > 0 ? String.format("%d:%02d:", hours, minutes) : String.format("%d:", minutes);

        // If the seconds is an integer, it is ambiguous if the pb is a precise
        // pb or not. So we always show it without the trailing .00.
        return timeString + (Math.floor(seconds) == seconds ? String.format("%02d", (int) seconds) : String.format("%05.2f", seconds));
    }

    // Method to collect all PBs from the adventure log
    @SuppressWarnings({ "null", "deprecation" })
    private void collectAndSendAdventureLogPBs() {
        if (client.getLocalPlayer() == null || client.getLocalPlayer().getName() == null || pohOwner == null) {
            return;
        }
        // Only process if we're in our own POH
        if (!client.getLocalPlayer().getName().equals(pohOwner)) {
            return;
        }

        List<BossPB> personalBests = new ArrayList<>();

        Widget parent = client.getWidget(ComponentID.ACHIEVEMENT_DIARY_SCROLL_TEXT);
        if (parent == null) {
            return;
        }

        // Each line is a separate static child
        Widget[] children = parent.getStaticChildren();
        String[] text = Arrays.stream(children)
            .map(Widget::getText)
            .map(Text::removeTags)
            .toArray(String[]::new);

        for (int i = 0; i < text.length; ++i) {
            String bossHeader = text[i] == null ? "" : text[i].trim();
            if (bossHeader.isEmpty()) {
                continue;
            }

            String boss = longBossName(bossHeader);
            String pendingTeamSize = null;

            for (i = i + 1; i < text.length; ++i) {
                String line = text[i] == null ? "" : text[i].trim();
                if (line.isEmpty()) {
                    break;
                }

                Matcher descriptorMatcher = ADVENTURE_LOG_PB_PATTERN.matcher(line);
                if (descriptorMatcher.find()) {
                    String normalizedTeamSize = normalizeTeamSize(descriptorMatcher.group("teamsize"));
                    String inlineTime = descriptorMatcher.group("time");

                    if (inlineTime != null && !inlineTime.isEmpty()) {
                        final double seconds = timeStringToSeconds(inlineTime);
                        personalBests.add(new BossPB(boss, normalizedTeamSize, seconds));
                        pendingTeamSize = null;
                    } else {
                        pendingTeamSize = normalizedTeamSize;
                    }
                    continue;
                }

                Matcher timeOnlyMatcher = ADVENTURE_LOG_PB_TIME_ONLY_PATTERN.matcher(line);
                if (timeOnlyMatcher.find() && pendingTeamSize != null) {
                    final double seconds = timeStringToSeconds(timeOnlyMatcher.group("time"));
                    personalBests.add(new BossPB(boss, pendingTeamSize, seconds));
                    pendingTeamSize = null;
                }
            }
        }

        if (!personalBests.isEmpty()) {
            sendPersonalBestsWebhook(pohOwner, personalBests);
        }
    }
    private void sendPersonalBestsWebhook(String playerName, List<BossPB> personalBests) {
        if (personalBests.isEmpty()) {
            return;
        }

        CustomWebhookBody customWebhookBody = new CustomWebhookBody();
        customWebhookBody.setContent(playerName + "'s Personal Best Times:");

        // Create a main embed for the PBs
        CustomWebhookBody.Embed pbEmbed = new CustomWebhookBody.Embed();
        pbEmbed.title = playerName + "'s Personal Best Times";

        // Add player info fields
        String accountHash = String.valueOf(client.getAccountHash());
        pbEmbed.addField("type", "adventure_log", true);
        pbEmbed.addField("player", playerName, true);
        pbEmbed.addField("acc_hash", accountHash, true);

        // Group PBs into batches (5 PBs per field)
        int pbsPerField = 5;
        int fieldCount = (int) Math.ceil(personalBests.size() / (double) pbsPerField);

        List<Integer> playerPets = getPetList();

        for (int i = 0; i < fieldCount; i++) {
            StringBuilder fieldContent = new StringBuilder();
            int startIdx = i * pbsPerField;
            int endIdx = Math.min(startIdx + pbsPerField, personalBests.size());

            for (int j = startIdx; j < endIdx; j++) {
                BossPB pb = personalBests.get(j);
                String formattedTime = formatTime(pb.getTime());

                // Format each PB as with "`boss name` - `team_size` : `time`" for easy parsing
                fieldContent.append("`" + pb.getBossName() + "`")
                           .append(" - ")
                           .append("`" + pb.getTeamSize() + "`")
                           .append(" : ")
                           .append("`" + formattedTime + "`");

                // Add a newline between entries (except the last one)
                if (j < endIdx - 1) {
                    fieldContent.append("\n");
                }
            }

            // Add the field with a batch number
            pbEmbed.addField("" + (i + 1), fieldContent.toString(), false);
        }
        pbEmbed.addField("Pets", playerPets.toString(), false);

        customWebhookBody.getEmbeds().add(pbEmbed);

        // Use the main plugin class' sendWebhook method
        submissionManager.sendDataToDropTracker(customWebhookBody, SubmissionType.ADVENTURE_LOG);
    }
    /**
     * Formats a time in seconds to a string in the format mm:ss or h:mm:ss
     */
    private String formatTime(double seconds)
    {
        int hours = (int) (seconds / 3600);
        int minutes = (int) ((seconds % 3600) / 60);
        double secs = seconds % 60;

        if (hours > 0)
        {
            return String.format("%d:%02d:%05.2f", hours, minutes, secs);
        }
        else
        {
            return String.format("%d:%05.2f", minutes, secs);
        }
    }

    private String longBossName(String boss)
    {
        return bossNameRegistry.canonicalName(boss, WordUtils::capitalize);
    }

    private void loadPets()
    {
        assert petsIconIdx == -1;

        // !pets requires off thread pets access, so we just store a copy
        EnumComposition petsEnum = client.getEnum(EnumID.PETS);
        pets = new int[petsEnum.size()];
        for (int i = 0; i < petsEnum.size(); ++i)
        {
            pets[i] = petsEnum.getIntValue(i);
        }

        final IndexedSprite[] modIcons = client.getModIcons();
        assert modIcons != null;

        final IndexedSprite[] newModIcons = Arrays.copyOf(modIcons, modIcons.length + pets.length);
        petsIconIdx = modIcons.length;

        client.setModIcons(newModIcons);

        for (int i = 0; i < pets.length; i++)
        {
            final int petId = pets[i];

            final AsyncBufferedImage abi = itemManager.getImage(petId);
            final int idx = petsIconIdx + i;
            abi.onLoaded(() ->
            {
                final BufferedImage image = ImageUtil.resizeImage(abi, 18, 16);
                final IndexedSprite sprite = ImageUtil.getImageIndexedSprite(image, client);
                client.getModIcons()[idx] = sprite;
            });
        }
    }

    /**
     * Looks up the list of owned pets for the local player
     */
    private List<Pet> getPetListOld()
    {
        String petListJson = configManager.getRSProfileConfiguration("chatcommands", "pets",
                String.class);

        List<Pet> petList;
        try
        {
            // CHECKSTYLE:OFF
            petList = gson.fromJson(petListJson, new TypeToken<List<Pet>>(){}.getType());
            // CHECKSTYLE:ON
        }
        catch (JsonSyntaxException ex)
        {
            return Collections.emptyList();
        }

        return petList != null ? petList : Collections.emptyList();
    }

    private List<Integer> getPetList()
    {
        List<Pet> old = getPetListOld();
        if (!old.isEmpty())
        {
            List<Integer> l = old.stream().map(Pet::getIconID).collect(Collectors.toList());
            return l;
        }

        String petListJson = configManager.getRSProfileConfiguration("chatcommands", "pets2",
                String.class);

        List<Integer> petList;
        try
        {
            // CHECKSTYLE:OFF
            petList = gson.fromJson(petListJson, new TypeToken<List<Integer>>(){}.getType());
            // CHECKSTYLE:ON
        }
        catch (JsonSyntaxException ex)
        {
            return Collections.emptyList();
        }

        return petList != null ? petList : Collections.emptyList();
    }

    @VisibleForTesting
    static double timeStringToSeconds(String timeString)
    {
        String[] s = timeString.split(":");
        if (s.length == 2) // mm:ss
        {
            return Integer.parseInt(s[0]) * 60 + Double.parseDouble(s[1]);
        }
        else if (s.length == 3) // h:mm:ss
        {
            return Integer.parseInt(s[0]) * 60 * 60 + Integer.parseInt(s[1]) * 60 + Double.parseDouble(s[2]);
        }
        return Double.parseDouble(timeString);
    }

    private static String normalizeTeamSize(String rawTeamSize)
    {
        if (rawTeamSize == null)
        {
            return "Solo";
        }

        String teamSize = rawTeamSize.toLowerCase().trim();
        if (teamSize.isEmpty())
        {
            return "Solo";
        }
        if (teamSize.contains("solo"))
        {
            return "Solo";
        }

        // Handles values like "3 player hard mode", "4 players expert mode", "6+ players".
        teamSize = teamSize
            .replace("hard mode", "")
            .replace("entry mode", "")
            .replace("expert mode", "")
            .replace("player", "")
            .replace("players", "")
            .trim();

        if ("1".equals(teamSize))
        {
            return "Solo";
        }

        return teamSize.isEmpty() ? "Solo" : teamSize;
    }
    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        switch (event.getGameState())
        {
            case LOADING:
            case HOPPING:
                pohOwner = null;
                break;
            case STARTING:
                petsIconIdx = -1;
                pets = null;
                break;
            case LOGIN_SCREEN:
                if (petsIconIdx == -1)
                {
                    loadPets();
                }
                break;
            default:
                break;
        }
    }

}

package io.droptracker.events;

import java.lang.ref.WeakReference;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Optional;
import java.util.function.Predicate;

import javax.annotation.Nullable;
import javax.inject.Inject;

import io.droptracker.models.CustomWebhookBody;
import io.droptracker.models.submissions.SubmissionType;
import io.droptracker.util.DeathRegions;
import io.droptracker.util.NpcUtilities;
import io.droptracker.util.RegionNameRegistry;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.ParamID;
import net.runelite.api.Player;
import net.runelite.api.WorldType;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.InteractingChanged;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.game.NPCManager;
import org.apache.commons.lang3.ArrayUtils;
import org.apache.commons.lang3.StringUtils;

/**
 * Tracks local player deaths and submits them to the DropTracker.
 *
 * Invoked manually from DropTrackerPlugin's event subscriptions (handlers in
 * this package are not registered on the RuneLite event bus).
 */
@Slf4j
public class DeathHandler extends BaseEventHandler {

    /** Suppress duplicate submissions if the client fires multiple death events. */
    private static final long DUPLICATE_WINDOW_MS = 5_000;

    private static final String ATTACK_OPTION = "Attack";

    private static final String KILLER_NPC = "npc";
    private static final String KILLER_PLAYER = "player";
    private static final String KILLER_UNKNOWN = "unknown";

    @Inject
    private NPCManager npcManager;

    @Inject
    private RegionNameRegistry regionNames;

    private long lastDeathAtMs = 0;

    /**
     * The last actor the local player interacted with.
     *
     * Reading {@code localPlayer.getInteracting()} on the death tick is not
     * enough on its own: the interaction is frequently already cleared by then,
     * and it answers the wrong question anyway (who we were attacking, not who
     * was attacking us). Tracking the target as it changes gives a candidate
     * that survives the death tick.
     *
     * Weakly held so a despawning actor can still be collected; the referent
     * may be null.
     */
    private WeakReference<Actor> lastTarget = new WeakReference<>(null);

    @Override
    public boolean isEnabled() {
        return config.deathEmbeds();
    }

    public void onInteractingChanged(InteractingChanged event) {
        if (event.getSource() == client.getLocalPlayer()
                && event.getTarget() != null
                && event.getTarget().getCombatLevel() > 0) {
            lastTarget = new WeakReference<>(event.getTarget());
        }
    }

    public void onActorDeath(ActorDeath event) {
        Player localPlayer = client.getLocalPlayer();
        boolean self = localPlayer != null && event.getActor() == localPlayer;

        try {
            if (!self || !isEnabled() || !plugin.isTracking) {
                return;
            }

            long now = System.currentTimeMillis();
            if (now - lastDeathAtMs < DUPLICATE_WINDOW_MS) {
                return;
            }
            lastDeathAtMs = now;

            submitDeath(localPlayer);
        } finally {
            // Clear the tracked target once it is dead — ours or theirs — so a
            // later death cannot be attributed to a corpse.
            if (self || event.getActor() == lastTarget.get()) {
                lastTarget = new WeakReference<>(null);
            }
        }
    }

    private void submitDeath(Player localPlayer) {
        WorldPoint location = currentLocation(localPlayer);
        Actor killer = identifyKiller(localPlayer);
        boolean pk = killer instanceof Player;
        boolean npc = killer instanceof NPC;

        String playerName = getPlayerName();
        if (playerName == null) {
            log.debug("Skipping death submission: no resolvable player name");
            return;
        }
        CustomWebhookBody webhook = createWebhookBody(playerName + " has died!");
        CustomWebhookBody.Embed embed = createEmbed(playerName + " has died!", "death");

        // LinkedHashMap: field order is the order they appear in the embed, and
        // addFields turns a null or blank value into the literal "N/A", so a
        // value we do not have must be left out rather than added empty.
        Map<String, Object> fieldData = new LinkedHashMap<>();

        String killerName = NpcUtilities.canonicalizeSpecialSource(actorName(killer));
        if (killerName != null) {
            fieldData.put("source", killerName);
        }
        fieldData.put("killer_type", pk ? KILLER_PLAYER : npc ? KILLER_NPC : KILLER_UNKNOWN);
        fieldData.put("is_pvp", pk);

        if (npc) {
            NPC killerNpc = (NPC) killer;
            fieldData.put("killer_npc_id", killerNpc.getId());
            if (killerNpc.getCombatLevel() > 0) {
                fieldData.put("killer_combat_level", killerNpc.getCombatLevel());
            }
        } else if (pk && killer.getCombatLevel() > 0) {
            fieldData.put("killer_combat_level", killer.getCombatLevel());
        }

        if (location != null) {
            int regionId = location.getRegionID();
            fieldData.put("region_id", regionId);

            RegionNameRegistry.Area area = regionNames.lookup(regionId);
            if (area != null) {
                fieldData.put("region_name", area.getName());
                if (area.getType() != null) {
                    fieldData.put("region_type", area.getType());
                }
                // "location" is what the notification embed renders and what
                // the custom-embed {location} token has always been documented
                // to be ("Catacombs of Kourend"). Leaving it out when the
                // region is unnamed lets the server fall back to showing the
                // bare region id rather than printing coordinates at people.
                fieldData.put("location", area.getName());
            }

            // The raw point still travels, just no longer as "location".
            fieldData.put("coordinates", location.getX() + "," + location.getY() + "," + location.getPlane());
            fieldData.put("plane", location.getPlane());
            fieldData.put("instanced", isInstance(localPlayer));
            fieldData.put("is_safe_death", DeathRegions.isSafe(client, regionId));
        }

        addFields(embed, fieldData);
        webhook.getEmbeds().add(embed);

        sendData(webhook, SubmissionType.DEATH);
    }

    /**
     * The local player's position, corrected for instances.
     *
     * Inside an instance {@code getWorldLocation()} returns a point in template
     * space, whose region id belongs to whichever chunk the instance was built
     * from — so every raid, Gauntlet, Inferno and Nightmare death used to
     * report a region that had nothing to do with where it happened.
     */
    @Nullable
    private WorldPoint currentLocation(Player localPlayer) {
        if (localPlayer == null) {
            return null;
        }
        WorldView worldView = localPlayer.getWorldView();
        if (worldView != null && worldView.isInstance()) {
            return WorldPoint.fromLocalInstance(client, localPlayer.getLocalLocation(), worldView.getPlane());
        }
        return localPlayer.getWorldLocation();
    }

    private boolean isInstance(Player localPlayer) {
        WorldView worldView = localPlayer != null ? localPlayer.getWorldView() : null;
        return worldView != null && worldView.isInstance();
    }

    @Nullable
    private static String actorName(@Nullable Actor actor) {
        if (actor == null) {
            return null;
        }
        String name = actor.getName();
        return name != null && !name.trim().isEmpty() ? name : null;
    }

    /**
     * @return the actor that most likely killed us, or null when the death
     *         cannot be attributed (poison, falling damage, an attacker that
     *         already despawned).
     */
    @Nullable
    private Actor identifyKiller(Player localPlayer) {
        boolean pvpEnabled = isPvpEnabled();
        Predicate<Actor> interactingWithUs = actor -> isInteractingWith(localPlayer, actor);

        // Fast path: whatever we were last engaged with, if it is still a
        // plausible killer.
        Actor recentTarget = lastTarget.get();
        if (isLikelyKiller(localPlayer, recentTarget, pvpEnabled)) {
            return recentTarget;
        }

        WorldView worldView = client.getTopLevelWorldView();
        if (worldView == null) {
            return null;
        }

        // A player can only have killed us where PvP is possible. Prefer one
        // who is not a friend/clanmate, since those are usually bystanders.
        if (pvpEnabled) {
            Optional<? extends Player> pker = worldView.players().stream()
                    .filter(interactingWithUs)
                    .min(pkComparator(localPlayer));
            if (pker.isPresent()) {
                return pker.get();
            }
        }

        // Otherwise the best-ranked NPC currently attacking us.
        return worldView.npcs().stream()
                .filter(interactingWithUs)
                .filter(npc -> isValidKiller(npc.getTransformedComposition()))
                .min(npcComparator(localPlayer))
                .orElse(null);
    }

    private boolean isPvpEnabled() {
        return client.getVarbitValue(VarbitID.INSIDE_WILDERNESS) > 0
                || client.getWorldType().contains(WorldType.PVP)
                || client.getWorldType().contains(WorldType.DEADMAN);
    }

    /** Whether the actor is alive and targeting the local player. */
    private static boolean isInteractingWith(Player localPlayer, @Nullable Actor actor) {
        return actor != null
                && actor != localPlayer
                && !actor.isDead()
                && actor.getInteracting() == localPlayer;
    }

    /** Whether an NPC is a plausible killer rather than scenery or a pet. */
    private static boolean isValidKiller(@Nullable NPCComposition composition) {
        return composition != null
                && composition.isInteractible()
                && !composition.isFollower()
                && composition.getCombatLevel() > 0;
    }

    private static boolean isLikelyKiller(Player localPlayer, @Nullable Actor actor, boolean pvpEnabled) {
        if (!isInteractingWith(localPlayer, actor)) {
            return false;
        }

        if (actor instanceof Player) {
            Player other = (Player) actor;
            return pvpEnabled && !other.isClanMember() && !other.isFriend() && !other.isFriendsChatMember();
        }

        if (actor instanceof NPC) {
            NPCComposition composition = ((NPC) actor).getTransformedComposition();
            return isValidKiller(composition) && ArrayUtils.contains(composition.getActions(), ATTACK_OPTION);
        }

        return false;
    }

    /**
     * Orders candidate NPCs by how likely each is to be the killer, best first
     * (so {@code Stream#min} picks the winner).
     */
    private Comparator<NPC> npcComparator(Player localPlayer) {
        return Comparator
                .comparing(
                        NPC::getTransformedComposition,
                        Comparator.nullsFirst(
                                Comparator
                                        // named in the hitpoints UI — i.e. something the game
                                        // itself treats as a notable opponent
                                        .comparing((NPCComposition c) -> c.getStringValue(ParamID.NPC_HP_NAME),
                                                Comparator.comparing(StringUtils::isNotEmpty))
                                        .thenComparing(c -> ArrayUtils.contains(c.getActions(), ATTACK_OPTION))
                                        .thenComparingInt(NPCComposition::getCombatLevel)
                                        .thenComparingInt(NPCComposition::getSize)
                                        .thenComparing(NPCComposition::isMinimapVisible)
                                        .thenComparing(c -> npcManager.getHealth(c.getId()),
                                                Comparator.nullsFirst(Comparator.naturalOrder()))))
                .thenComparingInt(npc -> -distanceTo(localPlayer, npc))
                .reversed();
    }

    /**
     * Orders candidate players by how likely each is to be the killer, best
     * first. Friends and clanmates rank last; a similar combat level and
     * proximity rank higher.
     */
    private static Comparator<Player> pkComparator(Player localPlayer) {
        return Comparator
                .comparing(Player::isClanMember)
                .thenComparing(Player::isFriend)
                .thenComparing(Player::isFriendsChatMember)
                .thenComparingInt(p -> Math.abs(localPlayer.getCombatLevel() - p.getCombatLevel()))
                .thenComparingInt(p -> -p.getCombatLevel())
                .thenComparing(p -> p.getOverheadIcon() == null)
                .thenComparing(p -> p.getTeam() == localPlayer.getTeam())
                .thenComparingInt(p -> distanceTo(localPlayer, p));
    }

    private static int distanceTo(Player localPlayer, Actor other) {
        if (localPlayer.getLocalLocation() == null || other.getLocalLocation() == null) {
            return Integer.MAX_VALUE;
        }
        return localPlayer.getLocalLocation().distanceTo(other.getLocalLocation());
    }
}

package io.droptracker.util;

import com.google.gson.TypeAdapter;
import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonWriter;

import java.io.IOException;
import java.time.Duration;
import java.time.format.DateTimeParseException;

/**
 * Serializes and deserializes {@link Duration} instances
 * from their equivalent ISO-8601 string representation.
 * <p>
 * This adapter exists because GSON does not ship with
 * a module for the Java 8 time API.
 *
 * @see <a href="https://github.com/google/gson/issues/1059">GSON Issue</a>
 */
public class DurationAdapter extends TypeAdapter<Duration> {
    @Override
    public void write(JsonWriter out, Duration duration) throws IOException {
        out.value(duration != null ? duration.toString() : null);
    }

    @Override
    public Duration read(JsonReader in) throws IOException {
        if (in.hasNext()) {
            try {
                return Duration.parse(in.nextString());
            } catch (DateTimeParseException ignored) {
            }
        }
        return null;
    }

    public static String formatDuration(Duration duration) {
        if (duration.toDays() > 0) {
			return duration.toDays() + " day ago";
		} else if (duration.toHours() > 0) {
			return duration.toHours() + " hr ago"; 
		} else if (duration.toMinutes() > 0) {
			return duration.toMinutes() + " min ago";
		} else {    
			return "just now";
		}
    }
}

package io.droptracker.util;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import lombok.extern.slf4j.Slf4j;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.Map;
import java.util.Objects;
import java.util.function.UnaryOperator;

/**
 * Data-driven registry mapping adventure-log / chat short boss names to their
 * canonical long names. The mappings live in
 * {@code /io/droptracker/boss_names.json} and were extracted verbatim from the
 * former switch statement in {@code WidgetEventHandler.longBossName}.
 *
 * Dynamic behavior (the {@code " (echo)"} suffix recursion and the
 * unmapped-name fallback) intentionally remains in code rather than data.
 */
@Slf4j
@Singleton
public final class BossNameRegistry {

    private static final String RESOURCE_PATH = "/io/droptracker/boss_names.json";
    private static final String ECHO_SUFFIX = " (echo)";

    private final Map<String, String> mappings;

    @Inject
    public BossNameRegistry(Gson gson) {
        this.mappings = loadMappings(gson);
    }

    private static Map<String, String> loadMappings(Gson gson) {
        try (InputStream is = BossNameRegistry.class.getResourceAsStream(RESOURCE_PATH);
             Reader reader = new BufferedReader(new InputStreamReader(Objects.requireNonNull(is), StandardCharsets.UTF_8))) {
            Map<String, String> mappings = gson.fromJson(reader,
                    new TypeToken<Map<String, String>>() {}.getType());
            return Collections.unmodifiableMap(Objects.requireNonNull(mappings));
        } catch (Exception e) {
            log.error("Failed to load boss name mappings from {}", RESOURCE_PATH, e);
            return Collections.emptyMap();
        }
    }

    /**
     * Resolves a short boss name to its canonical long name.
     * Names ending in {@code " (echo)"} (case-insensitive) are resolved by
     * recursing on the base name and re-appending {@code " (Echo)"}.
     *
     * @param shortName the short name to resolve
     * @return the canonical name, or the input unchanged when unmapped
     */
    public String canonicalName(String shortName) {
        return canonicalName(shortName, UnaryOperator.identity());
    }

    /**
     * Resolves a short boss name to its canonical long name, applying
     * {@code unmappedFallback} to the (possibly echo-stripped, lowercased)
     * name when no mapping exists. This mirrors the exact recursion order of
     * the original {@code longBossName} implementation.
     *
     * @param shortName        the short name to resolve
     * @param unmappedFallback transformation applied to unmapped names
     * @return the canonical name, or the fallback-transformed input when unmapped
     */
    public String canonicalName(String shortName, UnaryOperator<String> unmappedFallback) {
        String lowerBoss = shortName.toLowerCase();
        if (lowerBoss.endsWith(ECHO_SUFFIX)) {
            String actualBoss = lowerBoss.substring(0, lowerBoss.length() - ECHO_SUFFIX.length());
            return canonicalName(actualBoss, unmappedFallback) + " (Echo)";
        }

        String mapped = mappings.get(lowerBoss);
        return mapped != null ? mapped : unmappedFallback.apply(shortName);
    }

    /**
     * @return the number of short-name mappings loaded from the data file
     */
    public int size() {
        return mappings.size();
    }
}

package io.droptracker.util;

import io.droptracker.api.DropTrackerUrls;
import com.google.inject.Inject;

import io.droptracker.DropTrackerConfig;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.CommandExecuted;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.LinkBrowser;

import java.awt.*;


public class ChatMessageUtil {

    @Inject
    private DropTrackerConfig config;

    @Inject
    private ChatMessageManager chatMessageManager;

    @Inject
    private Client client;
    @Inject
    private ClientThread clientThread;

    @Subscribe
    public void onCommandExecuted(CommandExecuted event)
    {
        if (event.getCommand().equals("droptracker"))
        {
            LinkBrowser.browse(DropTrackerUrls.web("wiki", "why-api").toString());
        }
        if (event.getCommand().equals("debugurl"))
        {
            String apiUrlToUse = event.getArguments()[0];
            config.setCustomApiEndpoint(apiUrlToUse);
            sendChatMessage("All outgoing requests will now be sent to " + apiUrlToUse);
        }
    }
    public void warnApiSetting() {
        queueWarning("It is strongly recommended that you enable our API connections in the DropTracker plugin configuration. To learn more, type ::droptracker");
    }
    public void warnClogSetting() {
        queueWarning("Your collection log slots will not be tracked unless you enabled the game setting: Collection log - New addition notification");
    }

    private void queueWarning(String message) {
        Color color = ColorUtil.fromHex("#ff0000");
        String formatted = String.format("[%s] %s: %s",
                ColorUtil.wrapWithColorTag("DropTracker.io", color),
                "Warning",
                ColorUtil.wrapWithColorTag(message, color));
        chatMessageManager.queue(
                QueuedMessage.builder()
                        .type(ChatMessageType.CONSOLE)
                        .runeLiteFormattedMessage(formatted)
                        .build()
        );
    }

    public void sendChatMessage(String messageContent) {
        ChatMessageBuilder messageBuilder = new ChatMessageBuilder();
        messageBuilder.append(ChatColorType.HIGHLIGHT)
                .append("[")
                .append(ChatColorType.NORMAL)
                .append("DropTracker")
                .append(ChatColorType.HIGHLIGHT)
                .append("] ")
                .append(ChatColorType.NORMAL);
        messageBuilder.append(messageContent);
        final String finalMessage = messageBuilder.build();
        chatMessageManager.queue(
                QueuedMessage.builder()
                        .type(ChatMessageType.CONSOLE)
                        .runeLiteFormattedMessage(finalMessage)
                        .build()
        );
    }

    /**
     * Stamped onto a Discord author's name when their line is rendered in the
     * game's clan chat. Two jobs: a Discord user can never be mistaken for an
     * in-game clanmate, AND it is what stops the bridge from looping — the
     * render goes through {@code client.addChatMessage}, which posts a real
     * {@link net.runelite.api.events.ChatMessage}, so our own injected line
     * comes straight back through the plugin's chat subscriber. An in-game
     * display name cannot contain parentheses, so no real clanmate wears it.
     */
    public static final String DISCORD_SENDER_MARKER = "(Discord)";

    /**
     * Whether a CLAN_CHAT sender name is one of our own rendered Discord
     * lines. Substring rather than suffix: the marker is appended at the end
     * today, but the test has to keep holding if the rendered name is ever
     * decorated further, and no real name can contain it either way.
     */
    public static boolean isDiscordBridgeSender(String name) {
        return name != null && name.contains(DISCORD_SENDER_MARKER);
    }

    /**
     * Discord→game bridge line, rendered to look like clan chat (visible only
     * to this client — nothing is sent to the game server). Approach adapted
     * from the TrackScape Connector, Copyright (c) 2023, Bailey Townsend,
     * BSD 2-Clause License (see LICENSE). The sender carries
     * {@link #DISCORD_SENDER_MARKER}; both strings must already be
     * sanitized/capped by the caller.
     */
    public void sendDiscordClanMessage(String sender, String messageContent) {
        // Callers arrive on the OkHttp callback thread (the notification
        // poller), and client.getClanChannel() is only safe on the client
        // thread — hop over for the read; queue() itself is thread-safe.
        clientThread.invokeLater(() -> {
            String clanName = client.getClanChannel() != null
                    ? net.runelite.client.util.Text.removeTags(client.getClanChannel().getName())
                    : "Discord";
            chatMessageManager.queue(
                    QueuedMessage.builder()
                            .type(ChatMessageType.CLAN_CHAT)
                            .name(sender + " " + DISCORD_SENDER_MARKER)
                            .sender(clanName)
                            .value(messageContent)
                            .build()
            );
        });
    }

    /**
     * Event-notification line: prefixed "[Event Name] (Team name):" instead
     * of the generic [DropTracker] tag so lines read as the event talking.
     * Both names must already be sanitized/capped by the caller; teamName is
     * optional (omitted before the first /event_state snapshot lands).
     */
    public void sendEventChatMessage(String eventName, String teamName, String messageContent) {
        sendEventChatMessage(eventName, teamName, null, null, null, messageContent);
    }

    /**
     * Accented event line: an uppercase type tag ("COMPLETE", "LEAD CHANGE",
     * "PROGRESS"...) in a brightened accent, the body in the accent itself,
     * and — when {@code emphasis} occurs in the body — that one substring
     * (usually the item name) lifted back to the bright shade. A null accent
     * reproduces the old uncoloured line exactly.
     *
     * <p>Colours must go through {@link ChatMessageBuilder#append(Color,
     * String)}: the plain {@code append(String)} runs {@code escapeJagex},
     * which would print the tags literally. All strings must already be
     * sanitized/capped by the caller.</p>
     */
    public void sendEventChatMessage(String eventName, String teamName,
                                     String tag, String accentHex,
                                     String emphasis, String messageContent) {
        ChatMessageBuilder messageBuilder = new ChatMessageBuilder();
        messageBuilder.append(ChatColorType.HIGHLIGHT)
                .append("[")
                .append(ChatColorType.NORMAL)
                .append(eventName)
                .append(ChatColorType.HIGHLIGHT)
                .append("] ");
        if (teamName != null && !teamName.isEmpty()) {
            messageBuilder.append("(")
                    .append(ChatColorType.NORMAL)
                    .append(teamName)
                    .append(ChatColorType.HIGHLIGHT)
                    .append("): ");
        }
        Color accent = accentHex != null ? ColorUtil.fromHex(accentHex) : null;
        if (accent == null) {
            if (tag != null && !tag.isEmpty()) {
                messageBuilder.append(ChatColorType.HIGHLIGHT).append(tag).append(" ");
            }
            messageBuilder.append(ChatColorType.NORMAL).append(messageContent);
        } else {
            Color bright = ColorUtil.colorLerp(accent, Color.WHITE, 0.45);
            if (tag != null && !tag.isEmpty()) {
                messageBuilder.append(bright, tag).append(" ");
            }
            appendEmphasized(messageBuilder, messageContent, emphasis, accent, bright);
        }
        chatMessageManager.queue(
                QueuedMessage.builder()
                        .type(ChatMessageType.CONSOLE)
                        .runeLiteFormattedMessage(messageBuilder.build())
                        .build()
        );
    }

    /** Body in {@code accent}, with the first occurrence of {@code emphasis}
     *  (if any) in {@code bright}. Segments are appended side by side, never
     *  nested: RuneScape's {@code </col>} resets to the chat default rather
     *  than to an enclosing tag. */
    private static void appendEmphasized(ChatMessageBuilder builder, String body,
                                         String emphasis, Color accent, Color bright) {
        int at = emphasis != null && !emphasis.isEmpty() ? body.indexOf(emphasis) : -1;
        if (at < 0) {
            builder.append(accent, body);
            return;
        }
        if (at > 0) {
            builder.append(accent, body.substring(0, at));
        }
        builder.append(bright, emphasis);
        String rest = body.substring(at + emphasis.length());
        if (!rest.isEmpty()) {
            builder.append(accent, rest);
        }
    }
}

package io.droptracker.util;

import java.io.File;
import java.io.FileWriter;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.StandardCopyOption;
import java.text.SimpleDateFormat;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.Date;

import io.droptracker.DropTrackerConfig;
import javax.inject.Inject;

import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;
@Slf4j
public class DebugLogger {

    private static final String PLUGIN_DIR_NAME = "droptracker";
    private static final String LOGS_DIR_NAME = "logs";
    private static final String BASE_LOG_FILENAME = "droptracker.log";

    private static volatile DebugLogger activeInstance;

    private final DropTrackerConfig config;
    private final File logsDir;
    private final File currentLogFile;
    private final Object writeLock = new Object();
    private volatile boolean sessionHeaderWritten = false;
    private FileWriter writer;

    @Inject
    public DebugLogger(DropTrackerConfig config) {
        this.config = config;

        File pluginDir = new File(RuneLite.RUNELITE_DIR, PLUGIN_DIR_NAME);
        this.logsDir = new File(pluginDir, LOGS_DIR_NAME);
        if (!logsDir.exists()) {
            logsDir.mkdirs();
        }

        this.currentLogFile = new File(logsDir, BASE_LOG_FILENAME);
        rotateIfExists(currentLogFile);

        try {
            this.writer = new FileWriter(currentLogFile, true);
        } catch (IOException e) {
            // If we cannot open the writer, logging will become a no-op
            this.writer = null;
        }

        activeInstance = this;
    }

    public boolean isEnabled() {
        return config.debugLogging();
    }

    public static void log(String message) {
        DebugLogger instance = activeInstance;
        if (instance == null) {
            return;
        }
        if (!instance.isEnabled()) {
            /* Still forwarding these messages to the default Sl4fj logger;
                since we use the DebugLogger throughout as an alternative in our plugin
            */
            log.debug(message);
            return;
        }
        log.debug("DebugLogger message: " + message);
        instance.ensureSessionHeader();
        instance.writeLine(message);
    }

    private void ensureSessionHeader() {
        if (sessionHeaderWritten) {
            return;
        }
        synchronized (writeLock) {
            if (sessionHeaderWritten) {
                return;
            }
            writeLine("---- Debug logging enabled for this session ----");
            sessionHeaderWritten = true;
        }
    }

    private void writeLine(String message) {
        synchronized (writeLock) {
            if (writer == null) {
                return;
            }
            try {
                String timestamp = DateTimeFormatter.ISO_LOCAL_DATE_TIME.format(LocalDateTime.now());
                writer.write("[" + timestamp + "] " + message + System.lineSeparator());
                writer.flush();
            } catch (IOException e) {
                // Swallow to avoid impacting game thread; debugging only
            }
        }
    }

    private void rotateIfExists(File file) {
        if (!file.exists()) {
            return;
        }

        long lastModified = file.lastModified();
        String ts = new SimpleDateFormat("yyyy-MM-dd_HHmmss").format(new Date(lastModified));
        File target = new File(logsDir, "droptracker-" + ts + ".log");

        if (target.exists()) {
            int idx = 1;
            File candidate;
            do {
                candidate = new File(logsDir, "droptracker-" + ts + "-" + idx + ".log");
                idx++;
            } while (candidate.exists());
            target = candidate;
        }

        try {
            Files.move(file.toPath(), target.toPath(), StandardCopyOption.ATOMIC_MOVE);
        } catch (IOException moveEx) {
            // Fallback to simple numeric roll if atomic move fails
            int idx = 1;
            File candidate;
            do {
                candidate = new File(logsDir, "droptracker-" + idx + ".log");
                idx++;
            } while (candidate.exists());
            // Best-effort rename; ignore result
            //noinspection ResultOfMethodCallIgnored
            file.renameTo(candidate);
        }
    }

    public void close() {
        synchronized (writeLock) {
            if (writer != null) {
                try {
                    writer.flush();
                    writer.close();
                } catch (IOException e) {
                    // Ignore on close
                } finally {
                    writer = null;
                }
            }
            if (activeInstance == this) {
                activeInstance = null;
            }
        }
    }
}

package io.droptracker.util;

import java.util.Collection;
import java.util.Collections;
import java.util.HashSet;
import java.util.Optional;
import java.util.Set;
import java.util.function.Predicate;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import javax.annotation.Nullable;

import net.runelite.api.gameval.NpcID;
import org.apache.commons.lang3.tuple.Pair;
import org.jetbrains.annotations.VisibleForTesting;

import io.droptracker.DropTrackerPlugin;

import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.http.api.loottracker.LootRecordType;

public class NpcUtilities {

    public static final String GAUNTLET_NAME = "Gauntlet", GAUNTLET_BOSS = "Crystalline Hunllef";
    public static final String CG_NAME = "Corrupted Gauntlet", CG_BOSS = "Corrupted Hunllef";

    public static final String TOA = "Tombs of Amascut";
    public static final String TOB = "Theatre of Blood";
    public static final String COX = "Chambers of Xeric";

    public static final Set<String> SPECIAL_NPC_NAMES = Set.of("The Whisperer", "Araxxor", "Branda the Fire Queen",
            "Eldric the Ice King", "Dusk", "Corrupted Hunllef", "Crystalline Hunllef","Maggot King");
    public static final Set<String> LONG_TICK_NPC_NAMES = Set.of("Grotesque Guardians", "Yama");

    /**
     * Sources that announce their loot in chat a tick after the loot event
     * fires. Capturing the next frame there photographs the moment before the
     * drop message exists, so the screenshot cannot corroborate the drop
     * (issue #48). Captures for these sources wait one game tick.
     */
    public static final Set<String> DEFERRED_SCREENSHOT_NPC_NAMES = Set.of(
            "The Nightmare", "Phosani's Nightmare");

    /** Whether a submission from {@code source} must delay its screenshot a tick. */
    public static boolean needsDeferredScreenshot(@Nullable String source) {
        return source != null && DEFERRED_SCREENSHOT_NPC_NAMES.contains(source);
    }

    /* Mad Angel npc ids (Wyrmscraig, released 2026-07-29) — raw literals because
     * RuneLite 1.12.33 (latest release) has no NpcID constant for this NPC yet.
     * Two in-game variants exist, each with two ids: the version fought during
     * Fallen From Grace and the repeatable post-quest encounter. */
    public static final int MAD_ANGEL_QUEST_A = 16309;
    public static final int MAD_ANGEL_QUEST_B = 16315;
    public static final int MAD_ANGEL_POST_QUEST_A = 16305;
    public static final int MAD_ANGEL_POST_QUEST_B = 16314;

    /* Use a list for all special npc names, since Sailing added a number of them */
    public static final Set<Integer> SERVER_LOOT_NPC_IDS = Set.of(
                NpcID.YAMA,
                NpcID.HESPORI,
                NpcID.SAILING_BULL_SHARK_DEAD,
                NpcID.SAILING_HAMMERHEAD_SHARK_DEAD,
                NpcID.SAILING_TIGER_SHARK_DEAD,
                NpcID.SAILING_GREAT_WHITE_SHARK_DEAD,
                NpcID.SAILING_NARWHAL_DEAD,
                NpcID.SAILING_ORCA_DEAD,
                NpcID.SAILING_PYGMY_KRAKEN_DEAD,
                NpcID.SAILING_SPINED_KRAKEN_DEAD,
                NpcID.SAILING_ARMOURED_KRAKEN_DEAD,
                NpcID.SAILING_VAMPYRE_KRAKEN_DEAD,
                NpcID.SAILING_EAGLE_RAY_DEAD,
                NpcID.SAILING_BUTTERFLY_RAY_DEAD,
                NpcID.SAILING_STINGRAY_DEAD,
                NpcID.SAILING_MANTA_RAY_DEAD,
                NpcID.SAILING_OSPREY_DEAD,
                NpcID.SAILING_ALBATROSS_DEAD,
                NpcID.SAILING_FRIGATEBIRD_DEAD,
                NpcID.SAILING_TERN_DEAD,
                NpcID.SAILING_SEA_MOGRE_DEAD,
                NpcID.SAILING_DOLPHIN_DEAD,
                NpcID.SAILING_VEILED_KRAKEN_DEAD,
                NpcID.MAGGOT_KING,
                NpcID.MAGGOT_KING_CORPSE,
                // Mad Angel awards loot server-side, so nothing spawns on the
                // death tile for LootManager to scrape and NpcLootReceived
                // never fires — kills were tracked (166 PBs landed on release
                // day) while every drop was silently discarded by the
                // onServerNpcLoot gate below.
                MAD_ANGEL_QUEST_A,
                MAD_ANGEL_QUEST_B,
                MAD_ANGEL_POST_QUEST_A,
                MAD_ANGEL_POST_QUEST_B
        );

    /**
     * Server-loot npc ids published by the backend at
     * {@code content/server_loot_npc_ids.txt}, layered over the compiled-in
     * {@link #SERVER_LOOT_NPC_IDS} above. This is what stops a newly released
     * boss (Mad Angel, 2026-07-29) needing a plugin release before its drops
     * track at all.
     * <p>
     * Volatile immutable snapshot: written by the executor thread that fetches
     * the list, read by the loot handlers on the client thread.
     */
    private static volatile Set<Integer> remoteServerLootNpcIds = Collections.emptySet();

    /**
     * Install the published server-loot id list. A null/empty argument (fetch
     * failed, file unreachable, garbage body) is ignored rather than applied,
     * so a bad publish or an offline client degrades to the compiled-in list
     * instead of losing loot tracking for every server-loot boss.
     */
    public static void setRemoteServerLootNpcIds(Collection<Integer> ids) {
        if (ids == null || ids.isEmpty()) {
            return;
        }
        remoteServerLootNpcIds = Collections.unmodifiableSet(new HashSet<>(ids));
    }

    /**
     * Whether this npc's loot is awarded server-side, i.e. arrives via
     * {@code ServerNpcLoot} and must not also be submitted from the
     * client-side {@code NpcLootReceived} path. The union of the compiled-in
     * list and the published one — never fewer ids than the build shipped with.
     */
    public static boolean isServerLootNpc(int npcId) {
        return SERVER_LOOT_NPC_IDS.contains(npcId) || remoteServerLootNpcIds.contains(npcId);
    }

    /* Canonical encounter names that a multi-part boss's sub-NPCs are remapped
     * to (see canonicalizeSpecialSource). Loot for these can arrive via more
     * than one RuneLite loot event, so they need cross-handler de-duplication. */
    public static final Set<String> REMAP_TARGET_NAMES = Set.of(
            "Royal Titans", "Grotesque Guardians", "The Corrupted Gauntlet", "The Gauntlet");

    /**
     * Collapse the raw sub-NPC name of a multi-part boss to its canonical
     * encounter name (e.g. "Dusk" -> "Grotesque Guardians"). Names without a
     * remapping are returned unchanged. Centralises the remapping that used to
     * live inline in {@code DropHandler.onLootReceived} so every loot path
     * (NpcLootReceived / ServerNpcLoot / LootReceived) agrees on one name — a
     * prerequisite for reliably de-duplicating the same kill across handlers.
     */
    public static String canonicalizeSpecialSource(String name) {
        if (name == null) {
            return null;
        }
        switch (name) {
            case "Branda the Fire Queen":
            case "Eldric the Ice King":
                return "Royal Titans";
            case "Dusk":
                return "Grotesque Guardians";
            case "Corrupted Hunllef":
                return "The Corrupted Gauntlet";
            case "Crystalline Hunllef":
                return "The Gauntlet";
            default:
                return name;
        }
    }

    /**
     * Whether loot from this (already canonicalised) source can be delivered by
     * more than one RuneLite loot event for a single kill — the bosses in
     * {@link #SPECIAL_NPC_NAMES} (Whisperer/Araxxor/Maggot King and the raw
     * sub-NPC names) plus the {@link #REMAP_TARGET_NAMES} they collapse to.
     * These are the only sources that need duplicate submissions suppressed;
     * ordinary NPCs (which can legitimately be multi-killed in one tick with
     * identical loot) are intentionally excluded.
     */
    public static boolean isMultiPathLootSource(String canonicalName) {
        return canonicalName != null
                && (SPECIAL_NPC_NAMES.contains(canonicalName) || REMAP_TARGET_NAMES.contains(canonicalName));
    }

    public static final Pattern PRIMARY_REGEX = Pattern.compile(
            "Your (?<key>[\\w\\s:'-]+) (?<type>kill|chest|completion|success) count is:? (?<value>[\\d,]+)");
    public static final Pattern SECONDARY_REGEX = Pattern
            .compile("Your (?<type>kill|chest|completed) (?<key>[\\w\\s:]+) count is:? (?<value>[\\d,]+)");

    @SuppressWarnings("null")
    public static String getStandardizedSource(LootReceived event, DropTrackerPlugin plugin) {
        if (isCorruptedGauntlet(event, plugin)) {
            return CG_NAME;
        }
        if (plugin.lastDrop == null) {
            return event.getName();
        } else if (shouldUseChatName(event, plugin) && plugin.lastDrop.getSource() != null) {
            return plugin.lastDrop.getSource(); // distinguish entry/expert/challenge modes
        }
        return event.getName();
    }

    @SuppressWarnings("null")
    private static boolean isCorruptedGauntlet(LootReceived event, DropTrackerPlugin plugin) {
        return event.getType() == LootRecordType.EVENT && plugin.lastDrop != null
                && "The Gauntlet".equals(event.getName())
                && (CG_NAME.equals(plugin.lastDrop.getSource()) || CG_BOSS.equals(plugin.lastDrop.getSource()));
    }

    private static boolean shouldUseChatName(LootReceived event, DropTrackerPlugin plugin) {
        assert plugin.lastDrop != null;
        String lastSource = plugin.lastDrop.getSource();
        Predicate<String> coincides = source -> source.equals(event.getName()) && lastSource.startsWith(source);
        return coincides.test(TOA) || coincides.test(TOB) || coincides.test(COX);
    }

    public static Optional<Pair<String, Integer>> parseBoss(String message, DropTrackerPlugin plugin) {
        Matcher primary = PRIMARY_REGEX.matcher(message);
        Matcher secondary = SECONDARY_REGEX.matcher(message);
        Pair<String, Integer> mostRecentNpcData = null;

        if (primary.find()) {
            String boss = parsePrimaryBoss(primary.group("key"), primary.group("type"));
            String count = primary.group("value");
            if (boss != null) {
                try {
                    int killCount = Integer.parseInt(count.replace(",", ""));
                    mostRecentNpcData = Pair.of(boss, killCount);
                    plugin.ticksSinceNpcDataUpdate = 0;
                    return Optional.of(mostRecentNpcData);
                } catch (NumberFormatException ignored) {
                }
            }
        } else if (secondary.find()) {
            String key = parseSecondary(secondary.group("key"));
            String value = secondary.group("value");
            if (key != null) {
                try {
                    int killCount = Integer.parseInt(value.replace(",", ""));
                    mostRecentNpcData = Pair.of(key, killCount);
                    plugin.ticksSinceNpcDataUpdate = 0;
                    return Optional.of(mostRecentNpcData);
                } catch (NumberFormatException ignored) {
                }
            }
        }
        return Optional.empty();
    }

    @Nullable
    @VisibleForTesting
    static String parsePrimaryBoss(String boss, String type) {
        switch (type.toLowerCase()) {
            case "chest":
                if ("Barrows".equalsIgnoreCase(boss))
                    return boss;
                if ("Lunar".equals(boss))
                    return boss + " " + type;
                return null;

            case "completion":
                if (GAUNTLET_NAME.equalsIgnoreCase(boss))
                    return GAUNTLET_BOSS;
                if (CG_NAME.equalsIgnoreCase(boss))
                    return CG_BOSS;
                return null;

            case "kill":
                return boss;

            case "success":
                return boss;

            default:
                return null;
        }
    }

    @VisibleForTesting
    static String parseSecondary(String boss) {
        if (boss == null || "Wintertodt".equalsIgnoreCase(boss))
            return boss;

        int modeSeparator = boss.lastIndexOf(':');
        String raid = modeSeparator > 0 ? boss.substring(0, modeSeparator) : boss;
        if (raid.equalsIgnoreCase("Theatre of Blood")
                || raid.equalsIgnoreCase("Tombs of Amascut")
                || raid.equalsIgnoreCase("Chambers of Xeric")
                || raid.equalsIgnoreCase("Chambers of Xeric Challenge Mode"))
            return boss;

        return null;
    }

}

package io.droptracker.util;

import net.runelite.client.game.ItemStack;

import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.util.stream.Collectors;

/**
 * Helpers for working with loot bundles ({@link ItemStack} collections).
 * Shared by {@link io.droptracker.events.DropHandler} (embed building and
 * cross-handler dedup) and {@link io.droptracker.service.RaidLootDeduplicator}
 * (raid chest re-loot suppression), so every consumer derives the same
 * signature for the same bundle.
 */
public final class ItemStacks {

    private ItemStacks() {
    }

    @SuppressWarnings("deprecation")
    public static Collection<ItemStack> stack(Collection<ItemStack> items) {
        final List<ItemStack> list = new ArrayList<>();

        for (final ItemStack item : items) {
            int quantity = 0;
            for (final ItemStack i : list) {
                if (i.getId() == item.getId()) {
                    quantity = i.getQuantity();
                    list.remove(i);
                    break;
                }
            }
            if (quantity > 0) {
                list.add(new ItemStack(item.getId(), item.getQuantity() + quantity, item.getLocation()));
            } else {
                list.add(item);
            }
        }

        return list;
    }

    /**
     * Order-independent signature of a loot bundle (consolidated id:qty pairs),
     * used to recognise the same loot arriving via two different loot events.
     */
    public static String signature(Collection<ItemStack> items) {
        return stack(items).stream()
                .map(i -> i.getId() + ":" + i.getQuantity())
                .sorted()
                .collect(Collectors.joining(","));
    }
}

package io.droptracker.util;

import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import org.jetbrains.annotations.VisibleForTesting;

import java.util.Collections;
import java.util.HashSet;
import java.util.Set;

/**
 * Classifies a death location as safe (no items lost) or dangerous.
 *
 * This is policy, deliberately kept out of {@link RegionNameRegistry} so the
 * name data there stays a verbatim, regenerable extract. The region sets and
 * the ordering of the checks mirror Dink's {@code WorldUtils#getDangerLevel},
 * which is the most complete public treatment of this question.
 *
 * Not modelled here (both grant a one-off daily resurrection that makes an
 * otherwise-safe death dangerous, and both need extra varbit reads): the
 * Karamja elite diary in the Fight Caves and the Western Provinces elite diary
 * at Zulrah. Deaths there are reported as safe.
 */
public final class DeathRegions {

    public enum Danger {
        SAFE,
        DANGEROUS
    }

    private DeathRegions() {
    }

    private static final Set<Integer> BARBARIAN_ASSAULT = regions(7508, 7509, 10322);
    private static final Set<Integer> CASTLE_WARS = regions(9520, 9620);
    private static final Set<Integer> CHAMBERS_OF_XERIC = regions(12889, 13136, 13137, 13138, 13139, 13140,
            13141, 13145, 13393, 13394, 13395, 13396, 13397, 13401);
    private static final Set<Integer> CLAN_WARS = regions(12621, 12622, 12623, 13130, 13131, 13133, 13134,
            13135, 13386, 13387, 13390, 13641, 13642, 13643, 13644, 13645, 13646, 13647, 13899, 13900,
            14155, 14156);
    private static final Set<Integer> GAUNTLET = regions(7512, 7768, 12127);
    private static final Set<Integer> LAST_MAN_STANDING = regions(13658, 13659, 13660, 13914, 13915, 13916,
            13918, 13919, 13920, 14174, 14175, 14176, 14430, 14431, 14432);
    private static final Set<Integer> PLAYER_OWNED_HOUSE = regions(7257, 7534, 7535, 7790, 7791, 8046, 8047,
            8302, 8303);
    private static final Set<Integer> SOUL_WARS = regions(8493, 8748, 8749, 9005);
    private static final Set<Integer> TOMBS_OF_AMASCUT = regions(14160, 14162, 14164, 14674, 14676, 15184,
            15186, 15188, 15696, 15698, 15700);
    private static final Set<Integer> THEATRE_OF_BLOOD = regions(12611, 12612, 12613, 12867, 12869, 13122,
            13123, 13125, 13379);

    private static final int CLAN_HALL = 6997;
    private static final int CREATURE_GRAVEYARD = 13462;
    private static final int NIGHTMARE_ZONE = 9033;
    private static final int PEST_CONTROL_LANDER = 10536;
    private static final int TZHAAR_FIGHT_PIT = 9552;

    /* Deliberately absent from the safe sets: the Inferno (9043) and the
     * TzHaar Fight Caves (9551). Both are technically safe, but losing a run
     * there is the whole point of announcing it. */

    private static final int ACCOUNT_TYPE_HARDCORE_IRONMAN = 3;
    private static final int ACCOUNT_TYPE_HARDCORE_GROUP_IRONMAN = 5;

    private static Set<Integer> regions(int... ids) {
        Set<Integer> set = new HashSet<>(ids.length);
        for (int id : ids) {
            set.add(id);
        }
        return Collections.unmodifiableSet(set);
    }

    /**
     * @param client   the game client
     * @param regionId an instance-corrected map region id
     * @return whether items are at risk in this location
     */
    public static Danger classify(Client client, int regionId) {
        // Every PvM death is dangerous on a hardcore account — the status is
        // what is actually lost, so nothing below can downgrade it to safe.
        if (isHardcore(client)) {
            return Danger.DANGEROUS;
        }

        if (isSafeRegion(regionId) || isPestControl(client, regionId)) {
            return Danger.SAFE;
        }

        return Danger.DANGEROUS;
    }

    /**
     * The account-independent half of {@link #classify}: whether this region is
     * somewhere a non-hardcore death costs no items.
     *
     * Split out so the region policy can be tested directly — the rest of the
     * classification needs a live client for the account type and the Pest
     * Control status overlay.
     */
    public static boolean isSafeRegion(int regionId) {
        // Items cannot be carried in or out of these, so a death costs the run
        // rather than the inventory. ToA/ToB/CoX deaths inside a still-running
        // raid are likewise recoverable by the rest of the team.
        if (GAUNTLET.contains(regionId)
                || TOMBS_OF_AMASCUT.contains(regionId)
                || THEATRE_OF_BLOOD.contains(regionId)
                || CHAMBERS_OF_XERIC.contains(regionId)) {
            return true;
        }

        return BARBARIAN_ASSAULT.contains(regionId)
                || CASTLE_WARS.contains(regionId)
                || CLAN_WARS.contains(regionId)
                || LAST_MAN_STANDING.contains(regionId)
                || PLAYER_OWNED_HOUSE.contains(regionId)
                || SOUL_WARS.contains(regionId)
                || regionId == CLAN_HALL
                || regionId == CREATURE_GRAVEYARD
                || regionId == NIGHTMARE_ZONE
                || regionId == PEST_CONTROL_LANDER
                || regionId == TZHAAR_FIGHT_PIT;
    }

    public static boolean isSafe(Client client, int regionId) {
        return classify(client, regionId) == Danger.SAFE;
    }

    private static boolean isHardcore(Client client) {
        // VarbitID.IRONMAN is the account-type varbit: 0 normal, 1 ironman,
        // 2 ultimate, 3 hardcore, 4 group, 5 hardcore group, 6 unranked group.
        int accountType = client.getVarbitValue(VarbitID.IRONMAN);
        return accountType == ACCOUNT_TYPE_HARDCORE_IRONMAN
                || accountType == ACCOUNT_TYPE_HARDCORE_GROUP_IRONMAN;
    }

    /**
     * The Pest Control islands are ordinary-looking regions, so the lander
     * region alone does not cover a death during a game. The status overlay is
     * only built while a game is running, which is exactly the window that
     * matters.
     */
    private static boolean isPestControl(Client client, int regionId) {
        if (regionId == PEST_CONTROL_LANDER) {
            return true;
        }
        Widget widget = client.getWidget(InterfaceID.PestStatusOverlay.PEST_STATUS_PORT2);
        return widget != null && !widget.isHidden();
    }

    /* Region ids referenced by the tests, so a renumbering shows up there
     * rather than silently reclassifying deaths. */
    @VisibleForTesting
    static final int INFERNO = 9043;
    @VisibleForTesting
