package io.droptracker.util;

import io.droptracker.api.DropTrackerUrls;
import lombok.extern.slf4j.Slf4j;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

import javax.annotation.Nullable;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.image.BufferedImage;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ScheduledExecutorService;

/**
 * Tiny async cache for server-hosted icons (team pieces, NPC/skill task icons).
 *
 * <p>Keys are <em>relative paths</em> under {@code /img/}, e.g.
 * {@code "npcdb/2215.png"}, not URLs: the API is not permitted to tell the plugin
 * which host to contact. {@link DropTrackerUrls#image} anchors the path onto a
 * hardcoded base and rejects anything that tries to escape it, redirects are
 * disabled, and bytes go through ImageIO so a non-image body decodes to null and
 * renders nothing.
 */
@Slf4j
@Singleton
public class RemoteImageCache {
    private static final int MAX_ENTRIES = 64;
    private static final int MAX_DIMENSION = 512;

    private final Map<String, BufferedImage> cache =
        Collections.synchronizedMap(new LinkedHashMap<String, BufferedImage>() {
            @Override
            protected boolean removeEldestEntry(Map.Entry<String, BufferedImage> eldest) {
                return size() > MAX_ENTRIES;
            }
        });
    private final Map<String, Boolean> inFlight = new ConcurrentHashMap<>();

    private final OkHttpClient httpClient;
    private final ScheduledExecutorService executor;

    @Inject
    public RemoteImageCache(OkHttpClient httpClient, ScheduledExecutorService executor) {
        // Redirects off: the base is hardcoded, and following one would hand the
        // choice of host back to the server.
        this.httpClient = httpClient.newBuilder()
            .followRedirects(false)
            .followSslRedirects(false)
            .build();
        this.executor = executor;
    }

    /**
     * Cached image for the given {@code /img/}-relative path, or null while it
     * loads (or when the path is absent, malformed, or not an image). Kicks off at
     * most one background fetch per path; {@code onLoaded} runs off-EDT after a
     * successful load so callers can repaint.
     */
    @Nullable
    public BufferedImage get(@Nullable String imagePath, @Nullable Runnable onLoaded) {
        HttpUrl url = DropTrackerUrls.image(imagePath);
        if (url == null) {
            return null;
        }
        final String key = imagePath;
        BufferedImage cached = cache.get(key);
        if (cached != null) {
            return cached;
        }
        if (inFlight.putIfAbsent(key, Boolean.TRUE) == null) {
            CompletableFuture.runAsync(() -> {
                try {
                    BufferedImage image = fetch(url);
                    if (image != null
                            && image.getWidth() <= MAX_DIMENSION
                            && image.getHeight() <= MAX_DIMENSION) {
                        cache.put(key, image);
                        if (onLoaded != null) {
                            onLoaded.run();
                        }
                    }
                } catch (Exception e) {
                    log.debug("icon fetch failed for {}: {}", key, e.getMessage());
                } finally {
                    inFlight.remove(key);
                }
            }, executor);
        }
        return null;
    }

    @Nullable
    private BufferedImage fetch(HttpUrl url) throws Exception {
        Request request = new Request.Builder().url(url).build();
        try (Response response = httpClient.newCall(request).execute()) {
            ResponseBody body = response.body();
            if (!response.isSuccessful() || body == null) {
                return null;
            }
            // A non-image body (HTML error page, redirect target) decodes to null and renders nothing.
            return ImageIO.read(body.byteStream());
        }
    }
}

package io.droptracker.util;

/**
 * Minimal dotted-version comparison for plugin update checks.
 */
public final class VersionUtil {

    private VersionUtil() {
    }

    /**
     * Compares two dotted version strings numerically (e.g. "5.4.0" vs "5.10.2").
     * Missing segments are treated as zero; non-numeric segments compare as zero.
     *
     * @return negative if a &lt; b, 0 if equal, positive if a &gt; b
     */
    public static int compare(String a, String b) {
        String[] as = sanitize(a).split("\\.");
        String[] bs = sanitize(b).split("\\.");
        int length = Math.max(as.length, bs.length);
        for (int i = 0; i < length; i++) {
            int ai = segment(as, i);
            int bi = segment(bs, i);
            if (ai != bi) {
                return Integer.compare(ai, bi);
            }
        }
        return 0;
    }

    public static boolean isOlderThan(String current, String other) {
        return compare(current, other) < 0;
    }

    private static String sanitize(String version) {
        if (version == null) {
            return "0";
        }
        String trimmed = version.trim();
        if (trimmed.startsWith("v") || trimmed.startsWith("V")) {
            trimmed = trimmed.substring(1);
        }
        return trimmed.isEmpty() ? "0" : trimmed;
    }

    private static int segment(String[] parts, int index) {
        if (index >= parts.length) {
            return 0;
        }
        try {
            return Integer.parseInt(parts[index].trim());
        } catch (NumberFormatException e) {
            return 0;
        }
    }
}

package io.droptracker.util;

import javax.annotation.Nullable;

/**
 * Decides which RSN a submission is sent under.
 *
 * <p>Every submission the plugin builds carries a {@code player_name}, and the
 * backend resolves that name against a real account. An unreadable RSN used to
 * be replaced with the literal string {@code "Unknown"} — which is not an inert
 * placeholder. It is a name like any other, it matches a real (but empty) Wise
 * Old Man record, and adopting that record renamed whichever live account the
 * submission resolved to, breaking its identity and silently discarding
 * everything it submitted afterwards. The server no longer trusts that record,
 * but the plugin has no business inventing a name in the first place.
 *
 * <p>So: resolve honestly or not at all. A caller that gets {@code null} skips
 * the submission — an event with no identity has nothing to attach itself to.
 */
public final class PlayerIdentity {

    private PlayerIdentity() {
    }

    /**
     * Resolves the RSN to submit under.
     *
     * <p>The live name is unreadable whenever the local player is gone: at
     * logout and during a world hop (which is where most of these come from —
     * the XP handler snapshots on both), and in the short window after login
     * before the name arrives. The account hash outlives the local player in
     * all three, so the cached name covers them — and it is trusted only when
     * it was stored against the hash logged in right now, so it can never
     * attribute an event to whichever account the player was on previously.
     *
     * @param liveName          name read from the client
     * @param accountHash       account hash of the session being submitted for
     * @param cachedName        last name stored by the plugin at login
     * @param cachedAccountHash account hash {@code cachedName} was stored for
     * @return the RSN, or {@code null} when it cannot be established
     */
    @Nullable
    public static String resolve(@Nullable String liveName, @Nullable String accountHash,
                                 @Nullable String cachedName, @Nullable String cachedAccountHash) {
        if (liveName != null && !liveName.trim().isEmpty()) {
            return liveName;
        }
        if (cachedName == null || cachedName.trim().isEmpty()) {
            return null;
        }
        // The account hash is the only thing that proves the cached name
        // belongs to this session rather than the last one.
        if (!isUsableAccountHash(accountHash) || cachedAccountHash == null
                || !accountHash.trim().equals(cachedAccountHash.trim())) {
            return null;
        }
        return cachedName;
    }

    /**
     * True when an account hash identifies a logged-in account. The client
     * reports -1 when logged out, and the plugin substitutes 0 when there is no
     * client at all; both are strings the backend would otherwise try to match
     * a player row against.
     */
    public static boolean isUsableAccountHash(@Nullable String accountHash) {
        if (accountHash == null) {
            return false;
        }
        String trimmed = accountHash.trim();
        return !trimmed.isEmpty() && !"0".equals(trimmed) && !"-1".equals(trimmed);
    }

    /**
     * True when a submission's {@code player_name} field is unusable. Used as
     * the last line of defence before a payload leaves the client.
     */
    public static boolean isMissingName(@Nullable String playerName) {
        return playerName == null || playerName.trim().isEmpty();
    }
}

package io.droptracker.util;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import lombok.extern.slf4j.Slf4j;

import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;

/**
 * Resolves an OSRS map region id to a human-readable area name
 * ("Theatre of Blood", "Catacombs of Kourend") and a coarse area type.
 *
 * The data in {@code /io/droptracker/region_names.json} was extracted verbatim
 * from RuneLite's {@code DiscordGameEventType} enum (BSD 2-Clause, same licence
 * as this plugin), which maintains this mapping for Discord rich presence. That
 * enum is package-private so it cannot be imported; regenerate the resource by
 * re-parsing the enum constants that carry a {@code DiscordAreaType} and one or
 * more region ids.
 *
 * Region ids are only meaningful when they come from an instance-corrected
 * {@link net.runelite.api.coords.WorldPoint} — inside an instance the raw
 * {@code getWorldLocation()} returns template coordinates that resolve to the
 * wrong area (or none at all). See {@code DeathHandler#currentLocation}.
 */
@Slf4j
@Singleton
public final class RegionNameRegistry {

    private static final String RESOURCE_PATH = "/io/droptracker/region_names.json";

    /** A named area and the coarse bucket RuneLite files it under. */
    public static final class Area {
        private final String name;
        private final String type;

        Area(String name, String type) {
            this.name = name;
            this.type = type;
        }

        /** Human-readable area name, e.g. {@code "Theatre of Blood"}. */
        public String getName() {
            return name;
        }

        /**
         * One of {@code BOSSES}, {@code RAIDS}, {@code DUNGEONS}, {@code CITIES},
         * {@code MINIGAMES}, {@code REGIONS}.
         */
        public String getType() {
            return type;
        }

        @Override
        public String toString() {
            return name;
        }
    }

    /** Deserialization shape of the JSON resource. */
    private static final class AreaEntry {
        String name;
        String type;
        int[] regions;
    }

    private static final class AreaFile {
        List<AreaEntry> areas;
    }

    private final Map<Integer, Area> byRegion;

    @Inject
    public RegionNameRegistry(Gson gson) {
        this.byRegion = load(gson);
    }

    private static Map<Integer, Area> load(Gson gson) {
        try (InputStream is = RegionNameRegistry.class.getResourceAsStream(RESOURCE_PATH);
             Reader reader = new BufferedReader(new InputStreamReader(Objects.requireNonNull(is), StandardCharsets.UTF_8))) {
            AreaFile file = gson.fromJson(reader, new TypeToken<AreaFile>() {}.getType());
            Objects.requireNonNull(file);
            Objects.requireNonNull(file.areas);

            Map<Integer, Area> map = new HashMap<>();
            for (AreaEntry entry : file.areas) {
                if (entry == null || entry.name == null || entry.regions == null) {
                    continue;
                }
                Area area = new Area(entry.name, entry.type);
                for (int region : entry.regions) {
                    map.put(region, area);
                }
            }
            return Collections.unmodifiableMap(map);
        } catch (Exception e) {
            // A missing/corrupt resource must not break death tracking — callers
            // degrade to reporting the bare region id.
            log.error("Failed to load region names from {}", RESOURCE_PATH, e);
            return Collections.emptyMap();
        }
    }

    /**
     * @param regionId an instance-corrected map region id
     * @return the area covering that region, or null when unmapped
     */
    @Nullable
    public Area lookup(int regionId) {
        return byRegion.get(regionId);
    }

    /**
     * @param regionId an instance-corrected map region id
     * @return the human-readable area name, or null when unmapped
     */
    @Nullable
    public String nameOf(int regionId) {
        Area area = byRegion.get(regionId);
        return area != null ? area.getName() : null;
    }

    /**
     * @param regionId an instance-corrected map region id
     * @return the coarse area type, or null when unmapped
     */
    @Nullable
    public String typeOf(int regionId) {
        Area area = byRegion.get(regionId);
        return area != null ? area.getType() : null;
    }

    /** Number of distinct region ids the registry can name. */
    public int size() {
        return byRegion.size();
    }
}

package io.droptracker.util;


import io.droptracker.api.DropTrackerUrls;
import com.google.gson.Gson;
import lombok.extern.slf4j.Slf4j;
import okhttp3.HttpUrl;
import okhttp3.*;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;
import org.jetbrains.annotations.VisibleForTesting;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.IOException;
import java.io.Reader;
import java.util.*;
import java.util.concurrent.CompletableFuture;
import java.util.function.Function;

/**
 * This thread-safe singleton holds a mapping of item names to their item id, using the RuneLite API.
 * <p>
 * Unlike {@link net.runelite.client.game.ItemManager#search(String)}, this mapping supports untradable items.
 *
 * Author: iProdigy ( https://github.com/pajlads/DinkPlugin )
 */

@Slf4j
@Singleton
public class ItemIDSearch {
    private final Map<String, Integer> itemIdByName = Collections.synchronizedMap(new HashMap<>(16384));
    private @Inject OkHttpClient httpClient;
    private @Inject Gson gson;

    /**
     * @param name the exact in-game name of an item
     * @return the id associated with the item name, or null if not found
     */
    @Nullable
    public Integer findItemId(@NotNull String name) {
        return itemIdByName.get(name);
    }

    /**
     * Begins the initialization process for {@link #itemIdByName}
     * by querying item names and noted item ids from the RuneLite API,
     * before passing them to {@link #populate(Map, Set)}
     *
     * @implNote This operation does not block the current thread,
     * by utilizing OkHttp's thread pool and Java's Fork-Join common pool.
     */
    @Inject
    void init() {
        queryNamesById()
                .thenAcceptBothAsync(
                        queryNotedItemIds().exceptionally(e -> {
                            log.error("Failed to read noted items", e);
                            return Collections.emptySet();
                        }),
                        this::populate
                )
                .exceptionally(e -> {
                    log.error("Failed to read item names", e);
                    return null;
                });
    }

    /**
     * Populates {@link #itemIdByName} with the inverted mappings of {@code namesById},
     * while skipping noted items specified in {@code notedIds}.
     *
     * @param namesById a mapping of item id's to the corresponding in-game name
     * @param notedIds  the id's of noted items
     * @implNote When multiple non-noted item id's have the same in-game name, only the earliest id is saved
     */
    @VisibleForTesting
    void populate(@NotNull Map<Integer, String> namesById, @NotNull Set<Integer> notedIds) {
        namesById.forEach((id, name) -> {
            if (!notedIds.contains(id))
                itemIdByName.putIfAbsent(name, id);
        });

        log.debug("Completed initialization of item cache with {} entries", itemIdByName.size());
    }

    /**
     * @return a mapping of item ids to their in-game names, provided by the RuneLite API
     */
    private CompletableFuture<Map<Integer, String>> queryNamesById() {
        // Read JSON as Map<String, String> first
        return queryCache("names.json", Map.class)
                .thenApply(stringMap -> {
                    Map<Integer, String> result = new HashMap<>();
                    for (Object keyObj : stringMap.keySet()) {
                        String keyStr = (String) keyObj;
                        Object valObj = stringMap.get(keyStr);
                        // Defensive: valObj might be String or something else
                        String valueStr = valObj != null ? valObj.toString() : null;
                        result.put(Integer.parseInt(keyStr), valueStr);
                    }
                    return result;
                });

    }

    /**
     * @return a set of id's of noted items, provided by the RuneLite API
     */
    private CompletableFuture<Set<Integer>> queryNotedItemIds() {
        return queryCache("notes.json", Map.class)
                .thenApply(stringMap -> {
                    Set<Integer> keys = new HashSet<>();
                    for (Object keyObj : stringMap.keySet()) {
                        keys.add(Integer.parseInt((String) keyObj));
                    }
                    return keys;
                });

    }

    /**
     * @param fileName the name of the file to query from RuneLite's cache
     * @param type     a type token that indicates how the json response should be parsed
     * @return the transformed cache response, wrapped in a future
     */
    private <T> CompletableFuture<T> queryCache(@NotNull String fileName, @NotNull Class<T> clazz) {
        return readJson(httpClient, gson, DropTrackerUrls.itemCache(fileName), clazz);
    }

    public <T> CompletableFuture<T> readJson(@NotNull OkHttpClient httpClient, @NotNull Gson gson, @NotNull HttpUrl url, @NotNull Class<T> clazz) {
        return readUrl(httpClient, url, reader -> gson.fromJson(reader, clazz));
    }

    public <T> CompletableFuture<T> readUrl(@NotNull OkHttpClient httpClient, @NotNull HttpUrl url, @NotNull Function<Reader, T> transformer) {
        CompletableFuture<T> future = new CompletableFuture<>();
        Request request = new Request.Builder().url(url).build();
        httpClient.newCall(request).enqueue(new Callback() {
            @Override
            public void onFailure(@NotNull Call call, @NotNull IOException e) {
                future.completeExceptionally(e);
            }

            @Override
            public void onResponse(@NotNull Call call, @NotNull Response response) {
                try (Response autoClose = response) {
                    ResponseBody body = response.body();
                    if (body == null) {
                        future.completeExceptionally(new IOException("Empty response body from " + url));
                        return;
                    }
                    try (Reader reader = body.charStream()) {
                        future.complete(transformer.apply(reader));
                    }
                } catch (Exception e) {
                    future.completeExceptionally(e);
                }
            }
        });
        return future;
    }
    public class IntStringEntry {
        public int key;
        public String value;
    }
    public class IntIntEntry {
        public int key;
        public int value;
    }


}

package io.droptracker.util;

import java.text.NumberFormat;
import java.util.Locale;

/**
 * Quantity formatting for event progress values: large targets like
 * 10,000,000 XP must never render as raw digit runs. Panel rows use comma
 * grouping ({@link #commas}); tight spots (HUD progress bar) use GP-style
 * abbreviations ({@link #abbrev}).
 */
public final class ValueFormat {

    private static final NumberFormat COMMAS = NumberFormat.getIntegerInstance(Locale.US);

    private ValueFormat() {
    }

    /** 10000000 → "10,000,000". */
    public static String commas(long value) {
        synchronized (COMMAS) {
            return COMMAS.format(value);
        }
    }

    /** 10000000 → "10M", 1250000 → "1.25M", 813636 → "813.6K", 500 → "500". */
    public static String abbrev(long value) {
        long abs = Math.abs(value);
        if (abs >= 1_000_000_000L) {
            return trim(value / 1_000_000_000.0, 2) + "B";
        }
        if (abs >= 1_000_000L) {
            return trim(value / 1_000_000.0, 2) + "M";
        }
        if (abs >= 10_000L) {
            return trim(value / 1_000.0, 1) + "K";
        }
        return commas(value);
    }

    /**
     * "have / need" for progress displays: abbreviated once values get long
     * enough that comma strings stop fitting, comma-grouped below that.
     */
    public static String progress(long have, long need) {
        if (need >= 100_000L || have >= 100_000L) {
            return abbrev(have) + " / " + abbrev(need);
        }
        return commas(have) + " / " + commas(need);
    }

    private static String trim(double value, int maxDecimals) {
        String out = String.format(Locale.US, "%." + maxDecimals + "f", value);
        while (out.contains(".") && (out.endsWith("0") || out.endsWith("."))) {
            out = out.substring(0, out.length() - 1);
        }
        return out;
    }
}

package io.droptracker.util;


import com.google.gson.Gson;
import com.google.gson.annotations.SerializedName;
import com.google.gson.reflect.TypeToken;
import lombok.AccessLevel;
import lombok.Data;
import lombok.Setter;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemVariationMapping;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.OptionalDouble;
import java.util.stream.Collectors;

@Slf4j
@Singleton
public class Rarity {
    private final Map<String, Collection<Drop>> dropsByNpcName = new HashMap<>(1024);
    private @Inject Gson gson;
    private @Inject ItemManager itemManager;
    public static final double EPSILON = 0.00001;
    private static final int[] FACTORIALS;

    @Inject
    void init() {
        Map<String, List<RawDrop>> raw;
        try (InputStream is = getClass().getResourceAsStream("/npc_drops.json");
             Reader reader = new BufferedReader(new InputStreamReader(Objects.requireNonNull(is)))) {
            raw = gson.fromJson(reader,
                    new TypeToken<Map<String, List<RawDrop>>>() {}.getType());
        } catch (Exception e) {
            log.error("Failed to read monster drop rates", e);
            return;
        }

        raw.forEach((npcName, rawDrops) -> {
            List<Drop> drops = rawDrops.stream()
                    .map(RawDrop::transform)
                    .flatMap(Collection::stream)
                    .collect(Collectors.toList());
            dropsByNpcName.put(npcName, drops);
        });
    }

    public OptionalDouble getRarity(String npcName, int itemId, int quantity) {
        ItemComposition composition = itemId >= 0 ? itemManager.getItemComposition(itemId) : null;
        int canonical = composition != null && composition.getNote() != -1 ? composition.getLinkedNoteId() : itemId;
        String itemName = composition != null ? composition.getMembersName() : "";
        Collection<Integer> variants = new HashSet<>(
                ItemVariationMapping.getVariations(ItemVariationMapping.map(canonical))
        );
        return dropsByNpcName.getOrDefault(npcName, Collections.emptyList())
                .stream()
                .filter(drop -> drop.getMinQuantity() <= quantity && quantity <= drop.getMaxQuantity())
                .filter(drop -> {
                    int id = drop.getItemId();
                    if (id == itemId) return true;
                    return variants.contains(id) && itemName.equals(itemManager.getItemComposition(id).getMembersName());
                })
                .mapToDouble(Drop::getProbability)
                .reduce(Double::sum);
    }

    @Value
    private static class Drop {
        int itemId;
        int minQuantity;
        int maxQuantity;
        double probability;
    }

    @Data
    @Setter(AccessLevel.PRIVATE)
    private static class RawDrop {
        private @SerializedName("i") int itemId;
        private @SerializedName("r") Integer rolls;
        private @SerializedName("d") double denominator;
        private @SerializedName("q") Integer quantity;
        private @SerializedName("m") Integer quantMin;
        private @SerializedName("n") Integer quantMax;

        Collection<Drop> transform() {
            int rounds = rolls != null ? rolls : 1;
            int min = quantMin != null ? quantMin : quantity;
            int max = quantMax != null ? quantMax : quantity;
            double prob = 1 / denominator;

            if (rounds == 1) {
                return List.of(new Drop(itemId, min, max, prob));
            }
            List<Drop> drops = new ArrayList<>(rounds);
            for (int successCount = 1; successCount <= rounds; successCount++) {
                double density = binomialProbability(prob, rounds, successCount);
                drops.add(new Drop(itemId, min * successCount, max * successCount, density));
            }
            return drops;
        }
        public double binomialProbability(double p, int nTrials, int kSuccess) {
            // https://en.wikipedia.org/wiki/Binomial_distribution#Probability_mass_function
            return binomialCoefficient(nTrials, kSuccess) * Math.pow(p, kSuccess) * Math.pow(1 - p, nTrials - kSuccess);
        }
        private int binomialCoefficient(int n, int k) {
            assert n < FACTORIALS.length && k <= n && k >= 0;
            return FACTORIALS[n] / (FACTORIALS[k] * FACTORIALS[n - k]); // https://en.wikipedia.org/wiki/nCk
        }
    }

    static {
        // precompute factorials from 0 to 9 for n-choose-k formula
        int n = 10; // max rolls in npc_drops.json is 9 (for Bloodthirsty Leagues IV tier 5 relic)
        int[] facts = new int[n];
        facts[0] = 1; // 0! = 1
        for (int i = 1; i < n; i++) {
            facts[i] = i * facts[i - 1];
        }
        FACTORIALS = facts;
    }
}

package io.droptracker.api;

import java.util.regex.Pattern;

import javax.annotation.Nullable;

import okhttp3.HttpUrl;

/**
 * Every host this plugin is capable of connecting to, as compile-time constants.
 *
 * <p>The Plugin Hub requires that all URLs a plugin talks to are either hardcoded
 * in the plugin or typed by the user, so that the set of domains can be reviewed
 * exhaustively. The API therefore hands us <em>paths</em> (for example
 * {@code "itemdb/4151.png"}), never URLs, and this class anchors them onto one of
 * the bases below. A server response can influence which file we ask for; it can
 * never influence which host we ask.
 *
 * <p>The only address not listed here is the API base itself, which is resolved by
 * {@link DropTrackerApi#getApiUrl()} — either the {@link #DEFAULT_API} constant or
 * the endpoint the user typed into the hidden {@code customApiEndpoint} setting.
 */
public final class DropTrackerUrls {

	/** Website root: panel links, and the parent of {@link #IMAGES}. */
	public static final HttpUrl WEB = HttpUrl.get("https://www.droptracker.io/");

	/** Everything the plugin renders: item/npc icons, lootboards, submission screenshots. */
	public static final HttpUrl IMAGES = HttpUrl.get("https://www.droptracker.io/img/");

	/** Static published content: the webhook list, its key, and the item-id lists. */
	public static final HttpUrl CONTENT = HttpUrl.get("https://droptracker-io.github.io/content/");

	/** RuneLite's item cache, used to resolve item names to ids. */
	public static final HttpUrl ITEM_CACHE = HttpUrl.get("https://static.runelite.net/cache/item/");

	/** Discord webhook delivery. Submissions are POSTed to {@code base + id + token}. */
	public static final HttpUrl DISCORD_WEBHOOK = HttpUrl.get("https://discord.com/api/webhooks/");

	/** Discord invite links opened in the user's browser from the group panel. */
	public static final HttpUrl DISCORD_INVITE = HttpUrl.get("https://discord.gg/");

	/** API base used unless the user has typed their own endpoint. */
	public static final String DEFAULT_API = "https://api.droptracker.io";

	/**
	 * Characters no server-supplied path may contain: {@code :} (so nothing
	 * resembling a scheme survives), {@code %} (so nothing arrives pre-encoded and
	 * gets decoded twice), {@code ?} and {@code #} (so nothing can append a query or
	 * fragment), {@code \} and control characters.
	 *
	 * <p>Everything else is allowed and percent-encoded on the way out. Real
	 * screenshot paths contain apostrophes and parentheses ({@code Kree'arra},
	 * {@code Dagannoth_Rex_(hard)}), and it is {@code addPathSegment} — which
	 * encodes {@code /} too — that makes the host unreachable from a path, not the
	 * character set.
	 */
	private static final Pattern FORBIDDEN = Pattern.compile("[\\\\%?#:\\p{Cntrl}]");

	private static final int MAX_PATH_LENGTH = 512;
	private static final int MAX_SEGMENT_LENGTH = 128;

	private static final Pattern WEBHOOK_ID = Pattern.compile("[0-9]{5,32}");
	private static final Pattern WEBHOOK_TOKEN = Pattern.compile("[A-Za-z0-9._-]{16,200}");
	private static final Pattern INVITE_CODE = Pattern.compile("[A-Za-z0-9-]{1,64}");

	private DropTrackerUrls() {
	}

	/**
	 * Anchors a server-supplied relative path onto a compile-time base, or returns
	 * null if the path is anything other than a plain relative path.
	 *
	 * <p>Rejects absolute URLs, absolute paths, {@code .} / {@code ..} traversal,
	 * empty segments, and any {@link #FORBIDDEN} character. Callers treat null the
	 * same as "no image", so a rejected path simply renders nothing.
	 */
	@Nullable
	public static HttpUrl underBase(HttpUrl base, @Nullable String relativePath) {
		if (relativePath == null) {
			return null;
		}
		String path = relativePath.trim();
		if (path.isEmpty() || path.length() > MAX_PATH_LENGTH
				|| path.startsWith("/")
				|| FORBIDDEN.matcher(path).find()) {
			return null;
		}
		HttpUrl.Builder builder = base.newBuilder();
		for (String segment : path.split("/")) {
			if (segment.isEmpty() || segment.length() > MAX_SEGMENT_LENGTH
					|| ".".equals(segment) || "..".equals(segment)) {
				return null;
			}
			builder.addPathSegment(segment);
		}
		return builder.build();
	}

	/** {@code https://www.droptracker.io/img/<relativePath>} — item icons, lootboards, screenshots. */
	@Nullable
	public static HttpUrl image(@Nullable String relativePath) {
		return underBase(IMAGES, relativePath);
	}

	/**
	 * A page on the website, for opening in the user's browser.
	 *
	 * <p>Unlike {@link #underBase} this encodes rather than rejects, because some
	 * segments are legitimately free-form (a player name may contain spaces).
	 * {@code addPathSegment} percent-encodes {@code /} as well, so no segment can
	 * add depth or escape the host.
	 */
	public static HttpUrl web(String... segments) {
		HttpUrl.Builder builder = WEB.newBuilder();
		for (String segment : segments) {
			builder.addPathSegment(segment);
		}
		return builder.build();
	}

	/** {@code https://droptracker-io.github.io/content/<fileName>}. */
	@Nullable
	public static HttpUrl content(@Nullable String fileName) {
		return underBase(CONTENT, fileName);
	}

	/** {@code https://static.runelite.net/cache/item/<fileName>}. */
	@Nullable
	public static HttpUrl itemCache(@Nullable String fileName) {
		return underBase(ITEM_CACHE, fileName);
	}

	/**
	 * {@code https://discord.com/api/webhooks/<id>/<token>}. The id and token are
	 * opaque credentials published by the backend; the host is ours to decide.
	 */
	@Nullable
	public static HttpUrl discordWebhook(@Nullable String id, @Nullable String token) {
		if (id == null || token == null
				|| !WEBHOOK_ID.matcher(id).matches()
				|| !WEBHOOK_TOKEN.matcher(token).matches()) {
			return null;
		}
		return DISCORD_WEBHOOK.newBuilder()
			.addPathSegment(id)
			.addPathSegment(token)
			.build();
	}

	/** {@code https://discord.gg/<code>} for a group's public invite. */
	@Nullable
	public static HttpUrl discordInvite(@Nullable String code) {
		if (code == null || !INVITE_CODE.matcher(code.trim()).matches()) {
			return null;
		}
		return DISCORD_INVITE.newBuilder().addPathSegment(code.trim()).build();
	}
}

package io.droptracker.api;

import java.io.IOException;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.regex.Pattern;

import javax.annotation.Nullable;
import javax.inject.Inject;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;

import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;
import io.droptracker.util.ChatMessageUtil;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

import io.droptracker.DropTrackerConfig;
import io.droptracker.DropTrackerPlugin;

/* Helps determine what URL to send submissions to, populates the list on startup, etc. */
@Slf4j
public class UrlManager {

    private final DropTrackerConfig config;


    @Inject
    private DropTrackerPlugin plugin;

    @Inject
    private ClientThread clientThread;

    @Inject
    private ChatMessageUtil chatMessageUtil;

    @Inject
    private ScheduledExecutorService executor;

    @Inject
    private OkHttpClient httpClient;

    @Inject
    private Gson gson;

    private static final Random RANDOM = new Random();

    /** How many times the initial endpoint load has failed; retried with backoff. */
    private final AtomicInteger loadAttempts = new AtomicInteger(0);

    private static final int MAX_LOAD_ATTEMPTS = 5;

    @Inject
    public UrlManager(DropTrackerConfig config, DropTrackerPlugin plugin, ClientThread clientThread, ChatMessageUtil chatMessageUtil) {
        this.config = config;
        this.plugin = plugin;
        this.clientThread = clientThread;
        this.chatMessageUtil = chatMessageUtil;
    }


    private static CompletableFuture<Void> endpointUrlsLoaded = new CompletableFuture<>();

    public static List<WebhookEndpoint> endpoints = new ArrayList<>();

    private static int webhookResetCount = 0;

	public static List<WebhookEndpoint> backupEndpoints = new ArrayList<>();

	public static Boolean usingBackups = false;

	/** Everything after {@code /api/webhooks/} in a published entry, if it is written as a URL. */
	private static final Pattern WEBHOOK_PATH = Pattern.compile(".*?/api/webhooks/", Pattern.DOTALL);

	/**
	 * A Discord webhook as the two opaque credentials it actually is. The host is
	 * never taken from the published list — see {@link #url()}.
	 */
	public static final class WebhookEndpoint {
		private final String id;
		private final String token;

		WebhookEndpoint(String id, String token) {
			this.id = id;
			this.token = token;
		}

		/** Always under the hardcoded {@link DropTrackerUrls#DISCORD_WEBHOOK} base. */
		public HttpUrl url() {
			return DropTrackerUrls.discordWebhook(id, token);
		}
	}

	/**
	 * Turns one decrypted list entry into a webhook credential pair, or null if it
	 * is not one.
	 *
	 * <p>Accepts both the legacy format (a full {@code https://discord.com/api/webhooks/<id>/<token>}
	 * URL) and the current one (a bare {@code <id>/<token>} pair), so the plugin works
	 * against a list published either way. In both cases only the last two path
	 * segments are read — whatever host the entry may claim is discarded, never
	 * parsed, and never connected to.
	 */
	@Nullable
	static WebhookEndpoint parseEndpoint(@Nullable String plaintext) {
		if (plaintext == null) {
			return null;
		}
		String candidate = plaintext.trim();
		// Drop any host/prefix a legacy entry carries, plus any query or fragment.
		candidate = WEBHOOK_PATH.matcher(candidate).replaceFirst("");
		int cut = candidate.indexOf('?');
		if (cut < 0) {
			cut = candidate.indexOf('#');
		}
		if (cut >= 0) {
			candidate = candidate.substring(0, cut);
		}
		String[] parts = candidate.split("/");
		if (parts.length != 2) {
			return null;
		}
		// discordWebhook() is the validator: it returns null unless both parts are
		// well-formed credentials, which is exactly the condition for accepting one.
		if (DropTrackerUrls.discordWebhook(parts[0], parts[1]) == null) {
			return null;
		}
		return new WebhookEndpoint(parts[0], parts[1]);
	}

    /**
	 * Grabs a random webhook endpoint from the preloaded list.
	 * If not loaded yet, throws.
	 */
	public static HttpUrl getRandomEndpoint() throws IllegalStateException {
		// Wait for endpoints to be loaded, but don't block the main thread
		if (!endpointUrlsLoaded.isDone()) {
			throw new IllegalStateException("Endpoints are not yet loaded; cannot submit...");
		}
		if (endpoints.isEmpty()) {
			throw new IllegalStateException("No valid endpoints were loaded - check logs for loading errors");
		}
		return endpoints.get(RANDOM.nextInt(endpoints.size())).url();
	}

    /* Determine whether the given URL is a properly-formatted Discord webhook URL or not */
    public boolean isValidDiscordWebhookUrl(HttpUrl url) {
		if (config.useApi() && (url.host().equals("api.droptracker.io") || !config.customApiEndpoint().equals(""))) {
			return true;
		}
		// Ensure that any webhook URLs returned from the GitHub page are actual Discord webhooks
		// And not external connections of some sort
		if (!"discord.com".equals(url.host()) && !url.host().endsWith(".discord.com")) {
			if(!"discordapp.com".equals(url.host()) && !url.host().endsWith(".discordapp.com")){
				return false;
			}
		}
		List<String> segments = url.pathSegments();
		if (segments.size() >= 4 && "api".equals(segments.get(0)) && "webhooks".equals(segments.get(1))) {
			return true;
		}
		return false;
	}

    /* Fetch a new list of webhook URLs from the GitHub page */
    public void fetchNewList() throws IOException {
		if (UrlManager.webhookResetCount > 10) {
			// At this point we just stop attempting to fetch new webhooks
			// Assuming that something on the backend is broken and they're not replenishing properly
			plugin.isTracking = false;
			// isTracking prevents all event processing
			return;
		}
		// Attempt to obtain a new list
		 if (backupEndpoints.isEmpty()) {
			 LocalDate currentDate = LocalDate.now();

			 // Define formatter for YYYYMMDD pattern
			 DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyyMMdd");

			 // Format the date as YYYYMMDD string
			String dateString = currentDate.format(formatter);
			HttpUrl url = usingBackups
					? DropTrackerUrls.content(dateString + ".json")
					: DropTrackerUrls.content(dateString + "-1.json");

			JsonArray jsonArray = gson.fromJson(httpGetString(url), JsonArray.class);

			for (JsonElement element : jsonArray) {
				try {
					String encrypted = element.getAsString();
					try {
						WebhookEndpoint endpoint = parseEndpoint(FernetDecrypt.decryptWebhook(encrypted));
						if (endpoint != null) {
							backupEndpoints.add(endpoint);
						} else {
							log.error("[DropTracker] Decrypted entry is not a webhook credential; skipping");
						}
					} catch (Exception e) {
						log.error("Decryption failed: {}", e.getMessage());
					}
				} catch (Exception e) {
					log.error("Error processing element: {}", e.getMessage());
				}
			}
			if (!backupEndpoints.isEmpty()) {
				// COPY the freshly fetched list, then clear the backing one.
				// Assigning the reference made both fields the same ArrayList,
				// so the clear() below emptied the list we had just installed:
				// every webhook submission after the first refresh threw
				// IllegalStateException ("no urls") and was silently dropped,
				// and the recovery path could never repopulate because
				// backupEndpoints was permanently the same (empty) object. Ten
				// rounds of that flipped isTracking off entirely.
				endpoints = new ArrayList<>(backupEndpoints);
				backupEndpoints.clear();
				clientThread.invokeLater(() -> {
					chatMessageUtil.sendChatMessage("We are currently having some trouble transmitting your drops to our server...");
					chatMessageUtil.sendChatMessage("Please consider enabling our API in the plugin configuration to continue tracking seamlessly.");
				});

				UrlManager.webhookResetCount++;
				// toggle whether the current set of webhooks is from the backup endpoint or the main one
				// incase we need to grab a new set before the client restarts again.
				usingBackups = !usingBackups;
			}

		}

	}


	/* Load webhook credentials in the background from the GitHub pages site */
	public void loadEndpoints() {
		try {
			if (endpoints.isEmpty()) {

				LocalDate currentDate = LocalDate.now();

				// Define formatter for YYYYMMDD pattern
				DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyyMMdd");

				// Format the date as YYYYMMDD string
			    String dateString = currentDate.format(formatter);
				// Get the encryption key first from github (first line only, matching the prior readLine())
				String keyBody = httpGetString(DropTrackerUrls.content(dateString + "-k.txt"));
				String loadedKey = keyBody.split("\\R", 2)[0].trim();
				if (!loadedKey.isEmpty()) {
					FernetDecrypt.ENCRYPTION_KEY = loadedKey;
				} else {
					// Treat a missing key like any other load failure so the retry
					// logic below runs instead of leaving the future forever pending.
					throw new IOException("Encryption key endpoint returned no content");
				}

				String responseBody = httpGetString(DropTrackerUrls.content(dateString + ".json"));
				JsonArray jsonArray = gson.fromJson(responseBody, JsonArray.class);

				for (JsonElement element : jsonArray) {
					try {
						String encrypted = element.getAsString();
						try {
							// Always load webhook credentials as they're needed for both API disabled
							// users and as a fallback when API is enabled but fails
							WebhookEndpoint endpoint = parseEndpoint(FernetDecrypt.decryptWebhook(encrypted));
							if (endpoint != null) {
								endpoints.add(endpoint);
							} else {
								log.error("Decrypted entry is not a Discord webhook credential; skipping");
							}
						} catch (Exception e) {
							log.error("Decryption failed: {}", e.getMessage());
						}
					} catch (Exception e) {
						log.error("Error processing element: {}", e.getMessage());
					}
				}
			}
			log.debug("Successfully loaded {} webhook endpoints from GitHub", endpoints.size());
			endpointUrlsLoaded.complete(null);
		} catch (Exception e) {
			// A transient network failure at client startup used to permanently
			// disable webhook-mode submissions (the future completed exceptionally
			// and nothing ever retried). Retry with linear backoff instead.
			int attempt = loadAttempts.incrementAndGet();
			if (attempt < MAX_LOAD_ATTEMPTS) {
				long delaySeconds = 30L * attempt;
				log.warn("Failed to load webhook endpoints from GitHub (attempt {}/{}); retrying in {}s",
					attempt, MAX_LOAD_ATTEMPTS, delaySeconds, e);
				executor.schedule(this::loadEndpoints, delaySeconds, TimeUnit.SECONDS);
			} else {
				log.error("Failed to load webhook endpoints from GitHub after {} attempts; giving up", attempt, e);
				endpointUrlsLoaded.completeExceptionally(e);
			}
		}
	}

	/** Blocking GET returning the response body as a String, via the injected shared OkHttpClient. */
	private String httpGetString(@Nullable HttpUrl url) throws IOException {
		if (url == null) {
			throw new IOException("Refusing to fetch a rejected content URL");
		}
		Request request = new Request.Builder().url(url).build();
		try (Response response = httpClient.newCall(request).execute()) {
			if (!response.isSuccessful()) {
				throw new IOException("Request to " + url + " failed: HTTP " + response.code());
			}
			ResponseBody body = response.body();
			if (body == null) {
				throw new IOException("Empty response body from " + url);
			}
			return body.string();
		}
	}
}

package io.droptracker.api;

import javax.crypto.Cipher;
import javax.crypto.Mac;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.Base64;

import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

@Slf4j
@Singleton
public class FernetDecrypt {
    public static String ENCRYPTION_KEY = "";

    @Inject
    public FernetDecrypt() {
    }

    public static String decryptWebhook(String webhookHash) throws Exception {
        try {
            // First decode - get the Fernet token
            String fernetToken = new String(Base64.getUrlDecoder().decode(webhookHash), StandardCharsets.UTF_8);

            // Second decode - get the encrypted data
            byte[] token = Base64.getUrlDecoder().decode(fernetToken);

            // Decode the key
            byte[] keyBytes = Base64.getUrlDecoder().decode(ENCRYPTION_KEY);
            byte[] signingKey = Arrays.copyOfRange(keyBytes, 0, 16);
            byte[] encryptionKey = Arrays.copyOfRange(keyBytes, 16, 32);

            // Extract components according to Fernet spec:
            // Version (1 byte) + Timestamp (8 bytes) + IV (16 bytes) + Ciphertext + HMAC (32 bytes)
            if (token.length < 57) { // Minimum size: 1+8+16+0+32
                throw new IllegalArgumentException("Token too short: " + token.length);
            }

            byte version = token[0];

            // Skip timestamp (bytes 1-8) - not needed for decryption

            // Extract IV (bytes 9-24)  
            byte[] iv = Arrays.copyOfRange(token, 9, 25);

            // Get the HMAC (last 32 bytes)
            byte[] hmac = Arrays.copyOfRange(token, token.length - 32, token.length);
            byte[] message = Arrays.copyOfRange(token, 0, token.length - 32);

            // Verify HMAC
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(signingKey, "HmacSHA256"));
            byte[] calculatedHmac = mac.doFinal(message);

            if (!Arrays.equals(hmac, calculatedHmac)) {
                throw new SecurityException("Invalid HMAC");
            }

            // Get ciphertext (everything between IV and HMAC)
            // Start at byte 25 (after version + timestamp + IV)
            byte[] ciphertext = Arrays.copyOfRange(token, 25, token.length - 32);
            // Decrypt
            Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
            cipher.init(Cipher.DECRYPT_MODE, 
                       new SecretKeySpec(encryptionKey, "AES"),
                       new IvParameterSpec(iv));

            byte[] decryptedBytes = cipher.doFinal(ciphertext);
            String result = new String(decryptedBytes, StandardCharsets.UTF_8);

            // Post-process the result to fix common issues
            result = postProcessDecrypted(result);

            return result;
        } catch (Exception e) {
            log.error("Decryption failed for webhook hash: {}", webhookHash.substring(0, Math.min(20, webhookHash.length())) + "...", e);
            throw e;
        }
    }

    /**
     * Strips the leading non-printable bytes that occasionally survive decryption.
     *
     * <p>This used to also synthesise {@code "https://discord.com" + path} when the
     * plaintext looked like a webhook. It no longer does: the plaintext is a
     * credential, not an address, and the host is decided by
     * {@link DropTrackerUrls#DISCORD_WEBHOOK}. See
     * {@link UrlManager#parseEndpoint(String)}.
     */
    private static String postProcessDecrypted(String decrypted) {
        if (decrypted == null || decrypted.isEmpty()) {
            return decrypted;
        }
        return decrypted.replaceAll("^[\\p{Cntrl}\\p{So}\\p{Cn}]+", "");
    }
}

