	@Override
	protected void startUp() {
		api.setOnGroupConfigsLoadedCallback(() -> submissionManager.onGroupConfigsLoaded());
		if(config.showSidePanel()) {
			createSidePanel();
		}
		// Preload webhook URLs asynchronously
		executor.submit(() -> urlManager.loadEndpoints());
		// Load untradeable item IDs on startup for screenshotting purposes
		executor.submit(() -> loadUntradeables());

		// Server-controlled reference data. Fetched in the background; nothing
		// blocks on it, and consumers fall back to built-in defaults until it
		// lands (or if it never does).
		manifestService.startUp();

		// Scheduling only; nothing is sent until the manifest has loaded and the
		// player is logged in, and nothing at all if the user has not opted in.
		stateSyncScheduler.startUp();
		collectionLogScraper.startUp();

		// In-game event notifications + HUD: the overlays render nothing on
		// their own; the service's poll loop idles until the server reports a
		// live event (active_event in the group configs).
		overlayManager.add(eventToastOverlay);
		overlayManager.add(eventHudOverlay);
		eventNotificationService.start();

		// Seed the clan-channel binding for the Discord chat bridge: enabling
		// the plugin while already logged in and sitting in a clan fires no
		// ClanChannelChanged, so without this the inbound direction (and the
		// ?clan= presence heartbeat) stays dead until the next relog.
		clientThread.invokeLater(() -> clanRelayService.updateClanChannel(client.getClanChannel()));

		DebugLogger.log("[DropTrackerPlugin][startup] plugin started; apiEnabled=" + config.useApi()
			+ ", sidePanelEnabled=" + config.showSidePanel()
			+ (config.customApiEndpoint().equals("") ? ", customApiEndpoint=default" : ", customApiEndpoint=" + config.customApiEndpoint()));
		DebugLogger.log("[DropTrackerPlugin][startup] pluginVersion=" + pluginVersion);
	}

	private void loadUntradeables() {
		this.valuedItemIds = api.getValuedUntradeables();
		this.untradeableItemIds = api.getNotableUntradeables();
		// Published server-loot npc ids. Must be loaded before the first kill of
		// the session, not lazily on first drop like the item lists: this list
		// gates whether a drop is submitted at all, so a late load would lose
		// the very drops it exists to capture.
		NpcUtilities.setRemoteServerLootNpcIds(api.getServerLootNpcIds());
	}


	private void createSidePanel() {

		panel = injector.getInstance(DropTrackerPanel.class);
		panel.init();

		// Trigger initial UI refreshes so the panel is populated immediately
		SwingUtilities.invokeLater(() -> {
			if (panel != null) {
				panel.updateSentSubmissions();
				panel.updateHomePlayerButton();
				panel.updatePlayerPanel();
			}
		});

		submissionManager.setUpdateCallback(() -> {
			SwingUtilities.invokeLater(() -> {
				if (panel != null) {
					panel.updateSentSubmissions();
				}
			});
		});
		submissionManager.setUpdatesEnabled(true);

		navButton = NavigationButton.builder()
				.tooltip("DropTracker")
				.icon(PANEL_ICON)
				.priority(1)
				.panel(panel)
				.build();

		clientToolbar.addNavigation(navButton);
	}


	public void updatePanelOnLogin(String chatMessage) {
		if (chatMessage.contains("Welcome to Old School RuneScape.")) {
			// Instead of updating immediately, set a flag to update when player is available
			needsPanelUpdateOnLogin = true;
		}
	}


	/** Outbound payload only — embedded in webhook bodies for Discord to render. */
	public String itemImageUrl(int itemId) {
		return DropTrackerUrls.itemCache("icon/" + itemId + ".png").toString();
	}

	@Override
	protected void shutDown() {
		gameState.lazySet(null);

		collectionLogScraper.shutDown();
		stateSyncScheduler.shutDown();
		stateSyncService.reset();
		playerModelService.reset();
		manifestService.shutDown();
		eventNotificationService.stop();
		overlayManager.remove(eventToastOverlay);
		overlayManager.remove(eventHudOverlay);

		if (navButton != null) {
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
		if (panel != null) {
			panel.deinit();
			panel = null;
		}
		// Disable updates while panel is not present
		submissionManager.setUpdatesEnabled(false);
		if (debugLogger != null) {
			debugLogger.close();
		}
		this.resetAll();	
	}

