	@Subscribe(priority=1)
	public void onLootReceived(LootReceived lootReceived) {
		// A raid reward chest fires LootReceived once when opened in the loot
		// room and again if the unclaimed loot is taken from the collection
		// chest at the bank. Suppress the repeat BEFORE the fan-out: it must
		// reach neither DropHandler (duplicate drop submission) nor KCService
		// (phantom kill count increment).
		if (raidLootDeduplicator.isDuplicateRaidLoot(lootReceived)) {
			return;
		}
		dropHandler.onLootReceived(lootReceived);
		kcService.onLoot(lootReceived);
	}

	@Subscribe(priority = 1)
	public void onChatMessage(ChatMessage message) {
		if (!isTracking) {
			return;
		}
		String chatMessage = submissionManager.sanitize(message.getMessage());
		switch (message.getType()) {
			case WELCOME:
				if (!statsLoaded) {
					updatePanelOnLogin(chatMessage);
				}
				/* Welcome should only be called a single time on each login, 
					so we can call this regardless of whether statsLoaded is true,
					to load/refresh configurations respective to the current player logged in
				*/
				if (config.useApi()) {
					try {
						api.loadGroupConfigs(getLocalPlayerName());
						// Refresh the API panel to show updated group configs
						// Since loading is async, we need to delay the refresh
						if (panel != null) {
							// Initial refresh to show loading state
							SwingUtilities.invokeLater(() -> {
								panel.updateSentSubmissions();
							});

							// Schedule a panel submission update on the executor instead of directly waiting on the thread

							executor.schedule(() -> { panel.updateSentSubmissions(); }, 2, TimeUnit.SECONDS); // Wait 2 seconds for async load

						}
					} catch (IOException e) {
						log.debug("Couldn't refresh api Panel");
					}
				}
				break;
			case GAMEMESSAGE:
				if(pbHandler.isEnabled()){
					pbHandler.onGameMessage(chatMessage);
				}
				if(caHandler.isEnabled()){
					caHandler.onGameMessage(chatMessage);
				}
				if(clogHandler.isEnabled()) {
					clogHandler.onChatMessage(chatMessage);
				}
				if(petHandler.isEnabled()) {
					petHandler.onGameMessage(chatMessage);
				}
				if(diaryHandler.isEnabled()) {
					diaryHandler.onGameMessage(chatMessage);
				}
				if(trawlingHandler.isEnabled()) {
					trawlingHandler.onGameMessage(chatMessage);
				}
				break;
			case SPAM:
				// Trawling catch messages arrive as SPAM when game filtering is on
				if(trawlingHandler.isEnabled()) {
					trawlingHandler.onGameMessage(chatMessage);
				}
				break;
			case FRIENDSCHATNOTIFICATION:
				pbHandler.onFriendsChatNotification(chatMessage);
				break;
			case CLAN_MESSAGE:
			case CLAN_GIM_MESSAGE:
                petHandler.onClanChatNotification(chatMessage);
                // Clan-broadcast relay (group feature): CLAN_MESSAGE only —
                // GIM broadcasts are a different channel and stay local.
                if (message.getType() == ChatMessageType.CLAN_MESSAGE) {
                    clanRelayService.onClanBroadcast(chatMessage);
                }
                break;
			case CLAN_CHAT:
				// Player lines feed only the Discord chat bridge (opt-in);
				// nothing else in the plugin reads clanmates' chatter.
				clanRelayService.onClanChat(message.getName(), chatMessage);
				break;
			default:
				break;
		}
		kcService.onGameMessage(chatMessage);
	}

	@Subscribe
	public void onClanChannelChanged(ClanChannelChanged event) {
		// Keep the relay's clan binding current even while chat is quiet —
		// presence heartbeats and relayed lines both attach this name.
		clanRelayService.updateClanChannel(client.getClanChannel());
	}

	@Subscribe
	public void onGameTick(GameTick event) {
		// Keep the raid roster warm even while tracking is paused so that
		// re-enabling mid-raid still produces complete participant lists.
		nearbyPlayerTracker.onGameTick();
		// Character model export: cheap no-op unless the outfit changed and the
		// player has been standing still.
		playerModelService.onTick();
		// Screenshots deferred a tick so late-announcing bosses are captured
		// with their drop message on screen; drained before the tracking check
		// so a mid-flight toggle can't strand one (see SubmissionManager).
		submissionManager.onGameTick();

		if (!isTracking) {
			return;
		}

		// Check if we need to update panel on login and player is now available
		if (needsPanelUpdateOnLogin && client.getLocalPlayer() != null && client.getLocalPlayer().getName() != null) {
			needsPanelUpdateOnLogin = false; // Clear the flag

			// Use SwingUtilities to ensure UI updates happen on EDT
			String playerName = client.getLocalPlayer().getName();
			if (config.lastAccountName() != null && !config.lastAccountName().equals(playerName)) {
				/* In the case that the player has changed from the last time we stored their name/hash, we need to call the reset method on KCService... */
				kcService.reset();
			}
			config.setLastAccountName(playerName);
			config.setLastAccountHash(String.valueOf(client.getAccountHash()));
			// Load persisted submissions for this account
			submissionManager.loadSubmissions(String.valueOf(client.getAccountHash()));

			// Show login warnings once, now that varbits are guaranteed to be loaded
			if (!loginWarningsShown) {
				loginWarningsShown = true;
				if (config.clogEmbeds() && client.getVarbitValue(VarbitID.OPTION_COLLECTION_NEW_ITEM) == 0) {
					chatMessageUtil.warnClogSetting();
				}
				if (!config.useApi() && config.customApiEndpoint().equalsIgnoreCase("")) {
					chatMessageUtil.warnApiSetting();
				}
				// The update check talks to our API, so it only runs once the user
				// has enabled the integration (or pointed us at their own endpoint).
				if (config.useApi() || !config.customApiEndpoint().equalsIgnoreCase("")) {
					executor.submit(this::checkForPluginUpdates);
				}
			}

			SwingUtilities.invokeLater(() -> {
				try {
					if (panel != null) {
						panel.updatePlayerPanel();

						// Also update the home player button since config might now have player name
						panel.updateHomePlayerButton();
						statsLoaded = true;
					}
				} catch (Exception e) {
					log.debug("Couldn't Load Side Panel UI");
					statsLoaded = true;
				}
			});
		}

		/* Call individual event handlers */
		pbHandler.onTick();
		widgetEventHandler.onGameTick(event);
		petHandler.onTick();

		if (config.trackExperience()) {
			experienceHandler.onTick();
		}
	}

