	@Subscribe
	public void onGameStateChanged(GameStateChanged gameStateChanged) {
		GameState newState = gameStateChanged.getGameState();

		if (newState == GameState.LOADING) {
			return;
		}

		GameState previousState = gameState.getAndSet(newState);
		if (previousState == newState) {
			return;
		}

		// Clear per-session handler state so a partially-coalesced PB, pet or
		// collection-log popup from before a logout/hop can't fire stale
		// notifications after the player comes back.
		if (newState == GameState.LOGIN_SCREEN || newState == GameState.HOPPING) {
			pbHandler.reset();
			petHandler.reset();
			clogHandler.reset();
		}

		justLoggedIn.set(newState == GameState.LOGGED_IN);

		if (previousState == GameState.HOPPING) {
			return;
		}

		if (justLoggedIn.get()) {
			return;
		}

		if (!isTracking || !config.trackExperience()) {
			return;
		}
		experienceHandler.onGameStateChanged(gameStateChanged);
	}

	public String getLocalPlayerName() {
		if (client.getLocalPlayer() != null) {
			return client.getLocalPlayer().getName();
		} else {
			return "";
		}
	}

	/**
	 * Best-effort update check against GET /plugin_version (runs on the executor).
	 * Below the server's minimum version: warn every login. Behind the latest
	 * version: prompt once per new version (tracked via lastVersionNotified).
	 */
	private void checkForPluginUpdates() {
		DropTrackerApi.VersionInfo info = api.fetchVersionInfo();
		if (info == null) {
			return;
		}

		if (info.minimumVersion != null && VersionUtil.isOlderThan(pluginVersion, info.minimumVersion)) {
			chatMessageUtil.sendChatMessage("Your DropTracker plugin (v" + pluginVersion
				+ ") is older than the minimum supported version (v" + info.minimumVersion
				+ ") — submissions may be rejected. Please update via the Plugin Hub.");
			if (info.message != null && !info.message.isEmpty()) {
				chatMessageUtil.sendChatMessage(info.message);
			}
			return;
		}

		if (info.latestVersion != null && VersionUtil.isOlderThan(pluginVersion, info.latestVersion)
				&& !info.latestVersion.equals(config.lastVersionNotified())) {
			config.setLastVersionNotified(info.latestVersion);
			chatMessageUtil.sendChatMessage("A new DropTracker version is available (v" + info.latestVersion
				+ ", you have v" + pluginVersion + "). Update via the Plugin Hub for the latest features and fixes.");
			if (info.message != null && !info.message.isEmpty()) {
				chatMessageUtil.sendChatMessage(info.message);
			}
		}
	}

}

package io.droptracker.models;

import net.runelite.api.Client;

/**
 * The twelve achievement diary areas and how to read a player's progress.
 *
 * <p>Adapted from RuneProfile (BSD 2-Clause,
 * github.com/ReinhardtR/runeprofile-plugin), which in turn reads the counts the
 * way the game itself does.
 *
 * <p>There is no client API for diary progress, so this calls the game's own
 * {@code [proc,diary_completion_info]} script (2200) and reads the results off
 * the int stack. Doing it this way means we get whatever the game considers
 * complete, including task counts that change with a game update, rather than
 * maintaining a per-task varbit table that would silently rot.
 *
 * @see <a href="https://github.com/RuneStar/cs2-scripts/blob/master/scripts/%5Bproc%2Cdiary_completion_info%5D.cs2">the script</a>
 */
public enum AchievementDiaryArea {
	KARAMJA(0),
	ARDOUGNE(1),
	FALADOR(2),
	FREMENNIK(3),
	KANDARIN(4),
	DESERT(5),
	LUMBRIDGE(6),
	MORYTANIA(7),
	VARROCK(8),
	WILDERNESS(9),
	WESTERN_PROVINCES(10),
	KOUREND(11);

	private static final int DIARY_COMPLETION_INFO_SCRIPT = 2200;

	/** The script returns a triple per tier; the completed count is the first. */
	private static final int VALUES_PER_TIER = 3;
	private static final int TIER_COUNT = 4;

	private final int id;

	AchievementDiaryArea(int id) {
		this.id = id;
	}

	public int getId() {
		return id;
	}

	/**
	 * Completed task counts for this area, indexed by tier
	 * (0 easy, 1 medium, 2 hard, 3 elite).
	 *
	 * <p>Must be called on the client thread. Returns an all-zero array if the
	 * script returns less than expected, which happens when it is called before
	 * the player is fully logged in — a zero is indistinguishable from real
	 * "nothing completed", so callers should only sync when logged in.
	 */
	public int[] getTiersCompletedCount(Client client) {
		int[] completed = new int[TIER_COUNT];

		client.runScript(DIARY_COMPLETION_INFO_SCRIPT, id);
		int[] stack = client.getIntStack();
		if (stack == null || stack.length < TIER_COUNT * VALUES_PER_TIER) {
			return completed;
		}

		for (int tier = 0; tier < TIER_COUNT; tier++) {
			completed[tier] = stack[tier * VALUES_PER_TIER];
		}
		return completed;
	}
}

