@Data
public class CustomWebhookBody
{
	private String content;
	private List<Embed> embeds = new ArrayList<>();
	// Outbound payload only — Discord renders these, the plugin never fetches them.
	private static Author DropTracker = new Author(DropTrackerUrls.WEB.toString(),
			"DropTracker",
			DropTrackerUrls.image("droptracker-small.gif").toString());

	@Data
	public static class Embed
	{
		public String title = "";
		UrlEmbed image = null;
		final Author author = DropTracker;
		final List<Field> fields = new ArrayList<>();
		public void addField(String name, String value, boolean inline) {
			this.fields.add(new Field(name, value, inline));
		}
		public void setImage(String imageUrl) {
			this.image = new UrlEmbed(imageUrl);
		}
	}

	@Data
	public static class UrlEmbed
	{
		final String url;
	}
	@Data
	public static class Author
	{
		final String url;
		final String name;
		final String icon_url;
	}
	@Data
	public static class Field
	{
		final String name;
		final String value;
		final boolean inline;
	}

	public String getField(CustomWebhookBody.Embed embed, String fieldName) {
        for (CustomWebhookBody.Field field : embed.getFields()) {
            if (field.getName().equals(fieldName)) {
                return field.getValue();
            }   
        }
        return null;
    }
}

